function about_text() {
    echo "$APP_NAME $APP_VERSION\n$SIGNATURE\n\n$ABOUT_TEXT"
}

# Lista de versiones de ABOUT_TEXT en Markdown: «## version · fecha», viñetas (las de «  *», dentro
# de la anterior) en una sola linea, el tema antes de «:» en negrita y rutas y ficheros como codigo
CHANGES_MD_PY='
import re, sys

VERSION = re.compile(r"^(\d+\.\d+\.\d+) \((.+)\)$")
# Rutas (/opt/..., ~/...) y nombres de fichero: en letra de codigo (no lo de detras de https://)
CODE = re.compile(r"(?<![\w`:/])((?:~/|\./|/)[\w.*<>@+-]+(?:/[\w.*<>@+-]*)*|[\w*<>-]+(?:\.[\w*<>-]+)*"
                  r"\.(?:php|conf|cnf|deb|dmg|sql|zip|gz|desktop|policy|md|py|sh|log|pid|run|sha256)\b)")


def inline(text):
    text = CODE.sub(lambda m: "`%s`" % m.group(1), text)
    # Un punto o una coma del final de la frase queda fuera del codigo
    return re.sub(r"`([^`]*?)([.,;:]+)`", r"`\1`\2", text)


def bullet(text, depth):
    # «Tema: explicacion» o «Tema:» -> el tema en negrita
    m = re.match(r"^([^:«`/]{2,45}):(\s+(.*))?$", text)
    if m:
        text = "**%s:**%s" % (m.group(1), " " + m.group(3) if m.group(3) else "")
        return "  " * depth + "- " + text[:text.index(":**") + 3] + inline(text[text.index(":**") + 3:])
    return "  " * depth + "- " + inline(text)


def convert(plain):
    out, item, depth = [], None, 0

    def flush():
        nonlocal item
        if item is not None:
            out.append(bullet(item, depth))
            item = None

    for line in plain.split("\n"):
        m = VERSION.match(line)
        if m:
            flush()
            if out and out[-1] != "":
                out.append("")
            out.append("## %s · %s" % (m.group(1), m.group(2)))
            out.append("")
        elif line.startswith("- "):
            flush()
            item, depth = line[2:].strip(), 0
        elif line.startswith("  * "):
            flush()
            item, depth = line[4:].strip(), 1
        elif line.strip() and item is not None:
            item += " " + line.strip()
        elif not line.strip():
            flush()
        else:
            flush()
            out.append(inline(line.strip()))
    flush()
    return "\n".join(out).strip() + "\n"


sys.stdout.write(convert(sys.stdin.read()))
'

# Solo la lista de versiones con sus cambios, en Markdown (ventana "Novedades")
function changes_text() {
    echo -e "$ABOUT_TEXT" | sed -n '/^VERSIONES$/,$p' | tail -n +3 | python3 -I -c "$CHANGES_MD_PY"
}

function panel_about() {
    ui_msg "$(about_text)"
}

function panel() {
    offer_command_install

    while true; do
        local options=()

        options+=(
            "activar" "Cambiar la version activa"
            "instalar" "Instalar versiones (XAMPP completos y PHP nuevos)"
        )

        if [ -e /opt/lampp ] && [ ! -L /opt/lampp ]; then
            options+=("registrar" "Registrar el XAMPP sin gestionar de /opt/lampp (necesario para instalar XAMPP)")
        fi

        options+=(
            "estado" "Ver versiones instaladas"
            "bases" "Ver bases de datos de cada version"
            "desinstalar" "Desinstalar versiones"
        )

        local dir
        for dir in $(lampp_dirs); do
            if is_fpm_install "$dir"; then
                options+=("actualizar" "Actualizar versiones de PHP")
                break
            fi
        done

        options+=(
            "acerca" "Acerca de (version y cambios)"
            "salir" "Salir"
        )

        local header="Bienvenido al gestor de versiones LAMPP y PHP para Linux.\n"
        header+="Instala nuevas versiones de PHP o activa la que necesites.\n\n"
        # La version activa va en verde (con ventanas la pinta wt encima del texto)
        header+="Version activa: "
        local active=$(active_dir) active_text=""
        if [ -n "$active" ]; then
            active_text="lampp-${active#/opt/lampp-} (PHP $(php_version "$active"))"
            if [ "$UI" == "text" ] && [ -t 2 ]; then
                header+="\033[1;32m$active_text\033[0m"
            else
                header+=$active_text
            fi
        else
            header+="ninguna"
        fi
        [ "$DRY" -eq 1 ] && header+="\nMODO SIMULACION: no se hace ningun cambio"
        header+="\n\n¿Que quieres hacer?"

        # Firma abajo a la derecha de la cabecera, del ancho de la lista de opciones
        local cols=$(tput cols 2> /dev/null || echo 80)
        local sign_w=72
        (( sign_w > cols - 6 )) && sign_w=$(( cols - 6 ))
        if [ "$UI" == "text" ]; then
            header=$(with_signature "$header" $sign_w)
            header+="\n$(printf '%*s' $(( sign_w - ${#APP_VERSION} - 1 > 0 ? sign_w - ${#APP_VERSION} - 1 : 0 )) "")v$APP_VERSION"
        fi

        local choice
        choice=$(WT_GREEN=$active_text ui_menu "$header" "activar" "${options[@]}") || break

        case "$choice" in
            registrar) panel_register ;;
            instalar) panel_install ;;
            activar) panel_use ;;
            estado) ui_msg "$(status_text)" ;;
            bases) panel_databases ;;
            desinstalar) panel_remove ;;
            actualizar) panel_rebuild ;;
            acerca) panel_about ;;
            salir) break ;;
        esac
    done

    [ "$UI" == "whiptail" ] && clear

    return 0
}

# ===========================================================================
# Ventana (interfaz grafica con GTK 3)
# ===========================================================================

# La ventana es un programa en Python (GTK 3 y Python 3.8: funciona desde Ubuntu 20.04 sin instalar
# nada) que va dentro de este archivo, en gui_source. "nexum ventana" lo escribe en
# ~/.lvm-instalador/ventana.py y lo abre. La ventana no repite la logica del instalador: llama a
# este script con los comandos gui-* (datos en lineas "TIPO|campo|...") y con los de siempre (use,
# instalar, actualizar, desinstalar...) dentro de una pseudoterminal, para que sudo funcione igual
# que en la terminal. La contraseña la pide la ventana.
GUI_FILE="$LOG_DIR/ventana.py"
# Identificador de la ventana (el dock la relaciona con el acceso por StartupWMClass)
GUI_APP_ID="dev.hexer.LamppVersionManager"

function gui_available() {
    python3 -I -c 'import gi; gi.require_version("Gtk", "3.0"); from gi.repository import Gtk' 2> /dev/null
}

# Para la ventana: N|version|fecha|sha256|ruta del paquete .deb de nexum mas nuevo que esta
# version, y avisos (I|texto). Se busca en la ultima publicacion del repositorio de GitHub (su .deb
# y su firma se descargan a UPDATES_DIR) y en la carpeta de descargas (el Centro de aplicaciones no
# ofrece actualizar un .deb suelto). Solo cuando se pide (Buscar actualizaciones): se instala como
# root, y cualquier web puede dejar un fichero en Descargas. Solo vale un paquete tuyo, sin enlaces,
# firmado con la clave de UPDATE_KEY_FPR (su .sig al lado) y que solo lleve los ficheros de
# nexum, de root y con sus permisos (755 o 644).
UPDATES_DIR="$LOG_DIR/actualizaciones"
PACKAGE_FILES_PY='
import posixpath, sys, tarfile
files = {"opt/nexum/nexum.sh", "opt/nexum/nexum-actualizar",
         "opt/nexum/nexum-stack-firma.gpg",
         "usr/share/applications/nexum.desktop",
         "usr/share/icons/hicolor/256x256/apps/nexum.png",
         "usr/share/polkit-1/actions/io.github.mariomasku.nexum.policy"}
dirs = {""}
for f in files:
    parts = f.split("/")
    for i in range(1, len(parts)):
        dirs.add("/".join(parts[:i]))
try:
    with tarfile.open(fileobj=sys.stdin.buffer, mode="r|") as tar:
        for m in tar:
            name = (m.name[2:] if m.name.startswith("./") else m.name).rstrip("/")
            name = "" if name == "." else name
            if name.startswith("/") or ".." in name.split("/"):
                sys.exit(1)
            if not ((m.isdir() and name in dirs) or (m.isreg() and name in files)):
                sys.exit(1)
            exe = name in ("opt/nexum/nexum.sh", "opt/nexum/nexum-actualizar")
            if m.uid != 0 or m.gid != 0 or m.uname not in ("root", "") or m.gname not in ("root", "") or (m.mode & 0o7777) != (0o755 if m.isdir() or exe else 0o644):
                sys.exit(1)
except tarfile.TarError:
    sys.exit(1)
'
# Ultima publicacion de GitHub (JSON de la API en la entrada): version|fecha|url del .deb|url del
# .sig. Sin borradores ni versiones de prueba, y las descargas solo de esa publicacion
RELEASE_PY='
import json, re, sys
repo = sys.argv[1]
try:
    r = json.load(sys.stdin)
except ValueError:
    sys.exit(1)
if not isinstance(r, dict) or not isinstance(r.get("assets"), list):
    sys.exit(1)
tag = r.get("tag_name") or ""
m = re.fullmatch(r"v([0-9]{1,4}(\.[0-9]{1,4}){1,3})", tag)
when = r.get("published_at") or ""
if not m or r.get("draft") or r.get("prerelease") or not re.fullmatch(r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z", when):
    sys.exit(1)
deb = "nexum_%s_all.deb" % m.group(1)
base = "https://github.com/%s/releases/download/%s/" % (repo, tag)
urls = {a.get("name"): a.get("browser_download_url") for a in r["assets"] if isinstance(a, dict)}
if urls.get(deb) != base + deb or urls.get(deb + ".sig") != base + deb + ".sig":
    sys.exit(1)
print("%s|%s|%s|%s" % (m.group(1), when, base + deb, base + deb + ".sig"))
'

# ¿Esta <paquete> firmado con la clave de las actualizaciones? (la firma, en <paquete>.sig)
function update_signed() {
    local dir status=""

    [ -f "$1.sig" ] && [ ! -L "$1.sig" ] && command -v gpgv > /dev/null || return 1
    dir=$(mktemp -d) || return 1
    base64 -d <<< "$UPDATE_KEY_B64" > "$dir/firma.gpg" 2> /dev/null \
        && status=$(GNUPGHOME=$dir gpgv --status-fd 1 --keyring "$dir/firma.gpg" "$1.sig" "$1" 2> /dev/null)
    rm -rf "$dir"

    grep -q "^\[GNUPG:\] VALIDSIG $UPDATE_KEY_FPR " <<< "$status"
}

# Si la ultima publicacion de GitHub es mas nueva que esta version, descarga su .deb y su firma a
# UPDATES_DIR (solo tuya; el .deb con la fecha de la publicacion). Si no se puede, lo dice (I|...)
function github_update() {
    local json code rel v when deb_url sig_url f
    local get=(curl -q --proto =https --proto-redir =https -fsSL --max-time 60)

    # (sin -f: un 404 es que aun no hay ninguna publicacion, no un fallo de la conexion)
    json=$(curl -q --proto =https --proto-redir =https -sSL --max-time 30 --max-filesize 1048576 \
        -H "Accept: application/vnd.github+json" -w '\n%{http_code}' \
        "https://api.github.com/repos/$UPDATE_REPO/releases/latest" 2> /dev/null)
    code=${json##*$'\n'} json=${json%$'\n'*}
    case "$code" in
        200) ;;
        404) echo "I|Todavía no hay ninguna versión publicada en GitHub"; return 0 ;;
        *) echo "I|No se ha podido consultar GitHub (¿sin conexión?): solo se ha buscado en Descargas"; return 0 ;;
    esac
    rel=$(python3 -I -c "$RELEASE_PY" "$UPDATE_REPO" <<< "$json") \
        || { echo "I|La última publicación de GitHub no trae un paquete de Nexum Dev Stack con su firma"; return 0; }
    IFS='|' read -r v when deb_url sig_url <<< "$rel"
    dpkg --compare-versions "$v" gt "$APP_VERSION" || return 0

    [ -L "$UPDATES_DIR" ] && { echo "I|$UPDATES_DIR es un enlace: no se descarga nada ahí"; return 0; }
    mkdir -p -m 700 "$UPDATES_DIR" && chmod 700 "$UPDATES_DIR" || return 0
    f=$UPDATES_DIR/nexum_${v}_all.deb
    # Ya descargada y bien firmada: no se vuelve a bajar
    update_signed "$f" && return 0
    rm -f -- "$UPDATES_DIR"/nexum_* "$UPDATES_DIR"/lvm-instalador_*
    if ! "${get[@]}" --max-filesize 52428800 -o "$f.part" "$deb_url" 2> /dev/null \
            || ! "${get[@]}" --max-filesize 65536 -o "$f.sig" "$sig_url" 2> /dev/null; then
        rm -f -- "$f.part" "$f.sig"
        echo "I|No se ha podido descargar la $v de GitHub"
        return 0
    fi
    mv -f -- "$f.part" "$f"
    touch -d "$when" "$f" 2> /dev/null
    if ! update_signed "$f"; then
        rm -f -- "$f" "$f.sig"
        echo "I|La $v de GitHub no está firmada por quien hace el programa: no se ofrece"
    fi

    return 0
}

function gui_package() {
    local dir f v best="" best_v=$APP_VERSION real unsigned=""

    command -v dpkg-deb > /dev/null || return 0
    github_update
    for dir in "$UPDATES_DIR" "$(xdg-user-dir DOWNLOAD 2> /dev/null)" "$HOME/Descargas" "$HOME/Downloads"; do
        [ -d "$dir" ] || continue
        for f in "$dir"/nexum_*_all.deb; do
            [ -f "$f" ] && [ ! -L "$f" ] && [ -O "$f" ] || continue
            [ "$(dpkg-deb -f "$f" Package 2> /dev/null)" == "nexum" ] || continue
            # Solo los ficheros de nexum, normales (sin enlaces ni especiales), y firmado:
            # lo mismo que comprueba como root nexum-actualizar antes de instalarlo
            dpkg-deb --fsys-tarfile "$f" 2> /dev/null | python3 -I -c "$PACKAGE_FILES_PY" || continue
            v=$(dpkg-deb -f "$f" Version 2> /dev/null)
            [ -n "$v" ] && dpkg --compare-versions "$v" gt "$best_v" || continue
            if update_signed "$f"; then
                best=$f best_v=$v
            else
                unsigned=$f
            fi
        done
    done
    # Uno sin firma (hecho en este equipo con empaquetar-deb.sh, por ejemplo) solo en la terminal
    [ -z "$best" ] && [ -n "$unsigned" ] \
        && echo "I|$(basename "$unsigned") no lleva la firma de quien publica el programa. Si es tuyo, instálalo en la terminal: sudo apt install $unsigned"
    if [ -n "$best" ]; then
        real=$(readlink -f "$best")
        echo "N|$best_v|$(date -r "$real" '+%d/%m/%Y %H:%M')|$(sha256sum "$real" | cut -d' ' -f1)|$real"
    fi

    return 0
}

function gui_open() {
    if ! gui_available; then
        echo "La ventana necesita GTK 3 para Python. Instalalo con: sudo apt install python3-gi gir1.2-gtk-3.0"
        echo "Mientras tanto puedes usar el panel de la terminal: nexum"

        return 1
    fi

    if [ -z "$DISPLAY" ] && [ -z "$WAYLAND_DISPLAY" ]; then
        echo "No hay sesion grafica. Usa el panel de la terminal: nexum"

        return 1
    fi

    mkdir -p -m 700 "$LOG_DIR"
    # El codigo de la ventana va por la entrada de python, sin fichero en tu carpeta que otro
    # programa pudiera cambiar entre que se escribe y se abre (el ventana.py de antes se borra)
    rm -f "$GUI_FILE" "$GUI_FILE.tmp"
    cmp -s "$ICON_FILE" <(base64 -d <<< "$ICON_PNG_B64" 2> /dev/null) || install_icon
    [ "$DRY" -eq 0 ] && update_launchers
    # La pagina de web.local sin proyecto, al dia tras una actualizacion (solo si se puede escribir
    # sin contraseña: si no, al desmontar el proximo proyecto)
    [ -w "$HTDOCS_DIR/$EMPTY_PROJECT/index.html" ] && empty_page "$HTDOCS_DIR/$EMPTY_PROJECT" > /dev/null 2>&1

    # Abierta desde el menu no hay terminal donde ver los errores: van a ventana.log (vacio al abrirla y en
    # modo de añadir: si Limpieza lo vacia con la ventana abierta, sigue escribiendo al principio)
    [ -t 2 ] || { : > "$LOG_DIR/ventana.log"; exec 2>> "$LOG_DIR/ventana.log"; }
    # Con su ruta: el PATH de la sesion puede llevar delante carpetas tuyas (~/.local/bin)
    LVM_SIMULAR=$DRY exec /usr/bin/python3 -I - "$SELF" < <(gui_source)
}

# Datos de la ventana:
#   M|nombre|version|firma
#   A|activa|en marcha (1/0)|/opt/lampp sin registrar (1/0)|binarios x86_64 (1/0)|acceso del menu (1/0)
#   V|carpeta|php|apache|mariadb|proftpd|perl|phpmyadmin|tipo|bases de|motivo para no desinstalar
#   D|carpeta|base de datos|fecha|tipo (i: importada con nexum, c: ultimo cambio de tablas)
#   Z|procesos de LAMPP que sobran en memoria (de otras versiones)
#   Y|version montada|bytes del registro de errores: sus tablas del sistema de MariaDB son antiguas
#   R|carpeta|ok, parche o vulnerable|texto     PHP2Shell en cada version (php2shell_state)
# gui-vuelta: lo que la ventana pregunta cada 20 s (gui-datos, gui-hosts, gui-servicios y gui-proyectos) en
# una sola orden: el script se lee una vez y no cuatro (unos 200 ms cada una). Cada parte, en su subshell
# (un exit no corta las demas), va detras de una linea «@@<orden>|<codigo de salida>»
function gui_round() {
    local part out rc
    for part in gui-datos:gui_data gui-hosts:gui_hosts gui-servicios:gui_services gui-proyectos:gui_projects; do
        out=$("${part#*:}" 2>&1 < /dev/null)
        rc=$?
        echo "@@${part%%:*}|$rc"
        [ -n "$out" ] && printf '%s\n' "$out"
    done
    return 0
}

function gui_data() {
    local active=$(active_dir) dir name owner blocker kind dates=()

    echo "M|$APP_NAME|$APP_VERSION|$SIGNATURE"
    echo "A|${active#/opt/lampp-}|$(lampp_running && echo 1 || echo 0)|$([ -e /opt/lampp ] && [ ! -L /opt/lampp ] && echo 1 || echo 0)|$(native_binaries && echo 1 || echo 0)|$(launcher_exists && echo 1 || echo 0)"
    echo "H|$ACTIVE_VHOSTS|$HOSTS_FILE"
    # Correo de pruebas: E|Mailpit instalado (1/0)|encendido (1/0)|modo de WordPress|Mailpit en marcha
    # (1/0)|version instalada|direccion de su web|version que instala el gestor. Si la version activa
    # esta en marcha y Mailpit no (se ha cerrado la sesion, por ejemplo), se arranca
    [ "$DRY" -eq 0 ] && mailpit_sync --suave > /dev/null 2>&1
    echo "E|$(mailpit_installed && echo 1 || echo 0)|$(mail_on && echo 1 || echo 0)|$(mail_wp_mode)|$([ -n "$(mailpit_pid)" ] && echo 1 || echo 0)|$(mailpit_installed_version)|$MAIL_UI_URL|$MAILPIT_VERSION"
    # Procesos de LAMPP en memoria que no son de la version montada
    local stray=$(stray_summary)
    [ -n "$stray" ] && echo "Z|$stray"
    # Vhosts de proyectos cuya carpeta ya no esta en htdocs: W|carpeta|dominios (Apache avisa de cada uno al
    # arrancar)
    local vh
    vh=$(readlink -f "$ACTIVE_VHOSTS" 2> /dev/null)
    [ -n "$vh" ] && [ -f "$vh" ] && python3 -I -c "$VHOSTS_ORPHANS_PY" "$vh" "$HTDOCS_DIR" lista 2> /dev/null
    # Servicios de la version montada a los que se puede entrar desde otros equipos de la red
    local exposed=$(exposed_summary)
    [ -n "$exposed" ] && echo "N|$exposed"
    # Versiones que, si se arrancan a mano, quedarian abiertas a la red (o con el FTP de fabrica)
    local open_versions=$(unsecured_versions)
    [ -n "$open_versions" ] && echo "U|$open_versions"
    # Tablas del sistema de MariaDB antiguas en la version montada (llenan su registro de errores)
    if db_system_outdated; then
        local err_log=$(db_error_log "$active")
        echo "Y|${active#/opt/lampp-}|$([ -n "$err_log" ] && stat -c %s "$err_log" 2> /dev/null || echo 0)"
    fi
    # Certificados de proyectos en los que confia todo el equipo: C|dominio|motivo y A|CA
    # y G|dominio: proyectos https cuyo certificado propio aun no acepta el navegador, y Q|dominio:
    # los que acepta y ya no deberia (una tienda que ya no esta falseada)
    cert_audit | awk -F'|' '$1 == "C" { print "C|" $2 "|" $5 } $1 == "A" && !seen[$2]++ { print "W|" $2 }
        $1 == "T" && $5 == "0" { print "G|" $2 } $1 == "U" && !gone[$2]++ { print "Q|" $2 }
        $1 == "S" { n = split($2, a, "/"); print "C|" a[n] " (sin usar)|sistema" }'

    for dir in $(lampp_dirs); do
        name=${dir#/opt/lampp-}
        kind=XAMPP
        is_fpm_install "$dir" && kind=sobre
        is_stack_install "$dir" && kind=propia
        owner=$(data_owner "$dir")
        owner=${owner:-$name}
        blocker=$(remove_blocker "$name")
        blocker=${blocker//\\n/ }
        local fields=$(stack_fields "$dir")
        echo "V|$name|$fields|$kind|$owner|${blocker//|/ }"
        echo "R|$name|$(php2shell_state "$dir" "${fields%%|*}")"
        dates+=("$name" "/opt/lampp-$owner/var/mysql")
    done
    # (las fechas de las BBDD de todas las versiones en un solo python3)
    [ ${#dates[@]} -gt 0 ] && db_dates --varias "${dates[@]}"
    return 0
}

# Ramas de PHP para instalar (consulta php.net):
#   B|rama|ultimo parche|con soporte (1/0)|MariaDB|Perl|estado|carpeta|estado en php.net|fin del soporte
#     activo|fin de los parches de seguridad (de php_branch_states; vacios si no se pudo consultar)
#     estado: nueva (se instala en lampp-<carpeta>), instalada (en lampp-<carpeta>),
#     existe (ya hay otra cosa en esa carpeta)
#     ... |fecha del ultimo parche (AAAA-MM-DD)|seguridad (1 si php.net lo marca como parche de seguridad)
#   X|carpeta|release|php|instalado (1/0)          (catalogo de XAMPP, solo en equipos x86_64)
function gui_branches() {
    local releases=$(php_releases) supported=$(php_supported) branch latest have folder state sup b
    local states=$(php_branch_states) st all=$(php_all_releases) date sec

    if [ -z "$releases" ]; then
        echo "ERROR|No se ha podido consultar php.net. Comprueba la conexion a internet."

        return 1
    fi

    while read -r branch latest; do
        read -r -a b <<< "$(stack_branches "$branch")"
        sup=0
        grep -qxF "$branch" <<< "$supported" && sup=1
        have=$(php_installed_in "$latest")
        if [ -n "$have" ]; then
            state=instalada folder=${have#/opt/lampp-}
        else
            folder=$(item_folder "$(php_item "$latest" "$latest")")
            state=nueva
            [ -e "${TEST_DIR:-/opt}/lampp-$folder" ] && state=existe
        fi
        st=$(grep "^$branch|" <<< "$states" | cut -d'|' -f2-)
        # (siempre tres campos, aunque no se haya podido consultar: van despues la fecha y la marca)
        [ -z "$st" ] && st="||"
        read -r _ date sec <<< "$(awk -v v="$latest" '$1 == v {print; exit}' <<< "$all")"
        [ "$sec" == "seguridad" ] && sec=1 || sec=0
        echo "B|$branch|$latest|$sup|${b[1]}|${b[3]}|$state|$folder|$st|${date:--}|$sec"
    done <<< "$releases"

    if native_binaries; then
        local entry release php
        for entry in "${XAMPP_CATALOG[@]}"; do
            IFS='|' read -r folder release php _ <<< "$entry"
            echo "X|$folder|$release|$php|$([ -e "/opt/lampp-$folder" ] && echo 1 || echo 0)"
        done
    fi
}

# Fecha de publicacion en php.net del PHP de cada version instalada: F|carpeta|php|AAAA-MM-DD
function gui_php_dates() {
    local all=$(php_all_releases) dir php date
    [ -n "$all" ] || return 1
    for dir in $(lampp_dirs); do
        php=$(stack_fields "$dir" | cut -d'|' -f1)
        [[ "$php" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]] || continue
        date=$(awk -v v="$php" '$1 == v { print $2; exit }' <<< "$all")
        [[ "$date" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]] && echo "F|${dir#/opt/lampp-}|$php|$date"
    done
    return 0
}

# ===========================================================================
# Docker (sin root): proyectos con cualquier version de PHP en contenedores
# ===========================================================================
# Cada proyecto en Docker lleva su PHP-FPM, su MariaDB (con una copia de su BBDD) y su phpMyAdmin en
# contenedores de Docker sin root: corren con tu usuario, asi que ni un proyecto ni Docker pueden
# hacerse administradores del equipo. La web la sigue sirviendo el Apache de la version LAMPP activa,
# por su dominio (<carpeta>.docker.local, http y https con su certificado), con los .htaccess de
# siempre: los .php los pasa al PHP-FPM del contenedor por un socket de una carpeta solo tuya. Dentro
# del contenedor el proyecto esta en la misma ruta que ve Apache (/opt/lampp/htdocs/<carpeta>), y su
# wp-config.php (o parameters.php / settings.inc.php) se sustituye por uno con la BBDD del contenedor:
# el del proyecto no se toca, y la carpeta se puede seguir usando con LAMPP a la vez.
# (LVM_DOCKER, LVM_DOCKER_DIR y LVM_DOCKER_HOST solo para pruebas)
DOCKER_DIR=${LVM_DOCKER_DIR:-$HOME/.lvm-instalador/docker}
DOCKER_BIN=${LVM_DOCKER:-/usr/bin/docker}
# Versiones que se ofrecen: imagenes oficiales php:<version>-fpm y mariadb:<version> de Docker Hub
DOCKER_PHP_VERSIONS="8.5 8.4 8.3 8.2 8.1 8.0 7.4 7.3 7.2 7.1 7.0 5.6"
DOCKER_MARIADB_VERSIONS="11.8 11.4 10.11 10.6 10.5 10.4"
DOCKER_PMA_IMAGE="phpmyadmin:5.2"
# Extensiones de PHP de las imagenes (las que piden WordPress y PrestaShop)
DOCKER_PHP_EXT="bcmath exif gd intl mysqli opcache pdo_mysql soap zip"
# Paquetes de Ubuntu para Docker sin root (el demonio del sistema, con root, se deja apagado)
DOCKER_PACKAGES="docker.io docker-compose-v2 rootlesskit uidmap slirp4netns dbus-user-session"
# Puertos de 127.0.0.1 para el phpMyAdmin de cada proyecto (uno por proyecto, desde este)
DOCKER_PMA_PORT=28080

# Docker sin root siempre por su socket: nunca el del demonio del sistema
function docker_sock() {
    echo "${LVM_DOCKER_HOST:-unix://${XDG_RUNTIME_DIR:-/run/user/$(id -u)}/docker.sock}"
}

# Configuracion del cliente de Docker: una carpeta del gestor (solo tuya) y no ~/.docker, donde
# cualquier programa tuyo puede dejar un complemento (cli-plugins/docker-*) o un ayudante de claves
# (credsStore) que docker ejecutaria. Cada vez sin complementos propios y con un config.json vacio:
# docker compose y buildx son los del sistema (/usr/libexec/docker/cli-plugins)
DOCKER_CONFIG_DIR="$LOG_DIR/docker-config"
function docker_config_dir() {
    local cfg=$DOCKER_CONFIG_DIR
    if [ -L "$cfg" ] || { [ -e "$cfg" ] && [ ! -O "$cfg" ]; }; then
        echo "$cfg no es una carpeta tuya: no se usa Docker" >&2
        return 1
    fi
    mkdir -p -m 700 "$cfg" && chmod 700 "$cfg" || return 1
    [ -e "$cfg/cli-plugins" ] && rm -rf "$cfg/cli-plugins"
    [ "$(cat "$cfg/config.json" 2> /dev/null)" == "{}" ] || { rm -f "$cfg/config.json"; echo "{}" > "$cfg/config.json"; }
    chmod 600 "$cfg/config.json"
    echo "$cfg"
}

# docker como git (no_tty): en su propia sesion, sin la terminal de la tarea (sus complementos no
# pueden usar el permiso de sudo recordado ni leer lo que se escribe en ella). Su salida y sus
# errores pasan por tuberias; la entrada, solo si no es la terminal (una carga de BBDD por tuberia)
function dk() {
    local cfg
    cfg=$(docker_config_dir) || return 1
    ( [ -t 0 ] && exec < /dev/null
      set -o pipefail
      DOCKER_HOST=$(docker_sock) DOCKER_CONFIG=$cfg /usr/bin/python3 -I -c "$NO_TTY_PY" "$DOCKER_BIN" "$@" \
          2> >(cat >&2) | cat )
}

# ¿Responde Docker sin root? (0 si si)
function docker_ready() {
    [ -x "$DOCKER_BIN" ] || return 1
    local info
    info=$(dk info --format '{{json .SecurityOptions}}' 2> /dev/null) || return 1
    [[ "$info" == *rootless* ]]
}

# Nombre corto de un proyecto: el de su carpeta en minusculas, solo letras, numeros y - (va en el
# nombre de los contenedores y en el dominio)
function docker_slug() {
    local s
    s=$(tr 'A-Z' 'a-z' <<< "$1" | sed -E 's/[^a-z0-9]+/-/g; s/^-+//; s/-+$//' | cut -c1-40 | sed -E 's/-+$//')
    [ -n "$s" ] && echo "$s"
}

# Carpeta del socket de PHP-FPM de un proyecto: en /run/user/<tu uid> (solo tuya, en memoria y corta:
# la ruta de un socket no puede pasar de 107 caracteres)
function docker_run_dir() {
    echo "${XDG_RUNTIME_DIR:-/run/user/$(id -u)}/nexum/$1"
}

function docker_valid_slug() {
    [[ "$1" =~ ^[a-z0-9]([a-z0-9-]{0,38}[a-z0-9])?$ ]]
}

# Valor de proyecto.conf (lineas CLAVE=valor que escribe el gestor)
function docker_conf() {
    local f=$DOCKER_DIR/$1/proyecto.conf
    [ -f "$f" ] && [ ! -L "$f" ] || return 1
    awk -F= -v k="$2" '$1 == k { sub(/^[^=]*=/, ""); print; exit }' "$f"
}

# Proyectos en Docker (nombres cortos validos con su proyecto.conf)
function docker_projects() {
    local d
    [ -d "$DOCKER_DIR" ] || return 0
    for d in "$DOCKER_DIR"/*/; do
        d=$(basename "$d")
        docker_valid_slug "$d" && [ -f "$DOCKER_DIR/$d/proyecto.conf" ] && echo "$d"
    done
}

# Estado de los contenedores de un proyecto: marcha (todos), parado (ninguno), parcial o nuevo
function docker_state() {
    local out up=0 total=0 state
    out=$(dk ps -a --filter "label=com.docker.compose.project=nexum-$1" --format '{{.State}}' 2> /dev/null) || { echo "?"; return 0; }
    while read -r state; do
        [ -z "$state" ] && continue
        total=$((total + 1))
        [ "$state" == running ] && up=$((up + 1))
    done <<< "$out"
    if [ $total -eq 0 ]; then echo nuevo
    elif [ $up -eq $total ]; then echo marcha
    elif [ $up -eq 0 ]; then echo parado
    else echo parcial
    fi
}

# Para la ventana:
#   S|instalado (1/0)|Docker sin root responde (1/0)|version|LAMPP activa en marcha (1/0)|Docker o
#     containerd del sistema (con root) en marcha (1/0)
#   V|versiones de PHP|versiones de MariaDB
#   P|nombre|carpeta|php|mariadb|dominio|estado|bbdd|puerto de phpMyAdmin (de antes; en los del Apache de
#     Docker: web)|modo (web o nada)|version elegida (tienda)|tipo (wp, ps u otro)|versiones de PHP (espacios)
#   W|direccion|http|https|estado del Apache de Docker (marcha, parado, nuevo)|puertos permitidos (1/0)
#   C|contenedor|imagen|estado (running, exited...)|estado en texto|puertos|proyecto de compose
#     (todos los contenedores de tu Docker, para la consola de la pestaña)
#   I|imagen:etiqueta|tamaño|creada  y  O|volumen|driver   (imagenes y volumenes de tu Docker)
function gui_docker() {
    local installed=0 ready=0 version="" p
    [ -x "$DOCKER_BIN" ] && installed=1
    if [ $installed -eq 1 ] && docker_ready; then
        ready=1
        version=$(dk version --format '{{.Server.Version}}' 2> /dev/null | tr -cd '0-9.')
        # (con proyectos del Apache de Docker, que el temporizador de los que no tienen visitas este puesto:
        # los de antes de la 1.56.8 / 1.40.1 no lo tenian)
        [ -n "$(docker_web_projects)" ] && docker_idle_ensure
    fi
    [ $ready -eq 1 ] && docker_fix_restart > /dev/null
    echo "S|$installed|$ready|$version|$(lampp_running && echo 1 || echo 0)|$(systemctl is-active -q docker.service docker.socket containerd.service 2> /dev/null && echo 1 || echo 0)"
    echo "V|$DOCKER_PHP_VERSIONS|$DOCKER_MARIADB_VERSIONS"
    for p in $(docker_projects); do
        if docker_web_project "$p"; then
            echo "P|$p|$(docker_conf "$p" CARPETA)|$(docker_conf "$p" ACTIVA)|$(docker_conf "$p" MARIADB)|$(docker_conf "$p" DOMINIO)|$([ $ready -eq 1 ] && docker_state "$p" || echo "?")|$(docker_conf "$p" BBDD)|web|web|$(docker_conf "$p" ACTIVA)|$(docker_conf "$p" TIPO)|$(docker_conf "$p" PHP)|$(docker_conf "$p" LAMPP_BD)"
        else
            echo "P|$p|$(docker_conf "$p" CARPETA)|$(docker_conf "$p" PHP)|$(docker_conf "$p" MARIADB)|$(docker_conf "$p" DOMINIO)|$([ $ready -eq 1 ] && docker_state "$p" || echo "?")|$(docker_conf "$p" BBDD)|$(docker_conf "$p" PUERTO_PMA)"
        fi | tr -d '\000-\010\013-\037'
    done
    echo "W|$(docker_web_get IP)|$(docker_web_get HTTP)|$(docker_web_get HTTPS)|$([ $ready -eq 1 ] && docker_web_state || echo "?")|$(docker_web_ports_ok && echo 1 || echo 0)|$(docker_web_tld)|$(docker_dns_on && echo 1 || echo 0)"
    if [ $ready -eq 1 ]; then
        # (al final, el ID corto del contenedor)
        dk ps -a --format '{{.Names}}|{{.Image}}|{{.State}}|{{.Status}}|{{.Ports}}|{{.Label "com.docker.compose.project"}}|{{.ID}}' 2> /dev/null \
            | tr -d '\000-\010\013-\037' | awk -F'|' -v OFS='|' 'NF == 7 && $7 ~ /^[0-9a-f]+$/ {
                # (el puente hasta la BBDD de una version LAMPP no es de compose: va con su nombre)
                if ($6 == "" && $1 ~ /^nexum-lampp-bd-[0-9]+-[0-9]+(-[0-9]+)?$/) $6 = $1
                print "C|" $0 }'
        # (imagen, etiqueta e ID corto por separado)
        dk images --format '{{.Repository}}|{{.Tag}}|{{.ID}}|{{.Size}}|{{.CreatedSince}}' 2> /dev/null \
            | tr -d '\000-\010\013-\037' | awk -F'|' 'NF == 5 && $3 ~ /^[0-9a-f]+$/ { print "I|" $0 }'
        dk volume ls --format '{{.Name}}|{{.Driver}}' 2> /dev/null \
            | tr -d '\000-\010\013-\037' | awk -F'|' 'NF == 2 { print "O|" $0 }'
    fi
    return 0
}

# Uso de CPU y memoria de los contenedores en marcha (tarda un par de segundos: docker stats mide):
#   T|nucleos|memoria del equipo en bytes   y   K|contenedor|% de CPU|memoria usada (texto de Docker)
function gui_docker_stats() {
    docker_ready || return 0
    echo "T|$(nproc 2> /dev/null || echo 1)|$(awk '/^MemTotal:/ { print $2 * 1024 }' /proc/meminfo)"
    dk stats --no-stream --format '{{.Name}}|{{.CPUPerc}}|{{.MemUsage}}' 2> /dev/null \
        | tr -d '\000-\010\013-\037' | awk -F'|' 'NF == 3 { print "K|" $0 }'
    return 0
}

# docker-contenedor arrancar|parar|reiniciar|registros|borrar <contenedor>: uno solo de los contenedores de
# un proyecto del gestor (nexum-<proyecto>-php|db|pma-N), no cualquiera de tu Docker
function docker_container_action() {
    local action=$1 name=$2
    if ! [[ "$name" =~ ^nexum-[a-z0-9]([a-z0-9-]{0,38}[a-z0-9])?-(php|db|pma)-[0-9]{1,3}$ \
            || "$name" =~ ^nexum-[a-z0-9]([a-z0-9-]{0,38}[a-z0-9])?-php[0-9]{2}$ \
            || "$name" =~ ^nexum-(web|pma|mariadb-[0-9]{1,2}-[0-9]{1,2}|lampp-bd-[0-9]{1,2}-[0-9]{1,2}(-[0-9]{1,3})?)$ ]]; then
        echo "Contenedor no valido: $name (solo los de los proyectos en Docker del gestor)"
        return 1
    fi
    case $action in
        arrancar)
            if [[ "$name" =~ ^nexum-lampp-bd-([0-9]{1,2})-([0-9]{1,2})(-([0-9]{1,3}))?$ ]]; then
                local f=${BASH_REMATCH[1]}.${BASH_REMATCH[2]}${BASH_REMATCH[4]:+.${BASH_REMATCH[4]}}
                lampp_bd_up "$f" && lampp_bd_bridge_up "$f"
                return
            fi
            run dk start "$name" ;;
        parar)
            docker_shared_warn "$name"
            run dk stop "$name" ;;
        reiniciar) run dk restart "$name" ;;
        registros) dk logs --tail 200 "$name" ;;
        # (se quita el contenedor; los datos de la BBDD siguen en su volumen y, al arrancar el
        # proyecto, se vuelve a crear. Para quitarlo todo: docker-borrar <proyecto>)
        borrar) run dk rm -f "$name" ;;
        *) echo "Uso: nexum docker-contenedor arrancar|parar|reiniciar|registros|borrar <contenedor>"; return 1 ;;
    esac
}

# docker-imagenes borrar <ID|imagen:etiqueta> | descargar <imagen:etiqueta>: las imagenes de tu Docker.
# Se borra sin -f: si la usa algun contenedor (aunque este parado), Docker no la borra y lo dice
function docker_image_action() {
    local action=$1 ref=$2
    case $action in
        borrar)
            [[ "$ref" =~ ^[0-9a-f]{12,64}$ || "$ref" =~ ^[a-z0-9][a-z0-9._/-]{0,127}:[A-Za-z0-9_][A-Za-z0-9_.-]{0,127}$ ]] \
                || { echo "Imagen no valida: $ref"; return 1; }
            run dk image rm "$ref" ;;
        descargar)
            [[ "$ref" =~ ^[a-z0-9][a-z0-9._/-]{0,127}:[A-Za-z0-9_][A-Za-z0-9_.-]{0,127}$ ]] \
                || { echo "Imagen no valida: $ref (imagen:etiqueta)"; return 1; }
            # (las nexum-php:X son del gestor y no estan en Docker Hub: se rehacen con docker-imagen)
            [[ "$ref" == nexum-* ]] && { echo "$ref es del gestor: se rehace con «Actualizar imagen» de su proyecto"; return 1; }
            run dk pull "$ref" ;;
        *) echo "Uso: nexum docker-imagenes borrar <ID|imagen:etiqueta> | descargar <imagen:etiqueta>"; return 1 ;;
    esac
}

# docker-volumen-borrar <volumen>: Docker no borra uno que use algun contenedor (aunque este parado)
function docker_volume_remove() {
    [[ "$1" =~ ^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$ ]] || { echo "Volumen no valido: $1"; return 1; }
    run dk volume rm "$1"
}

# Los contenedores de los proyectos no arrancan solos al encender el equipo (se arrancan desde la
# pestaña Docker). Hasta la 1.54 se creaban con restart: unless-stopped y Docker los volvia a arrancar
# al iniciar la sesion: se cambia en sus compose.yaml y en los contenedores que ya existen (sin pararlos)
function docker_fix_restart() {
    local p dir
    for p in $(docker_projects); do
        dir=$DOCKER_DIR/$p
        docker_web_project "$p" && continue
        grep -q '^    restart: unless-stopped$' "$dir/compose.yaml" 2> /dev/null || continue
        [ "$DRY" -eq 1 ] && { echo "  [simulacion] $p: sin arranque automatico"; continue; }
        sed -i 's/^    restart: unless-stopped$/    restart: "no"/' "$dir/compose.yaml"
        dk ps -aq --filter "label=com.docker.compose.project=nexum-$p" 2> /dev/null \
            | xargs -r "$DOCKER_BIN" -H "$(docker_sock)" update --restart=no > /dev/null 2>&1
    done
    docker_fix_pma
    docker_fix_cache
    return 0
}

# Hasta la 1.55.9 la cache de una tienda PrestaShop 1.7+ en Docker (var/cache) iba en la carpeta del
# proyecto, la misma que usa LAMPP: guardaba alli la BBDD del contenedor (db) y la tienda dejaba de
# funcionar en LAMPP. Se pasa a un volumen del contenedor; se aplica al volver a crear su contenedor
# de PHP (al arrancar el proyecto, o ya, si esta en marcha)
function docker_fix_cache() {
    local p dir folder
    for p in $(docker_projects); do
        dir=$DOCKER_DIR/$p
        folder=$(docker_conf "$p" CARPETA)
        docker_web_project "$p" && continue
        grep -q '/app/config/parameters.php:ro"$' "$dir/compose.yaml" 2> /dev/null || continue
        grep -q '/var/cache"$' "$dir/compose.yaml" && continue
        [ "$DRY" -eq 1 ] && { echo "  [simulacion] $p: la cache de PrestaShop en su volumen"; continue; }
        python3 -I - "$dir/compose.yaml" "$folder" <<'PY' || continue
import sys
path, folder = sys.argv[1], sys.argv[2]
lines = open(path, encoding="utf-8").read().split("\n")
out = []
for line in lines:
    out.append(line)
    if line.endswith('/app/config/parameters.php:ro"'):
        out.append('      - "cache:/opt/lampp/htdocs/%s/var/cache"' % folder)
    if line == "  db: {}":
        out.append("  cache: {}")
open(path + ".nuevo", "w", encoding="utf-8").write("\n".join(out))
PY
        mv -f "$dir/compose.yaml.nuevo" "$dir/compose.yaml" || continue
        if [ "$(docker_state "$p")" == marcha ]; then
            dk compose --project-directory "$dir" -f "$dir/compose.yaml" up -d php > /dev/null 2>&1
        fi
    done
    return 0
}

# Hasta la 1.54.0 el phpMyAdmin de cada proyecto entraba solo como root (PMA_USER y PMA_PASSWORD):
# cualquier programa o web que llegara a su puerto tenia la BBDD entera. Ahora enseña su pantalla
# de acceso (usuario root y la contraseña de la BBDD, que la ventana copia). Se quita de sus
# compose.yaml; el contenedor se rehace al arrancar el proyecto (o ya, si esta en marcha)
function docker_fix_pma() {
    local p dir
    for p in $(docker_projects); do
        dir=$DOCKER_DIR/$p
        docker_web_project "$p" && continue
        grep -qE '^      PMA_(USER|PASSWORD):' "$dir/compose.yaml" 2> /dev/null || continue
        [ "$DRY" -eq 1 ] && { echo "  [simulacion] $p: phpMyAdmin con su pantalla de acceso"; continue; }
        sed -i -E '/^      PMA_(USER|PASSWORD):/d' "$dir/compose.yaml" || continue
        if [ "$(docker_state "$p")" == marcha ]; then
            dk compose --project-directory "$dir" -f "$dir/compose.yaml" up -d pma > /dev/null 2>&1
        fi
    done
    return 0
}

# docker-imagen <nombre>: rehace la imagen de PHP de un proyecto (nexum-php:<version>) con lo ultimo
# de Docker Hub (--pull, sin la cache: con los parches de seguridad de PHP y del sistema de la
# imagen) y vuelve a crear su contenedor de PHP. La BBDD y la configuracion no se tocan. Los demas
# proyectos con esa version de PHP pasan a la imagen nueva al volver a crear su contenedor
function docker_update_image() {
    local slug=$1 dir php
    if ! docker_valid_slug "$slug" || [ ! -f "$DOCKER_DIR/$slug/proyecto.conf" ]; then
        echo "No hay ningun proyecto en Docker con el nombre $slug"
        return 1
    fi
    dir=$DOCKER_DIR/$slug
    if docker_web_project "$slug"; then
        local v running
        echo "$slug: imagenes de PHP $(docker_conf "$slug" PHP) de nuevo, con lo ultimo de Docker Hub (la BBDD y la configuracion no cambian)"
        [ "$DRY" -eq 1 ] && return 0
        docker_ready || { echo "Docker sin root no esta en marcha"; return 1; }
        local steps=()
        for v in $(docker_conf "$slug" PHP); do steps+=("Imagen de PHP $v"); done
        steps+=("Volver a crear sus contenedores")
        task_plan "$slug: imágenes de PHP" "${steps[@]}"
        for v in $(docker_conf "$slug" PHP); do
            task_step
            docker_php_image "$v" --nueva || { echo "No se ha podido rehacer la imagen de PHP $v: sigue con la anterior"; return 1; }
        done
        task_step
        running=$(dk ps --filter "label=com.docker.compose.project=nexum-$slug" --format '{{.Label "com.docker.compose.service"}}' 2> /dev/null)
        [ -n "$running" ] && { dk compose --project-directory "$dir" -f "$dir/compose.yaml" up -d --force-recreate $running || return 1; }
        dk image prune -f > /dev/null 2>&1
        echo "$slug ya funciona con las imagenes nuevas"
        return 0
    fi
    php=$(docker_conf "$slug" PHP)
    [[ " $DOCKER_PHP_VERSIONS " == *" $php "* ]] || { echo "$slug usa una version de PHP que no se ofrece: $php"; return 1; }
    echo "$slug: imagen de PHP $php de nuevo, con lo ultimo de Docker Hub (la BBDD y la configuracion no cambian)"
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] docker build --pull --no-cache -t nexum-php:$php y contenedor de PHP nuevo"
        return 0
    fi
    docker_ready || { echo "Docker sin root no esta en marcha"; return 1; }
    task_plan "$slug: imagen de PHP $php" "Imagen de PHP $php" "Volver a crear su contenedor"
    task_step
    docker_php_image "$php" --nueva || { echo "No se ha podido rehacer la imagen de PHP $php: sigue con la anterior"; return 1; }
    task_step
    mkdir -p -m 700 "$(docker_run_dir "$slug")"
    dk compose --project-directory "$dir" -f "$dir/compose.yaml" up -d --force-recreate php || return 1
    dk image prune -f > /dev/null 2>&1
    echo "$slug ya funciona con la imagen nueva de PHP $php"
}

# docker-php <nombre> <version>: cambia la version de PHP de un proyecto en Docker. Solo se cambia su
# contenedor de PHP (con la imagen de esa version, que se prepara si hace falta): su BBDD, su
# phpMyAdmin y su configuracion se quedan como estaban
function docker_set_php() {
    local slug=$1 php=$2 dir old
    if ! docker_valid_slug "$slug" || [ ! -f "$DOCKER_DIR/$slug/proyecto.conf" ]; then
        echo "No hay ningun proyecto en Docker con el nombre $slug"
        return 1
    fi
    [[ " $DOCKER_PHP_VERSIONS " == *" $php "* ]] || { echo "PHP $php no se ofrece en Docker ($DOCKER_PHP_VERSIONS)"; return 1; }
    if docker_web_project "$slug"; then
        echo "$slug va con el Apache de Docker: añade la version (docker-php-añadir $slug $php) y, si quieres, quita otra (docker-php-quitar)"
        return 1
    fi
    dir=$DOCKER_DIR/$slug
    old=$(docker_conf "$slug" PHP)
    if [ "$old" == "$php" ]; then
        echo "$slug ya usa PHP $php"
        return 0
    fi
    if ! grep -qE '^    image: nexum-php:[0-9.]+$' "$dir/compose.yaml"; then
        echo "No se encuentra el contenedor de PHP en $dir/compose.yaml"
        return 1
    fi
    echo "$slug: PHP $old -> $php (la BBDD y la configuracion no cambian)"
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] imagen nexum-php:$php y contenedor de PHP nuevo"
        return 0
    fi
    docker_ready || { echo "Docker sin root no esta en marcha"; return 1; }
    docker_php_image "$php" || { echo "No se ha podido preparar la imagen de PHP $php: sigue con PHP $old"; return 1; }
    sed -i -E "s|^    image: nexum-php:[0-9.]+$|    image: nexum-php:$php|" "$dir/compose.yaml" \
        && sed -i "s/^PHP=.*/PHP=$php/" "$dir/proyecto.conf" || return 1
    mkdir -p -m 700 "$(docker_run_dir "$slug")"
    if ! dk compose --project-directory "$dir" -f "$dir/compose.yaml" up -d php; then
        echo "No arranca con PHP $php: se vuelve a PHP $old"
        sed -i -E "s|^    image: nexum-php:[0-9.]+$|    image: nexum-php:$old|" "$dir/compose.yaml"
        sed -i "s/^PHP=.*/PHP=$old/" "$dir/proyecto.conf"
        dk compose --project-directory "$dir" -f "$dir/compose.yaml" up -d php
        return 1
    fi
    echo "$slug ya funciona con PHP $php"
}

# Arranque de Docker sin root y su servicio de usuario (lo mismo que hace dockerd-rootless-setuptool.sh
# del Docker oficial, que el paquete docker.io de Ubuntu no trae): rootlesskit crea el espacio de
# usuarios y la red (slirp4netns) y dentro arranca dockerd, que al verse ahi usa
# $XDG_RUNTIME_DIR/docker.sock y ~/.local/share/docker
DOCKER_ROOTLESS_SH='#!/bin/sh
# Docker sin root de Nexum Dev Stack (como dockerd-rootless.sh de Docker). Lo arranca systemctl --user
set -e
if [ -z "$_DOCKERD_ROOTLESS_CHILD" ]; then
    : "${XDG_RUNTIME_DIR:?falta XDG_RUNTIME_DIR}"
    export _DOCKERD_ROOTLESS_CHILD=1
    exec /usr/bin/rootlesskit --state-dir="$XDG_RUNTIME_DIR/dockerd-rootless" --net=slirp4netns --mtu=65520 \
        --slirp4netns-sandbox=auto --slirp4netns-seccomp=auto --disable-host-loopback --port-driver=builtin \
        --copy-up=/etc --copy-up=/run --propagation=rslave "$0" "$@"
fi
[ "$_DOCKERD_ROOTLESS_CHILD" = 1 ]
# (los del Docker del sistema: dentro del espacio de usuarios /run es una copia propia)
rm -f /run/docker /run/containerd /run/xtables.lock
exec /usr/bin/dockerd "$@"
'
DOCKER_UNIT='[Unit]
Description=Docker sin root (Nexum Dev Stack)
Documentation=https://docs.docker.com/engine/security/rootless/

[Service]
Environment=PATH=/usr/sbin:/usr/bin:/sbin:/bin
ExecStart=%h/.lvm-instalador/docker/bin/dockerd-rootless
ExecReload=/bin/kill -s HUP $MAINPID
TimeoutSec=0
RestartSec=2
Restart=always
StartLimitBurst=3
StartLimitInterval=60s
LimitNOFILE=infinity
LimitNPROC=infinity
LimitCORE=infinity
TasksMax=infinity
Delegate=yes
Type=notify
NotifyAccess=all
KillMode=mixed

[Install]
WantedBy=default.target
'

# docker-instalar: Docker sin root. Instala los paquetes de Ubuntu (con sudo, si falta alguno), deja
# apagados el Docker y el containerd del sistema (los que corren como root), prepara los rangos de
# usuarios (subuid/subgid) y, si Ubuntu limita los espacios de usuarios, el perfil de AppArmor de
# rootlesskit. Despues, ya con tu usuario, el servicio de Docker sin root (systemctl --user)
function docker_install() {
    local me=$(id -un) p missing=""
    if ! command -v apt-get > /dev/null; then
        echo "Docker sin root solo se instala en Ubuntu o Debian. Instalalo a mano: https://docs.docker.com/engine/security/rootless/"
        return 1
    fi
    for p in $DOCKER_PACKAGES; do
        dpkg-query -W -f='${Status}' "$p" 2> /dev/null | grep -q "install ok installed" || missing+=" $p"
    done
    task_plan "Preparando Docker sin root" "Paquetes del sistema" "Docker del sistema, apagado" "Docker sin root" "Comprobar que responde"
    task_step
    if [ -n "$missing" ]; then
        echo "1/4 Paquetes:$missing"
        # (sin preguntas de debconf: la tarea no tiene una terminal donde contestarlas)
        run sudo env DEBIAN_FRONTEND=noninteractive apt-get install -y $missing || return 1
    else
        echo "1/4 Paquetes: ya estan instalados"
    fi
    # (el paquete deja en marcha el demonio con root: con el, el grupo docker seria como ser root)
    task_step
    echo "2/4 Docker y containerd del sistema (con root), apagados: se usa solo el tuyo"
    if systemctl is-enabled -q docker.service docker.socket containerd.service 2> /dev/null \
            || systemctl is-active -q docker.service docker.socket containerd.service 2> /dev/null; then
        run sudo systemctl disable --now docker.service docker.socket containerd.service 2> /dev/null || true
    fi
    if ! grep -q "^$me:" /etc/subuid 2> /dev/null || ! grep -q "^$me:" /etc/subgid 2> /dev/null; then
        echo "   Rangos de usuarios para los contenedores (/etc/subuid y /etc/subgid)"
        run sudo usermod --add-subuids 231072-296607 --add-subgids 231072-296607 "$me" || return 1
    fi
    if [ "$(cat /proc/sys/kernel/apparmor_restrict_unprivileged_userns 2> /dev/null)" == 1 ] \
            && ! grep -lqs 'rootlesskit' /etc/apparmor.d/* 2> /dev/null; then
        echo "   Perfil de AppArmor para rootlesskit (Ubuntu limita los espacios de usuarios)"
        if [ "$DRY" -eq 1 ]; then
            echo "  [simulacion] /etc/apparmor.d/usr.bin.rootlesskit y recarga de AppArmor"
        else
            printf '%s\n' 'abi <abi/4.0>,' 'include <tunables/global>' '' \
                '"/usr/bin/rootlesskit" flags=(unconfined) {' '  userns,' '' \
                '  include if exists <local/usr.bin.rootlesskit>' '}' \
                | sudo tee /etc/apparmor.d/usr.bin.rootlesskit > /dev/null \
                && sudo apparmor_parser -r /etc/apparmor.d/usr.bin.rootlesskit || return 1
        fi
    fi
    task_step
    echo "3/4 Docker sin root para $me (servicio de tu usuario)"
    local unit_dir=${XDG_CONFIG_HOME:-$HOME/.config}/systemd/user
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] $DOCKER_DIR/bin/dockerd-rootless y $unit_dir/docker.service"
    else
        mkdir -p -m 700 "$DOCKER_DIR" "$DOCKER_DIR/bin" && mkdir -p "$unit_dir" || return 1
        printf '%s' "$DOCKER_ROOTLESS_SH" > "$DOCKER_DIR/bin/dockerd-rootless.nuevo" \
            && chmod 700 "$DOCKER_DIR/bin/dockerd-rootless.nuevo" \
            && mv -f "$DOCKER_DIR/bin/dockerd-rootless.nuevo" "$DOCKER_DIR/bin/dockerd-rootless" || return 1
        printf '%s' "$DOCKER_UNIT" > "$unit_dir/docker.service.nuevo" \
            && mv -f "$unit_dir/docker.service.nuevo" "$unit_dir/docker.service" || return 1
    fi
    run systemctl --user daemon-reload || return 1
    run systemctl --user enable docker.service || return 1
    run systemctl --user restart docker.service || {
        echo "No arranca Docker sin root. Lo que dice:"
        journalctl --user -u docker.service -n 30 --no-pager 2> /dev/null
        return 1
    }
    task_step
    echo "4/4 Comprobando"
    local i
    for i in $(seq 20); do docker_ready && break; [ "$DRY" -eq 1 ] && break; sleep 1; done
    if [ "$DRY" -eq 0 ] && ! docker_ready; then
        echo "Docker sin root no responde. Prueba a cerrar la sesion y volver a entrar, y pulsa Comprobar."
        return 1
    fi
    echo "Docker sin root listo (socket $(docker_sock))."
}

# Imagen de PHP del gestor para una version (nexum-php:<version>): la oficial php:<version>-fpm con
# las extensiones de DOCKER_PHP_EXT (con install-php-extensions, que sabe instalarlas tambien en las
# versiones antiguas). PHP-FPM escucha en un socket de /run/nexum (docker_run_dir del proyecto) y corre
# como el root del contenedor, que en Docker sin root eres tu: asi escribe en el proyecto con tu usuario
# Con --nueva se rehace aunque ya exista (Actualizar imagen: con lo ultimo de Docker Hub, sin cache).
# El php.ini es el de produccion, con las mitigaciones de PHP2Shell (PHP_SECURE_INI), y cada proceso
# de PHP-FPM se renueva cada 50 peticiones
# (install-php-extensions, fijado por su huella: la etiqueta 2 la puede mover cualquiera que llegue a
# esa cuenta de Docker Hub. Es la 2.12.3, del 20/10/2026; para otra: docker buildx imagetools inspect)
DOCKER_EXT_INSTALLER="mlocati/php-extension-installer:2.12.3@sha256:ac4b252c153a9f6de5578ff2c417790aba836bb49855543144606033eceda253"
function docker_php_image() {
    local php=$1 dir=$DOCKER_DIR/imagenes/php-$1 fresh=() ini
    if [ "$2" == "--nueva" ]; then
        fresh=(--pull --no-cache)
    elif [ "$DRY" -eq 0 ] && dk image inspect "nexum-php:$php" > /dev/null 2>&1; then
        return 0
    fi
    mkdir -p -m 700 "$dir" || return 1
    ini=$(printf 'memory_limit = 512M\nmax_execution_time = 300\n%s' "$PHP_SECURE_INI")
    php_85_or_later "$php" && ini+=$'\n'$PHP_SECURE_INI_85
    ini=${ini//$'\n'/\\n}
    cat > "$dir/Dockerfile" << EOF
FROM php:$php-fpm
COPY --from=$DOCKER_EXT_INSTALLER /usr/bin/install-php-extensions /usr/local/bin/
RUN install-php-extensions $DOCKER_PHP_EXT
RUN rm -f /usr/local/etc/php-fpm.d/zz-docker.conf /usr/local/etc/php-fpm.d/docker.conf \\
 && printf '[global]\\nerror_log = /proc/self/fd/2\\ndaemonize = no\\n[www]\\nuser = root\\ngroup = root\\nlisten = /run/nexum/php.sock\\nlisten.mode = 0660\\nclear_env = no\\ncatch_workers_output = yes\\npm.max_requests = 50\\n' > /usr/local/etc/php-fpm.d/zz-nexum.conf \\
 && cp "\$PHP_INI_DIR/php.ini-production" "\$PHP_INI_DIR/php.ini" \\
 && printf '$ini\\n' > "\$PHP_INI_DIR/conf.d/zz-nexum.ini"
CMD ["php-fpm", "-R", "-F"]
EOF
    echo "Preparando la imagen de PHP $php (${fresh:+de nuevo, }tarda unos minutos)..."
    run dk build "${fresh[@]}" -t "nexum-php:$php" "$dir"
}

# Configuracion del proyecto para el contenedor: copia de su wp-config.php (o parameters.php /
# settings.inc.php) con la BBDD del contenedor y, en WordPress, su dominio. Imprime la ruta relativa
# del fichero dentro del proyecto (la que se sustituye en el contenedor), nada si no tiene. El
# servidor de la BBDD es db (el contenedor del proyecto) o el septimo argumento (la MariaDB comun)
function docker_project_config() {
    local folder=$1 dir=$2 domain=$3 db=$4 user=$5 pass=$6 host=${7:-db} rel
    for rel in wp-config.php app/config/parameters.php config/settings.inc.php; do
        [ -f "$HTDOCS_DIR/$folder/$rel" ] && [ ! -L "$HTDOCS_DIR/$folder/$rel" ] && break
        rel=""
    done
    [ -z "$rel" ] && return 0
    python3 -I - "$HTDOCS_DIR/$folder/$rel" "$dir/config.php" "$rel" "$domain" "$db" "$user" "$pass" "$host" << 'EOF' || return 1
import os, re, sys
src, dst, rel, domain, db, user, pw, host = sys.argv[1:9]
with open(src, encoding="utf-8", errors="surrogateescape", newline="") as f:
    text = f.read(2000000)
def lit(v):
    return "'" + v.replace("\\", "\\\\").replace("'", "\\'") + "'"
if rel == "wp-config.php":
    for name, val in (("DB_NAME", db), ("DB_USER", user), ("DB_PASSWORD", pw), ("DB_HOST", host)):
        # (en cualquier sitio de la linea, salvo detras de un comentario // o #)
        text, n = re.subn(r"""(?m)^((?:(?!//|#)[^\n])*?\bdefine\(\s*['"]%s['"]\s*,\s*)(?:'(?:[^'\\]|\\.)*'|"(?:[^"\\]|\\.)*")""" % name,
                          lambda m: m.group(1) + lit(val), text, count=1)
        if not n:
            text = re.sub(r"^<\?php", lambda m: "<?php\ndefine(%s, %s);" % (lit(name), lit(val)), text, count=1)
    # (el dominio del contenedor, sin tocar la BBDD; detras de un proxy con https)
    extra = ("\nif (($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '') === 'https' || ($_SERVER['HTTPS'] ?? '') === 'on') { $_SERVER['HTTPS'] = 'on'; }\n"
             "define('WP_HOME', 'https://%s');\ndefine('WP_SITEURL', 'https://%s');\n" % (domain, domain))
    # Las direcciones de la web en local que lleva el contenido (las imagenes y enlaces que se guardaron
    # trabajando con LAMPP: https://web.local/wp-content/...): en lo que devuelve, las del contenedor. Si
    # no, se piden a LAMPP (sin el en marcha, o con otro proyecto en web.local, no salen). La BBDD no se
    # toca. Tambien escapadas (JSON, Elementor) y codificadas
    hosts = [h for h in os.environ.get("LVM_DOMINIOS_LOCALES", "").split() if re.fullmatch(r"[A-Za-z0-9.-]+(:[0-9]+)?", h)]
    if hosts:
        pairs = []
        for h in hosts:
            for scheme in ("https://", "http://"):
                pairs.append((scheme + h, "https://" + domain))
                pairs.append((scheme.replace("/", "\\/") + h, "https:\\/\\/" + domain))
                pairs.append((scheme.replace(":", "%3A").replace("/", "%2F") + h, "https%3A%2F%2F" + domain))
        extra += ("if (PHP_SAPI !== 'cli') { ob_start(function ($b) { return str_replace(%s, %s, $b); }); }\n"
                  % ("array(" + ", ".join(lit(a) for a, _ in pairs) + ")", "array(" + ", ".join(lit(b) for _, b in pairs) + ")"))
    text = re.sub(r"(?m)^[ \t]*define\(\s*['\"](WP_HOME|WP_SITEURL)['\"].*$", "", text)
    text = re.sub(r"^<\?php", lambda m: "<?php" + extra, text, count=1)
elif rel == "app/config/parameters.php":
    for key, val in (("database_host", host), ("database_port", ""), ("database_name", db),
                     ("database_user", user), ("database_password", pw)):
        text = re.sub(r"""(['"]%s['"]\s*=>\s*)(?:'(?:[^'\\]|\\.)*'|"(?:[^"\\]|\\.)*"|NULL|null|\d+)""" % key,
                      lambda m: m.group(1) + lit(val), text, count=1)
else:
    for name, val in (("_DB_SERVER_", host), ("_DB_NAME_", db), ("_DB_USER_", user), ("_DB_PASSWD_", pw)):
        text = re.sub(r"""(define\(\s*['"]%s['"]\s*,\s*)(?:'(?:[^'\\]|\\.)*'|"(?:[^"\\]|\\.)*")""" % name,
                      lambda m: m.group(1) + lit(val), text, count=1)
fd = os.open(dst, os.O_WRONLY | os.O_CREAT | os.O_TRUNC | os.O_NOFOLLOW, 0o600)
with os.fdopen(fd, "w", encoding="utf-8", errors="surrogateescape", newline="") as f:
    f.write(text)
EOF
    echo "$rel"
}

# Bloque del vhost de un proyecto en Docker (http y https) para los vhosts compartidos: la carpeta
# del proyecto como siempre y los .php al PHP-FPM del contenedor
function docker_vhost_block() {
    local slug=$1 folder=$2 domain=$3 sock=$4 crt=$5 key=$6 admin=$(server_admin) port
    printf '\n# nexum-docker %s: el PHP va en Docker (no se edita a mano: lo quita Docker, Borrar)\n' "$slug"
    for port in "$PORT_HTTP" "$PORT_HTTPS"; do
        printf '<VirtualHost *:%s>\n    ServerAdmin %s\n    DocumentRoot "/opt/lampp/htdocs/%s"\n    ServerName %s\n' \
            "$port" "$admin" "$folder" "$domain"
        [ "$port" == "$PORT_HTTPS" ] && printf '    SSLEngine on\n    SSLCertificateFile "%s"\n    SSLCertificateKeyFile "%s"\n' "$crt" "$key"
        printf '    <FilesMatch "\\.php$">\n        SetHandler "proxy:unix:%s|fcgi://nexum-%s"\n    </FilesMatch>\n' "$sock" "$slug"
        printf '    ErrorLog "logs/%s-error_log"\n</VirtualHost>\n' "$domain"
    done
    printf '# /nexum-docker %s\n' "$slug"
}

# Cambia los vhosts compartidos por los de la copia, con la comprobacion de siempre (edit_vhosts)
function docker_apply_vhosts() {
    local copy=$1
    edit_vhosts --aplicar "$copy"
}

# docker-crear <carpeta> <php> <mariadb> [--bd <base> --desde <version LAMPP>] [--dominio <dominio>]
#   [--nombre <nombre>]  (otro nombre: el mismo proyecto en Docker con otra version de PHP)
function docker_create() {
    local folder=${1%/} php=$2 maria=$3 db="" from="" domain="" name="" slug dir sock rel pma_port p
    shift 3 2> /dev/null
    while [ $# -gt 0 ]; do
        case $1 in
            --bd|--desde|--dominio|--nombre)
                [ -n "$2" ] || { echo "Falta el valor de $1"; return 1; }
                case $1 in --bd) db=$2 ;; --desde) from=$2 ;; --dominio) domain=$2 ;; --nombre) name=$2 ;; esac
                shift 2 ;;
            *) echo "Opcion desconocida: $1"; return 1 ;;
        esac
    done
    if [ -z "$folder" ] || [ -z "$php" ] || [ -z "$maria" ]; then
        echo "Uso: nexum docker-crear <carpeta> <php> <mariadb> [--bd <base> --desde <version>] [--dominio <dominio>] [--nombre <nombre>]"
        return 1
    fi
    valid_project "$folder" || return 1
    [[ " $DOCKER_PHP_VERSIONS " == *" $php "* ]] || { echo "PHP $php no se ofrece en Docker ($DOCKER_PHP_VERSIONS)"; return 1; }
    [[ " $DOCKER_MARIADB_VERSIONS " == *" $maria "* ]] || { echo "MariaDB $maria no se ofrece en Docker ($DOCKER_MARIADB_VERSIONS)"; return 1; }
    if [ -n "$db" ]; then
        db_valid_name "$db" || return 1
        [ -n "$from" ] && valid_version_name "$from" && [ -d "${TEST_DIR:-/opt}/lampp-$from" ] \
            || { echo "Con --bd hay que decir de que version LAMPP se copia (--desde)"; return 1; }
    fi
    if [ -n "$name" ]; then
        slug=$name
        docker_valid_slug "$slug" || { echo "Nombre no valido para Docker: $slug (minusculas, numeros y guiones)"; return 1; }
    else
        slug=$(docker_slug "$folder") && docker_valid_slug "$slug" || { echo "No se puede sacar un nombre corto de $folder"; return 1; }
    fi
    domain=${domain:-$slug.docker.local}
    domain=$(tr 'A-Z' 'a-z' <<< "$domain")
    valid_domain "$domain" || { echo "Dominio no valido: $domain"; return 1; }
    [[ "$domain" == *.local ]] || { echo "El dominio de un proyecto en Docker tiene que acabar en .local ($domain)"; return 1; }
    dir=$DOCKER_DIR/$slug
    if [ -e "$dir" ]; then
        echo "Ya hay un proyecto en Docker con el nombre $slug ($dir): borralo antes o usa otra carpeta"
        return 1
    fi
    if vhosts_info | awk -F'|' -v d="$domain" '$3 == d || (" " $4 " ") ~ (" " d " ") { f = 1 } END { exit !f }'; then
        echo "Ya hay un vhost con el dominio $domain"
        return 1
    fi
    if [ "$DRY" -eq 0 ] && ! docker_ready; then
        echo "Docker sin root no esta en marcha: instalalo o arrancalo en la pestaña Docker."
        return 1
    fi
    # Puerto de 127.0.0.1 para su phpMyAdmin: el primero libre
    pma_port=$DOCKER_PMA_PORT
    while grep -qs "^PUERTO_PMA=$pma_port$" "$DOCKER_DIR"/*/proyecto.conf || ss -Hltn "sport = :$pma_port" 2> /dev/null | grep -q .; do
        pma_port=$((pma_port + 1))
    done
    local dbname=${db:-$(tr '-' '_' <<< "$slug")} user=nexum
    local root_pass app_pass
    root_pass=$(head -c 18 /dev/urandom | base64 | tr -d '/+=\n')
    app_pass=$(head -c 18 /dev/urandom | base64 | tr -d '/+=\n')
    sock=$(docker_run_dir "$slug")/php.sock
    if [ ${#sock} -gt 100 ]; then
        echo "La ruta del socket de PHP ($sock) es demasiado larga: usa una carpeta con un nombre mas corto"
        return 1
    fi

    echo "Proyecto en Docker: $folder con PHP $php y MariaDB $maria (https://$domain)"
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] $dir con compose.yaml, la imagen nexum-php:$php, vhost de $domain y su linea en $HOSTS_FILE"
        [ -n "$db" ] && echo "  [simulacion] copia de $db de lampp-$from a la MariaDB del contenedor"
        return 0
    fi
    mkdir -p -m 700 "$DOCKER_DIR" "$dir" "$(dirname "$sock")" || return 1
    chmod 700 "$DOCKER_DIR" "$dir" "$(dirname "$(dirname "$sock")")" "$(dirname "$sock")"
    # (las contraseñas, solo en ficheros solo tuyos)
    ( umask 077
      printf 'DB_ROOT_PASS=%s\nDB_PASS=%s\n' "$root_pass" "$app_pass" > "$dir/.env"
      printf 'CARPETA=%s\nPHP=%s\nMARIADB=%s\nDOMINIO=%s\nBBDD=%s\nPUERTO_PMA=%s\n' \
          "$folder" "$php" "$maria" "$domain" "$dbname" "$pma_port" > "$dir/proyecto.conf" ) || return 1
    rel=$(docker_project_config "$folder" "$dir" "$domain" "$dbname" "$user" "$app_pass") || return 1
    {
        printf 'name: nexum-%s\nservices:\n' "$slug"
        printf '  php:\n    image: nexum-php:%s\n    restart: "no"\n    volumes:\n' "$php"
        printf '      - "%s:/opt/lampp/htdocs/%s"\n' "$HTDOCS_DIR/$folder" "$folder"
        printf '      - "%s:/run/nexum"\n' "$(dirname "$sock")"
        [ -n "$rel" ] && printf '      - "./config.php:/opt/lampp/htdocs/%s/%s:ro"\n' "$folder" "$rel"
        # PrestaShop 1.7 y posteriores guardan su configuracion (con la BBDD del contenedor: db y su
        # usuario) en var/cache: aparte, en un volumen del contenedor, no en la carpeta que comparte
        # con LAMPP (que la leeria y no encontraria la BBDD)
        [ "$rel" == app/config/parameters.php ] && printf '      - "cache:/opt/lampp/htdocs/%s/var/cache"\n' "$folder"
        printf '    depends_on: [db]\n'
        printf '  db:\n    image: mariadb:%s\n    restart: "no"\n    environment:\n' "$maria"
        printf '      MARIADB_ROOT_PASSWORD: ${DB_ROOT_PASS}\n      MARIADB_DATABASE: %s\n      MARIADB_USER: %s\n      MARIADB_PASSWORD: ${DB_PASS}\n' "$dbname" "$user"
        printf '    volumes:\n      - "db:/var/lib/mysql"\n'
        # (sin PMA_USER ni PMA_PASSWORD: phpMyAdmin enseña su pantalla de acceso; la contraseña de
        # root la copia la ventana)
        printf '  pma:\n    image: %s\n    restart: "no"\n    environment:\n      PMA_HOST: db\n      UPLOAD_LIMIT: 64M\n' "$DOCKER_PMA_IMAGE"
        printf '    ports:\n      - "127.0.0.1:%s:80"\n    depends_on: [db]\n' "$pma_port"
        printf 'volumes:\n  db: {}\n'
        if [ "$rel" == app/config/parameters.php ]; then printf '  cache: {}\n'; fi
    } > "$dir/compose.yaml" || return 1

    task_plan "Creando $folder en Docker" "Imagen de PHP $php" "Contenedores" "BBDD $dbname" "Vhost de $domain"
    task_step
    echo "1/4 Imagen de PHP $php"
    docker_php_image "$php" || { echo "No se ha podido preparar la imagen de PHP $php"; return 1; }
    task_step
    echo "2/4 Contenedores"
    dk compose --project-directory "$dir" -f "$dir/compose.yaml" up -d || return 1
    task_step
    echo "3/4 BBDD $dbname"
    local i
    # (la contraseña no va en ninguna orden, que se ve en ps: el cliente la toma dentro del contenedor
    # de MARIADB_ROOT_PASSWORD, la variable con la que se creo)
    for i in $(seq 60); do
        dk compose --project-directory "$dir" -f "$dir/compose.yaml" exec -T db \
            sh -c 'MYSQL_PWD=$MARIADB_ROOT_PASSWORD exec $(command -v mariadb || command -v mysql) -uroot -e "SELECT 1"' < /dev/null > /dev/null 2>&1 && break
        sleep 1
    done
    if [ -n "$db" ]; then
        local tmp
        mkdir -p -m 700 "$LOG_DIR" || return 1
        tmp=$(mktemp "$LOG_DIR/docker-$slug-XXXXXX") && mv -f "$tmp" "$tmp.sql.gz" && tmp=$tmp.sql.gz || return 1
        echo "Copiando $db de lampp-$from..."
        if ! export_database "$db" "$tmp" "$from"; then
            rm -f "$tmp"
            echo "No se ha podido descargar $db de lampp-$from: el proyecto queda con la BBDD vacia."
        else
            db_temp_stop
            gzip -dc "$tmp" | dk compose --project-directory "$dir" -f "$dir/compose.yaml" exec -T db \
                sh -c 'MYSQL_PWD=$MARIADB_ROOT_PASSWORD exec $(command -v mariadb || command -v mysql) -uroot --binary-mode "$0"' "$dbname" \
                || echo "Aviso: la carga de $db ha dado errores (mira el registro)."
            rm -f "$tmp"
            docker_ps_domain "$dir" "$dbname" "$domain" "$root_pass"
            # (la copia va sin el administrador de pruebas: se le pone el de este equipo para el Panel)
            local admin
            admin=$(docker_test_admin "$slug")
            grep -v '^A|' <<< "$admin" | grep .
            grep -q '^A|' <<< "$admin" && echo "Administrador de pruebas del panel: $TEST_ADMIN_USER, contraseña $TEST_ADMIN_PASS"
        fi
    fi
    task_step
    echo "4/4 Vhost de $domain"
    local crt=$OWN_SSL_DIR/$domain-selfsigned.crt key=$OWN_SSL_DIR/$domain-selfsigned.key copy
    [ -f "$crt" ] || make_selfsigned "$domain" "" "$crt" "$key" || return 1
    copy=$(mktemp "$LOG_DIR/vhosts-docker-XXXXXX") || return 1
    { cat "$(readlink -f "$ACTIVE_VHOSTS")"; docker_vhost_block "$slug" "$folder" "$domain" "$sock" "$crt" "$key"; } > "$copy"
    docker_apply_vhosts "$copy" || { rm -f "$copy"; echo "No se ha podido añadir el vhost de $domain (los contenedores quedan creados)"; return 1; }
    rm -f "$copy"
    if ! grep -qE "^[^#]*[[:space:]]${domain//./\\.}([[:space:]]|$)" "$HOSTS_FILE" 2> /dev/null; then
        copy=$(mktemp "$LOG_DIR/hosts-docker-XXXXXX") || return 1
        { cat "$HOSTS_FILE"; printf '127.0.0.1 %s\n' "$domain"; } > "$copy"
        edit_hosts --aplicar "$copy"
        rm -f "$copy"
    fi
    browser_trust "$domain" || true
    echo "Proyecto en Docker listo: https://$domain (PHP $php). phpMyAdmin: http://127.0.0.1:$pma_port/"
}

# Tienda PrestaShop copiada al contenedor: su dominio pasa a ser el del contenedor (la BBDD es una copia)
function docker_ps_domain() {
    local dir=$1 db=$2 domain=$3 pass=$4 prefix
    # (la contraseña, la del contenedor: MARIADB_ROOT_PASSWORD)
    prefix=$(dk compose --project-directory "$dir" -f "$dir/compose.yaml" exec -T db \
        sh -c 'MYSQL_PWD=$MARIADB_ROOT_PASSWORD exec $(command -v mariadb || command -v mysql) -uroot -N -e "SELECT LEFT(table_name, LENGTH(table_name) - 8) FROM information_schema.tables WHERE table_schema = \"$0\" AND table_name LIKE \"%shop\\_url\" LIMIT 1"' "$db" < /dev/null 2> /dev/null | tr -d '\r')
    [[ "$prefix" =~ ^[A-Za-z0-9_]+$ ]] || return 0
    echo "Tienda PrestaShop: su dominio pasa a $domain en la copia del contenedor"
    dk compose --project-directory "$dir" -f "$dir/compose.yaml" exec -T db \
        sh -c 'MYSQL_PWD=$MARIADB_ROOT_PASSWORD exec $(command -v mariadb || command -v mysql) -uroot "$0"' "$db" << EOF
UPDATE \`${prefix}shop_url\` SET domain = '$domain', domain_ssl = '$domain';
UPDATE \`${prefix}configuration\` SET value = '$domain' WHERE name IN ('PS_SHOP_DOMAIN', 'PS_SHOP_DOMAIN_SSL');
UPDATE \`${prefix}configuration\` SET value = '1' WHERE name IN ('PS_SSL_ENABLED', 'PS_SSL_ENABLED_EVERYWHERE');
EOF
}

# docker-usuario-pruebas <nombre>: el administrador de pruebas (usuario-pruebas) en la BBDD del
# contenedor del proyecto. La copia que se lleva de LAMPP no lo tiene (exportar-bd lo deja fuera) y
# sin el no entra el Panel. Es el mismo test_admin, por el cliente de la MariaDB del contenedor como
# root: la contraseña la toma dentro del contenedor (MARIADB_ROOT_PASSWORD), nunca en una orden. Dice
# A|wp|... y/o A|ps|... como usuario-pruebas; con el proyecto parado, nada (sale con 1)
function docker_test_admin() {
    local slug=$1 dir db folder
    docker_valid_slug "$slug" && [ -f "$DOCKER_DIR/$slug/proyecto.conf" ] || { echo "No hay ningun proyecto en Docker con el nombre $slug"; return 1; }
    dir=$DOCKER_DIR/$slug
    db=$(docker_conf "$slug" BBDD) folder=$(docker_conf "$slug" CARPETA)
    db_valid_name "$db" > /dev/null || { echo "$slug no tiene una BBDD valida en su proyecto.conf"; return 1; }
    if docker_web_project "$slug"; then
        local DB_ROOT_CLIENT=(dk exec -i "$(docker_maria_name "$(docker_conf "$slug" MARIADB)")"
            sh -c 'MYSQL_PWD=$MARIADB_ROOT_PASSWORD exec $(command -v mariadb || command -v mysql) -uroot "$@"' mariadb)
        test_admin "$db" "$folder"
        return
    fi
    local DB_ROOT_CLIENT=(dk compose --project-directory "$dir" -f "$dir/compose.yaml" exec -T db
        sh -c 'MYSQL_PWD=$MARIADB_ROOT_PASSWORD exec $(command -v mariadb || command -v mysql) -uroot "$@"' mariadb)
    test_admin "$db" "$folder"
}

# docker-borrar <nombre> --copia: antes de borrar el proyecto, una copia de su BBDD de Docker en
# ~/nexum-backups (docker-<nombre>-<bbdd>-<fecha>.sql.gz, se puede volver a cargar con importar-bd), con un
# volcado de su MariaDB de Docker: la comun de su version, en los del Apache de Docker, o la suya, en los
# de antes. Con la BBDD en vivo de una version (sin copia en Docker), no hay nada que copiar. Si la copia
# falla, devuelve error: entonces no se borra nada
function docker_db_backup() {
    local slug=$1 dir=$DOCKER_DIR/$1 db maria backup i cl
    local c=(dk compose --project-directory "$dir" -f "$dir/compose.yaml")
    local dump='MYSQL_PWD=$MARIADB_ROOT_PASSWORD exec $(command -v mariadb-dump || command -v mysqldump) -uroot --single-transaction --routines --triggers --events "$0"'
    db=$(docker_conf "$slug" BBDD)
    docker_web_project "$slug" && [ -n "$(docker_conf "$slug" LAMPP_BD)" ] && db=$(docker_conf "$slug" BBDD_DOCKER)
    if ! db_valid_name "$db" > /dev/null; then
        echo "$slug no tiene BBDD propia en Docker: no hay nada que copiar"
        return 0
    fi
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] copia de $db (la de Docker) en ~/nexum-backups"
        return 0
    fi
    echo "Copia de su BBDD de Docker ($db)"
    if docker_web_project "$slug"; then
        maria=$(docker_conf "$slug" MARIADB)
        docker_maria_up "$maria" > /dev/null || { echo "La MariaDB $maria de Docker no responde: no se borra nada"; return 1; }
        cl=(dk exec -i "$(docker_maria_name "$maria")")
    else
        "${c[@]}" up -d db > /dev/null || { echo "No se ha podido arrancar su MariaDB de Docker: no se borra nada"; return 1; }
        for i in $(seq 60); do
            "${c[@]}" exec -T db sh -c 'MYSQL_PWD=$MARIADB_ROOT_PASSWORD exec $(command -v mariadb || command -v mysql) -uroot -e "SELECT 1"' \
                < /dev/null > /dev/null 2>&1 && break
            sleep 1
        done
        cl=("${c[@]}" exec -T db)
    fi
    mkdir -p -m 700 "$COPIES_DIR" || return 1
    backup="$COPIES_DIR/docker-$slug-$db-$(date +%Y%m%d-%H%M%S).sql.gz"
    ( umask 077
      set -o pipefail
      "${cl[@]}" sh -c "$dump" "$db" < /dev/null | gzip > "$backup" )
    if [ $? -ne 0 ] || [ "$(gzip -dc "$backup" 2> /dev/null | head -c 4096 | wc -c)" -lt 100 ]; then
        echo "No se ha podido copiar su BBDD de Docker ($db): no se borra nada"
        rm -f "$backup"
        return 1
    fi
    echo "Copia de $db: $backup"
}
# docker-arrancar|docker-parar|docker-registros|docker-borrar <nombre> (docker-borrar <nombre> --copia: antes,
# una copia de su BBDD de Docker en ~/nexum-backups; si falla, no se borra nada)
function docker_action() {
    local action=$1 slug=$2 dir
    docker_valid_slug "$slug" && [ -f "$DOCKER_DIR/$slug/proyecto.conf" ] || { echo "No hay ningun proyecto en Docker con el nombre $slug"; return 1; }
    if [ "$action" == borrar ] && [ "$3" == --copia ]; then
        docker_db_backup "$slug" || return 1
    fi
    # (los del Apache de Docker: lo suyo es distinto)
    if docker_web_project "$slug"; then
        case $action in
            arrancar|parar|registros|borrar) docker_web_action "$action" "$slug" ;;
            *) echo "Uso: nexum docker-arrancar|docker-parar|docker-registros|docker-borrar <nombre>"; return 1 ;;
        esac
        return
    fi
    dir=$DOCKER_DIR/$slug
    local c=(dk compose --project-directory "$dir" -f "$dir/compose.yaml")
    case $action in
        # (la carpeta del socket esta en memoria: tras reiniciar el equipo hay que volver a crearla)
        arrancar) run mkdir -p -m 700 "$(docker_run_dir "$slug")" && run "${c[@]}" up -d ;;
        parar) run "${c[@]}" stop ;;
        registros) "${c[@]}" logs --no-color --tail 200 ;;
        borrar)
            local domain=$(docker_conf "$slug" DOMINIO) copy
            echo "Se borran los contenedores de $slug y su BBDD (la copia del contenedor; la de LAMPP no se toca)"
            run "${c[@]}" down -v || return 1
            if grep -q "^# nexum-docker $slug:" "$(readlink -f "$ACTIVE_VHOSTS")" 2> /dev/null; then
                copy=$(mktemp "$LOG_DIR/vhosts-docker-XXXXXX") || return 1
                awk -v s="$slug" '$0 ~ ("^# nexum-docker " s ":") { skip = 1 } !skip { print } $0 == ("# /nexum-docker " s) { skip = 0 }' \
                    "$(readlink -f "$ACTIVE_VHOSTS")" | sed -e :a -e '/^\n*$/{$d;N;ba' -e '}' > "$copy"
                docker_apply_vhosts "$copy" || { rm -f "$copy"; return 1; }
                rm -f "$copy"
            fi
            if [ -n "$domain" ] && valid_domain "$domain" && grep -qE "^127\.0\.0\.1[[:space:]]+${domain//./\\.}$" "$HOSTS_FILE"; then
                copy=$(mktemp "$LOG_DIR/hosts-docker-XXXXXX") || return 1
                grep -vE "^127\.0\.0\.1[[:space:]]+${domain//./\\.}$" "$HOSTS_FILE" > "$copy"
                edit_hosts --aplicar "$copy"
                rm -f "$copy"
            fi
            [ "$DRY" -eq 1 ] || rm -rf "$dir" "$(docker_run_dir "$slug")"
            echo "Proyecto en Docker $slug borrado"
            ;;
        *) echo "Uso: nexum docker-arrancar|docker-parar|docker-registros|docker-borrar <nombre>"; return 1 ;;
    esac
}

# ===========================================================================
# Docker con su propio Apache: un proyecto en varias versiones de PHP a la vez, sin LAMPP
# ===========================================================================
# Desde la 1.56 los proyectos nuevos en Docker no pasan por el Apache de LAMPP: Docker tiene el suyo
# (nexum-web, la imagen oficial de Apache) en otra direccion de este equipo (127.0.0.2 por defecto:
# DOCKER_WEB_FILE), asi que funcionan con LAMPP parado o con cualquier version activa. Lleva las mismas
# reglas de seguridad que LAMPP (las de UNKNOWN_HOST_VHOST: los ficheros que no se sirven y la barrera
# entre webs) y lee los .htaccess de cada proyecto. Los .php los pasa al contenedor de cada version de
# PHP (nexum-<proyecto>-php83, con la imagen nexum-php de siempre: ninguna imagen mas) por la red
# interna de Docker (nexum), sin puertos abiertos fuera. Las BBDD van en una MariaDB comun por version
# de MariaDB (nexum-mariadb-11-8), cada proyecto con su BBDD y su usuario, y hay un solo phpMyAdmin
# (https://pma.docker.local, con su pantalla de acceso). Un proyecto puede tener varias versiones de
# PHP a la vez con la misma BBDD: en WordPress, cada una con su dominio (<proyecto>-php83.docker.local,
# su wp-config.php del contenedor lo lleva); una tienda PrestaShop guarda su dominio en la BBDD, asi que
# va con uno solo (<proyecto>.docker.local) y la version que se elija. Un certificado propio para
# *.docker.local, que no es de una CA: no vale para ninguna otra web. Los proyectos de antes (con
# LAMPP delante) siguen igual hasta que se pasan (docker-pasar)
# (httpd fijado por su huella: la etiqueta 2.4 la puede mover cualquiera que llegue a esa cuenta de
# Docker Hub. Es la 2.4.69, Debian trixie, del 21/10/2026; para otra: docker buildx imagetools inspect)
DOCKER_WEB_IMAGE="httpd:2.4.69@sha256:a30cd4cd57f3f3c3be9b2d16384d2488839996bb14c67df2b51f1ecbb3e584a1"
DOCKER_WEB_DIR=$DOCKER_DIR/web
DOCKER_WEB_FILE="$DOCKER_DIR/web.conf"
# (los puertos de menos de 1024 son de root: con Docker sin root hay que bajar ese limite una vez)
DOCKER_SYSCTL=${LVM_DOCKER_SYSCTL:-/etc/sysctl.d/60-nexum-docker.conf}

# Direccion (IP) y puertos (HTTP, HTTPS) del Apache de Docker. Siempre de 127.x: nunca abiertos a la red
function docker_web_get() {
    local v def
    case $1 in IP) def=127.0.0.2 ;; HTTP) def=80 ;; HTTPS) def=443 ;; TLD) def=docker.local ;; DNS) def=0 ;; *) return 1 ;; esac
    v=$(awk -F= -v k="$1" '$1 == k { sub(/^[^=]*=/, ""); print; exit }' "$DOCKER_WEB_FILE" 2> /dev/null)
    case $1 in
        IP) docker_web_valid_ip "$v" || v=$def ;;
        TLD) [ "$v" == docker.test ] || v=$def ;;
        DNS) [ "$v" == 1 ] || v=$def ;;
        *) [[ "$v" =~ ^[1-9][0-9]{0,4}$ ]] && [ "$v" -le 65535 ] || v=$def ;;
    esac
    echo "$v"
}

# Guarda web.conf (solo tuyo): docker_web_conf_write <ip> <http> <https> <tld> <dns>
function docker_web_conf_write() {
    mkdir -p -m 700 "$DOCKER_DIR" || return 1
    ( umask 077; printf 'IP=%s\nHTTP=%s\nHTTPS=%s\nTLD=%s\nDNS=%s\n' "$@" > "$DOCKER_WEB_FILE.nuevo" ) \
        && mv -f "$DOCKER_WEB_FILE.nuevo" "$DOCKER_WEB_FILE"
}

# Final de los dominios del Apache de Docker: docker.local (en /etc/hosts, uno a uno) o, con el DNS
# comodin, docker.test. .local es de mDNS: un DNS para *.docker.local no se consultaria
function docker_web_tld() {
    docker_web_get TLD
}

# ¿Va el DNS comodin de *.docker.test? (sus dominios ya no van en /etc/hosts)
function docker_dns_on() {
    [ "$(docker_web_get DNS)" == 1 ] && [ "$(docker_web_get TLD)" == docker.test ]
}

# Dominio de phpMyAdmin
function docker_web_pma() {
    echo "pma.$(docker_web_tld)"
}

function docker_web_valid_ip() {
    [[ "$1" =~ ^127\.([0-9]{1,3})\.([0-9]{1,3})\.([0-9]{1,3})$ ]] \
        && [ "${BASH_REMATCH[1]}" -le 255 ] && [ "${BASH_REMATCH[2]}" -le 255 ] && [ "${BASH_REMATCH[3]}" -le 254 ] \
        && [ "${BASH_REMATCH[3]}" -ge 1 ]
}

# Direccion de una web del Apache de Docker: https://<dominio>, con el puerto si no es el 443
function docker_web_url() {
    local port=$(docker_web_get HTTPS)
    echo "https://$1$([ "$port" == 443 ] || echo ":$port")"
}

# ¿Puede Docker sin root abrir sus puertos? (el limite de los puertos de root, ip_unprivileged_port_start)
function docker_web_ports_ok() {
    local start low http https
    start=$(cat "${LVM_PORT_START_FILE:-/proc/sys/net/ipv4/ip_unprivileged_port_start}" 2> /dev/null || echo 1024)
    http=$(docker_web_get HTTP) https=$(docker_web_get HTTPS)
    low=$http
    [ "$https" -lt "$low" ] && low=$https
    [ "$low" -ge "$start" ]
}

# Nombres de lo comun: la MariaDB de una version (nexum-mariadb-11-8) y el contenedor de PHP de una
# version de un proyecto (nexum-<proyecto>-php83)
function docker_maria_name() {
    echo "nexum-mariadb-${1//./-}"
}
function docker_web_container() {
    echo "nexum-$1-php${2//./}"
}

# ¿Es un proyecto del sistema nuevo (con el Apache de Docker)?
function docker_web_project() {
    docker_valid_slug "$1" && [ "$(docker_conf "$1" MODO)" == web ]
}

# Dominio de una version de PHP de un proyecto: el de la tienda (uno solo) o <proyecto>-php83.docker.local
function docker_web_domain() {
    if [ "$(docker_conf "$1" TIPO)" == ps ]; then
        echo "$1.$(docker_web_tld)"
    else
        echo "$1-php${2//./}.$(docker_web_tld)"
    fi
}

# Dominios de un proyecto (todas sus versiones)
function docker_web_domains() {
    local v
    for v in $(docker_conf "$1" PHP); do docker_web_domain "$1" "$v"; done | awk '!seen[$0]++'
}

# Proyectos del sistema nuevo
function docker_web_projects() {
    local p
    for p in $(docker_projects); do
        [ "$(docker_conf "$p" MODO)" == web ] && echo "$p"
    done
}

# La red interna de Docker que comparten el Apache, las MariaDB y los PHP (sin puertos fuera)
function docker_net() {
    dk network inspect nexum > /dev/null 2>&1 || dk network create nexum > /dev/null
}

# SQL como root en la MariaDB comun de una version: docker_maria_sql <version> [argumentos de mariadb].
# La contraseña no va en ninguna orden (se ve en ps): el cliente la toma dentro del contenedor
function docker_maria_sql() {
    local v=$1
    shift
    dk exec -i "$(docker_maria_name "$v")" \
        sh -c 'MYSQL_PWD=$MARIADB_ROOT_PASSWORD exec $(command -v mariadb || command -v mysql) -uroot "$@"' mariadb "$@"
}

# La MariaDB comun de una version: la crea (su compose.yaml y su contraseña de root al azar, en
# ficheros solo tuyos) si no existe, la arranca y espera a que responda
function docker_maria_up() {
    local v=$1 name dir i
    [[ " $DOCKER_MARIADB_VERSIONS " == *" $v "* ]] || { echo "MariaDB $v no se ofrece en Docker ($DOCKER_MARIADB_VERSIONS)"; return 1; }
    name=$(docker_maria_name "$v") dir=$DOCKER_DIR/mariadb-$v
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] MariaDB $v comun ($name) en marcha"
        return 0
    fi
    if [ ! -f "$dir/compose.yaml" ]; then
        mkdir -p -m 700 "$DOCKER_DIR" "$dir" || return 1
        ( umask 077
          printf 'DB_ROOT_PASS=%s\n' "$(head -c 18 /dev/urandom | base64 | tr -d '/+=\n')" > "$dir/.env"
          { printf 'name: %s\nservices:\n  db:\n    image: mariadb:%s\n    container_name: %s\n    restart: "no"\n' "$name" "$v" "$name"
            printf '    environment:\n      MARIADB_ROOT_PASSWORD: ${DB_ROOT_PASS}\n      MARIADB_AUTO_UPGRADE: "1"\n'
            printf '    command: ["--character-set-server=utf8mb4", "--collation-server=utf8mb4_unicode_ci", "--max-allowed-packet=512M"]\n'
            printf '    volumes:\n      - "datos:/var/lib/mysql"\n    networks: [nexum]\n'
            printf 'volumes:\n  datos:\n    name: %s\n' "$name"
            printf 'networks:\n  nexum:\n    external: true\n    name: nexum\n'; } > "$dir/compose.yaml" ) || return 1
    fi
    docker_net || return 1
    dk compose --project-directory "$dir" -f "$dir/compose.yaml" up -d || return 1
    for i in $(seq 90); do
        docker_maria_sql "$v" -e "SELECT 1" < /dev/null > /dev/null 2>&1 && return 0
        sleep 1
    done
    echo "La MariaDB $v de Docker no responde (mira sus registros en la pestaña Docker)"
    return 1
}

# MariaDB comunes que hay (sus versiones)
function docker_maria_versions() {
    local d
    for d in "$DOCKER_DIR"/mariadb-*/; do
        d=$(basename "$d")
        d=${d#mariadb-}
        [[ " $DOCKER_MARIADB_VERSIONS " == *" $d "* ]] && [ -f "$DOCKER_DIR/mariadb-$d/compose.yaml" ] && echo "$d"
    done
}

# Certificado propio de *.docker.local (no es de una CA: solo vale para esos dominios), en una carpeta
# solo tuya: el Apache del contenedor lo lee como el root del contenedor, que en Docker sin root eres tu
function docker_web_cert() {
    local c=$DOCKER_WEB_DIR/certs
    if [ -s "$c/docker.local.crt" ] && [ -s "$c/docker.local.key" ]; then
        openssl x509 -in "$c/docker.local.crt" -noout -text 2> /dev/null | grep -q 'DNS:\*\.docker\.test' && return 0
        [ "$DRY" -eq 1 ] || rm -f "$c/docker.local.crt" "$c/docker.local.key"
    fi
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] certificado propio de *.docker.local en $c"
        return 0
    fi
    mkdir -p -m 700 "$DOCKER_DIR" "$DOCKER_WEB_DIR" "$c" || return 1
    if ! ( umask 077; openssl req -x509 -nodes -newkey rsa:2048 -days 3650 -subj "/CN=docker.local" \
            -addext "basicConstraints=critical,CA:FALSE" -addext "extendedKeyUsage=serverAuth" \
            -addext "subjectAltName=DNS:docker.local,DNS:*.docker.local,DNS:docker.test,DNS:*.docker.test" \
            -keyout "$c/docker.local.key" -out "$c/docker.local.crt" > /dev/null 2>&1 ); then
        rm -f "$c/docker.local.key" "$c/docker.local.crt"
        echo "No se ha podido crear el certificado de *.docker.local"
        return 1
    fi
    echo "Certificado propio de *.docker.local y *.docker.test (solo vale para esos dominios)"
}

# Chrome, Chromium y Firefox aceptan sin aviso el certificado de *.docker.local: va a sus almacenes
# con confianza P (la de un servidor, no la de una CA), como los de los proyectos de LAMPP
function docker_web_trust() {
    local crt=$DOCKER_WEB_DIR/certs/docker.local.crt nick="lvm-instalador docker.local" d i n=0
    # (en las pruebas, nunca en los navegadores de verdad)
    [ -n "$TEST_DIR" ] && return 0
    [ -f "$crt" ] || [ "$DRY" -eq 1 ] || return 0
    if ! command -v certutil > /dev/null; then
        echo "Para que Chrome y Firefox acepten *.docker.local sin aviso falta certutil: sudo apt install libnss3-tools"
        return 0
    fi
    for d in "$HOME/.pki/nssdb" "$HOME"/snap/chromium/current/.pki/nssdb "$HOME"/.mozilla/firefox/*/ \
             "$HOME"/snap/firefox/common/.mozilla/firefox/*/; do
        d=${d%/}
        [ -f "$d/cert9.db" ] || continue
        # (el de antes, si el certificado se ha rehecho: con el mismo nombre)
        for i in 1 2 3 4 5; do
            no_tty certutil -L -d "sql:$d" -n "$nick" > /dev/null 2>&1 || break
            run no_tty certutil -D -d "sql:$d" -n "$nick" || break
            [ "$DRY" -eq 0 ] || break
        done
        run no_tty certutil -A -d "sql:$d" -n "$nick" -t "P,," -i "$crt" && n=$((n + 1))
    done
    [ $n -gt 0 ] && echo "El navegador acepta el certificado de *.docker.local (si Chrome estaba abierto, cierralo y vuelve a abrirlo)"
    return 0
}

# Lineas de /etc/hosts de los dominios de Docker: docker_web_hosts poner|quitar <dominio...>. poner: a la
# direccion del Apache de Docker (y fuera de cualquier otra linea); quitar: fuera. Solo esos dominios
function docker_web_hosts() {
    local mode=$1 copy rc n names=()
    shift
    # (con el DNS comodin, los *.docker.test los contesta el; solo se tocan los de antes)
    for n in "$@"; do
        docker_dns_on && [[ "$n" == *.docker.test ]] && continue
        names+=("$n")
    done
    set -- "${names[@]}"
    [ $# -gt 0 ] || return 0
    mkdir -p -m 700 "$LOG_DIR" || return 1
    copy=$(mktemp "$LOG_DIR/hosts-docker-XXXXXX") || return 1
    python3 -I - "$HOSTS_FILE" "$copy" "$mode" "$(docker_web_get IP)" "$@" << 'EOF'
import re, sys
src, dst, mode, ip = sys.argv[1:5]
names = [n.lower() for n in sys.argv[5:]]
lines = open(src).read().splitlines()
now = {}
for line in lines:
    w = line.split("#", 1)[0].split()
    for n in w[1:]:
        now.setdefault(n.lower(), w[0])
if mode == "poner" and all(now.get(n) == ip for n in names):
    out = lines
else:
    out = []
    for line in lines:
        body, sep, comment = line.partition("#")
        w = body.split()
        if len(w) >= 2 and re.match(r"^(127\.\d+\.\d+\.\d+|::1)$", w[0]):
            keep = [n for n in w[1:] if n.lower() not in names]
            if len(keep) != len(w) - 1:
                if not keep:
                    continue
                line = w[0] + " " + " ".join(keep) + (" " + sep + comment if sep else "")
        out.append(line)
    if mode == "poner":
        out.append(ip + " " + " ".join(names))
open(dst, "w").write("\n".join(out) + "\n")
EOF
    if cmp -s "$copy" "$HOSTS_FILE"; then
        rm -f "$copy"
        return 0
    fi
    edit_hosts --aplicar "$copy"
    rc=$?
    rm -f "$copy"
    return $rc
}

# Reglas de seguridad de todas las webs, las mismas que en LAMPP (de UNKNOWN_HOST_VHOST: ficheros que
# no se sirven, CORS y la barrera entre webs, si esta encendida)
function docker_web_security() {
    local text="# Configuracion, repositorios${UNKNOWN_HOST_VHOST#*$'\n'# Configuracion, repositorios}"
    if cross_site_on; then
        printf '%s\n' "$text"
    else
        awk '/^# >>> barrera entre webs/ { s = 1 } !s { print } /^# <<< barrera entre webs/ { s = 0 }' <<< "$text"
    fi
}

# Vhosts de un proyecto en el Apache de Docker: http lleva a https, y en https la carpeta del proyecto
# (la misma ruta que en su contenedor de PHP) con los .php a su version de PHP. Una tienda, solo la
# version elegida (ACTIVA)
function docker_web_site() {
    local slug=$1 folder versions v dom
    folder=$(docker_conf "$slug" CARPETA)
    versions=$(docker_conf "$slug" PHP)
    [ "$(docker_conf "$slug" TIPO)" == ps ] && versions=$(docker_conf "$slug" ACTIVA)
    printf '# %s (%s)\n' "$slug" "$folder"
    for v in $versions; do
        dom=$(docker_web_domain "$slug" "$v")
        printf '<VirtualHost *:80>\n    ServerName %s\n    Redirect permanent / %s/\n</VirtualHost>\n' "$dom" "$(docker_web_url "$dom")"
        printf '<VirtualHost *:443>\n    ServerName %s\n    DocumentRoot "/opt/lampp/htdocs/%s"\n' "$dom" "$folder"
        printf '    SSLEngine on\n    SSLCertificateFile /certs/docker.local.crt\n    SSLCertificateKeyFile /certs/docker.local.key\n'
        # (con su PHP parado, por ejemplo al llevar horas sin visitas, lo dice en vez de un error sin mas.
        # Solo los errores del propio Apache: un 503 de la web, como el modo mantenimiento, pasa igual)
        printf '    ErrorDocument 502 "%s"\n    ErrorDocument 503 "%s"\n' "$DOCKER_STOPPED_MSG" "$DOCKER_STOPPED_MSG"
        printf '    <FilesMatch "\\.php$">\n        SetHandler "proxy:fcgi://%s:9000"\n    </FilesMatch>\n' "$(docker_web_container "$slug" "$v")"
        [ "$(docker_conf "$slug" TIPO)" == ps ] || docker_web_media "$folder"
        printf '</VirtualHost>\n'
    done
}

# Reglas de las imagenes de produccion de un WordPress en el Apache de Docker (su dominio, el de media-proyecto,
# el mismo que con LAMPP): lo que falte de wp-content/uploads (imagenes, videos y PDF; solo GET y HEAD) se pide
# a su web real con una redireccion 302. Nada si no tiene dominio de produccion
function docker_web_media() {
    local folder=$1 prod
    prod=$(media_saved "$folder")
    valid_domain "$prod" && [[ "$prod" != *.local && "$prod" != *.test && "$prod" != localhost && "$prod" != *.localhost ]] || return 0
    printf '    # nexum-media %s: lo que falte de wp-content/uploads se pide a produccion (media-proyecto)\n' "$prod"
    printf '    RewriteEngine On\n    RewriteCond %%{REQUEST_METHOD} ^(GET|HEAD)$\n'
    printf '    RewriteCond /opt/lampp/htdocs/%s%%{REQUEST_URI} !-f\n' "$folder"
    printf '    RewriteRule ^/(wp-content/uploads/.+\\.(%s))$ https://%s/$1 [NC,R=302,L]\n' "$MEDIA_EXT" "$prod"
}

# Configuracion del Apache de Docker (httpd.conf, las reglas, un vhost por proyecto y el de phpMyAdmin,
# en DOCKER_WEB_DIR/conf) y su compose.yaml. Se escribe entera cada vez (lo sabe todo de proyecto.conf).
# La carpeta conf va montada en el contenedor: se cambia lo de dentro, nunca la carpeta (el contenedor
# seguiria viendo la de antes)
DOCKER_WEB_CONF=/usr/local/apache2/conf/nexum/httpd.conf
function docker_web_write() {
    local d=$DOCKER_WEB_DIR p tmp pma_hosts="" v
    [ "$DRY" -eq 1 ] && return 0
    mkdir -p -m 700 "$DOCKER_DIR" "$d" || return 1
    tmp=$(mktemp -d "$d/.nexum-XXXXXX") || return 1
    mkdir -p "$tmp/sitios" || return 1
    docker_web_security > "$tmp/seguridad.conf" || return 1
    cat > "$tmp/httpd.conf" << 'EOF'
# Apache de Docker de lvm-instalador (se rehace solo: no se edita a mano)
ServerRoot "/usr/local/apache2"
Listen 80
Listen 443
LoadModule mpm_event_module modules/mod_mpm_event.so
# (en local basta un proceso con sus hilos: no tres esperando, como trae de fabrica)
StartServers 1
ServerLimit 4
ThreadsPerChild 25
MinSpareThreads 5
MaxSpareThreads 50
MaxRequestWorkers 100
LoadModule unixd_module modules/mod_unixd.so
LoadModule authz_core_module modules/mod_authz_core.so
LoadModule authz_host_module modules/mod_authz_host.so
LoadModule authz_user_module modules/mod_authz_user.so
LoadModule authn_core_module modules/mod_authn_core.so
LoadModule authn_file_module modules/mod_authn_file.so
LoadModule auth_basic_module modules/mod_auth_basic.so
LoadModule access_compat_module modules/mod_access_compat.so
LoadModule mime_module modules/mod_mime.so
LoadModule log_config_module modules/mod_log_config.so
LoadModule env_module modules/mod_env.so
LoadModule setenvif_module modules/mod_setenvif.so
LoadModule headers_module modules/mod_headers.so
LoadModule expires_module modules/mod_expires.so
LoadModule filter_module modules/mod_filter.so
LoadModule deflate_module modules/mod_deflate.so
LoadModule rewrite_module modules/mod_rewrite.so
LoadModule dir_module modules/mod_dir.so
LoadModule alias_module modules/mod_alias.so
LoadModule version_module modules/mod_version.so
LoadModule socache_shmcb_module modules/mod_socache_shmcb.so
LoadModule ssl_module modules/mod_ssl.so
LoadModule proxy_module modules/mod_proxy.so
LoadModule proxy_fcgi_module modules/mod_proxy_fcgi.so
LoadModule proxy_http_module modules/mod_proxy_http.so
# (los procesos que sirven las webs, con un usuario sin privilegios del contenedor: leen los ficheros
# del proyecto, no los cambian. El PHP va en su contenedor, que si los puede cambiar)
User daemon
Group daemon
ServerName docker.local
ServerSignature Off
ServerTokens Prod
ErrorLog /proc/self/fd/2
LogLevel warn
LogFormat "%v %h %t \"%r\" %>s %b" nexum
CustomLog /proc/self/fd/1 nexum
TypesConfig conf/mime.types
DirectoryIndex index.php index.html index.htm
Timeout 300
ProxyTimeout 300
SSLProtocol all -SSLv3 -TLSv1 -TLSv1.1
SSLSessionCache "shmcb:/usr/local/apache2/logs/ssl_scache(512000)"
<Directory />
    AllowOverride None
    Require all denied
</Directory>
<Directory "/opt/lampp/htdocs">
    Options FollowSymLinks
    AllowOverride All
    Require all granted
</Directory>
Include conf/nexum/seguridad.conf
IncludeOptional conf/nexum/sitios/*.conf
EOF
    # (el primero: los dominios sin proyecto, con un 403)
    { printf '# Dominios sin ningun proyecto en Docker\n'
      for p in 80 443; do
          printf '<VirtualHost *:%s>\n    ServerName docker.local\n' "$p"
          [ $p == 443 ] && printf '    SSLEngine on\n    SSLCertificateFile /certs/docker.local.crt\n    SSLCertificateKeyFile /certs/docker.local.key\n'
          printf '    <Location />\n        Require all denied\n        ErrorDocument 403 "Este dominio no tiene ningun proyecto en Docker (lvm-instalador)"\n    </Location>\n</VirtualHost>\n'
      done; } > "$tmp/sitios/000-defecto.conf"
    # phpMyAdmin: su contenedor, por https://pma.docker.local o pma.docker.test (con su pantalla de acceso)
    { printf '<VirtualHost *:80>\n    ServerName %s\n    Redirect permanent / %s/\n</VirtualHost>\n' "$(docker_web_pma)" "$(docker_web_url "$(docker_web_pma)")"
      printf '<VirtualHost *:443>\n    ServerName %s\n' "$(docker_web_pma)"
      printf '    SSLEngine on\n    SSLCertificateFile /certs/docker.local.crt\n    SSLCertificateKeyFile /certs/docker.local.key\n'
      printf '    ProxyPass / http://nexum-pma/\n    ProxyPassReverse / http://nexum-pma/\n</VirtualHost>\n'; } > "$tmp/sitios/001-phpmyadmin.conf"
    for p in $(docker_web_projects); do
        docker_web_site "$p" > "$tmp/sitios/$p.conf" || return 1
    done
    for v in $(docker_maria_versions); do pma_hosts+=",$(docker_maria_name "$v")"; done
    pma_hosts=${pma_hosts#,}
    { printf 'name: nexum-web\nservices:\n'
      printf '  web:\n    image: %s\n    container_name: nexum-web\n    restart: "no"\n' "$DOCKER_WEB_IMAGE"
      printf '    ports:\n      - "%s:%s:80"\n      - "%s:%s:443"\n' "$(docker_web_get IP)" "$(docker_web_get HTTP)" "$(docker_web_get IP)" "$(docker_web_get HTTPS)"
      printf '    volumes:\n      - "%s:/opt/lampp/htdocs:ro"\n' "$HTDOCS_DIR"
      printf '      - "./conf:/usr/local/apache2/conf/nexum:ro"\n      - "./certs:/certs:ro"\n'
      printf '    command: ["httpd-foreground", "-f", "%s"]\n    networks: [nexum]\n' "$DOCKER_WEB_CONF"
      printf '  pma:\n    image: %s\n    container_name: nexum-pma\n    restart: "no"\n    environment:\n' "$DOCKER_PMA_IMAGE"
      printf '      PMA_HOSTS: "%s"\n      PMA_ABSOLUTE_URI: "%s/"\n      UPLOAD_LIMIT: 64M\n    networks: [nexum]\n' \
          "${pma_hosts:-$(docker_maria_name 11.8)}" "$(docker_web_url "$(docker_web_pma)")"
      printf 'networks:\n  nexum:\n    external: true\n    name: nexum\n'; } > "$tmp/compose.yaml"
    chmod -R go-rwx "$tmp"
    # (dentro de conf, que no se cambia: los ficheros y, de golpe, la carpeta de los vhosts)
    mkdir -p -m 700 "$d/conf" || return 1
    rm -rf "$d/conf/sitios.antes"
    [ -d "$d/conf/sitios" ] && mv "$d/conf/sitios" "$d/conf/sitios.antes"
    mv "$tmp/sitios" "$d/conf/sitios" && mv -f "$tmp/seguridad.conf" "$tmp/httpd.conf" "$d/conf/" \
        && mv -f "$tmp/compose.yaml" "$d/compose.yaml" || return 1
    rm -rf "$tmp" "$d/conf/sitios.antes"
}

# Estado del Apache de Docker: marcha, parado o nuevo (sin contenedor)
function docker_web_state() {
    local s
    s=$(dk ps -a --filter name='^nexum-web$' --format '{{.State}}' 2> /dev/null | head -1)
    case $s in running) echo marcha ;; "") echo nuevo ;; *) echo parado ;; esac
}

# Arranca el Apache de Docker y su phpMyAdmin (con su configuracion al dia, su certificado y la linea de
# pma.docker.local en hosts). Si ya estaba en marcha, recarga su configuracion sin cortar nada
function docker_web_up() {
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] Apache de Docker (nexum-web) en $(docker_web_get IP), puertos $(docker_web_get HTTP) y $(docker_web_get HTTPS)"
        return 0
    fi
    if ! docker_web_ports_ok; then
        echo "Docker sin root aun no puede usar los puertos $(docker_web_get HTTP) y $(docker_web_get HTTPS)."
        echo "Pulsa «Permitir» en Configuracion, Docker (o: nexum docker-web permitir), o elige otros puertos."
        return 1
    fi
    docker_web_cert && docker_web_write && docker_net || return 1
    docker_web_hosts poner "$(docker_web_pma)" || return 1
    local was
    was=$(docker_web_state)
    dk compose --project-directory "$DOCKER_WEB_DIR" -f "$DOCKER_WEB_DIR/compose.yaml" up -d || return 1
    [ "$was" == marcha ] && docker_web_reload --sin-escribir
    return 0
}

# Vuelve a escribir la configuracion del Apache de Docker y, si esta en marcha, la recarga sin cortar las
# conexiones (si Apache no la acepta, lo dice y sigue con la de antes)
function docker_web_reload() {
    local out
    [ "$DRY" -eq 1 ] && return 0
    [ "$1" == --sin-escribir ] || docker_web_write || return 1
    [ "$(docker_web_state)" == marcha ] || return 0
    if ! out=$(dk exec nexum-web httpd -f "$DOCKER_WEB_CONF" -t 2>&1); then
        echo "El Apache de Docker no acepta su configuracion nueva: sigue con la de antes"
        sed 's/^/  /' <<< "$out" | tail -5
        return 1
    fi
    dk exec nexum-web httpd -f "$DOCKER_WEB_CONF" -k graceful > /dev/null 2>&1
}

# docker-web [estado] | puertos <ip> <http> <https> | permitir | arrancar | parar | confiar
#   estado: W|direccion|http|https|estado (marcha, parado o nuevo)|puertos permitidos (1/0)
function docker_web_command() {
    case ${1:-estado} in
        estado)
            echo "W|$(docker_web_get IP)|$(docker_web_get HTTP)|$(docker_web_get HTTPS)|$(docker_ready && docker_web_state || echo "?")|$(docker_web_ports_ok && echo 1 || echo 0)|$(docker_web_tld)|$(docker_dns_on && echo 1 || echo 0)" ;;
        dns) shift; docker_dns_command "$@" ;;
        puertos) docker_web_set "$2" "$3" "$4" ;;
        permitir) docker_web_allow ;;
        arrancar)
            docker_ready || { echo "Docker sin root no esta en marcha"; return 1; }
            docker_web_up ;;
        parar)
            [ "$DRY" -eq 1 ] && { echo "  [simulacion] Apache de Docker y phpMyAdmin parados"; return 0; }
            run dk compose --project-directory "$DOCKER_WEB_DIR" -f "$DOCKER_WEB_DIR/compose.yaml" stop ;;
        confiar) docker_web_trust ;;
        *) echo "Uso: nexum docker-web [estado] | puertos <ip> <http> <https> | permitir | arrancar | parar | confiar | dns activar|quitar"; return 1 ;;
    esac
}

# docker-web puertos <ip> <http> <https>: otra direccion (siempre de 127.x) u otros puertos. Con los de
# siempre (80 y 443) no puede ser 127.0.0.1: los usa el Apache de LAMPP. Los dominios de Docker pasan a
# la direccion nueva en /etc/hosts y el Apache de Docker se vuelve a crear. (Docker sin root no deja que
# dos contenedores publiquen el mismo numero de puerto aunque sea en otra direccion: no puede coincidir
# con el de un phpMyAdmin de un proyecto de antes, 28080 en adelante)
function docker_web_set() {
    local ip=$1 http=$2 https=$3 p domains=()
    if ! docker_web_valid_ip "$ip"; then
        echo "Direccion no valida: $ip (tiene que ser de este equipo: 127.x.x.x, como 127.0.0.2)"
        return 1
    fi
    for p in "$http" "$https"; do
        [[ "$p" =~ ^[1-9][0-9]{0,4}$ ]] && [ "$p" -le 65535 ] || { echo "Puerto no valido: $p"; return 1; }
    done
    [ "$http" != "$https" ] || { echo "Los puertos HTTP y HTTPS tienen que ser distintos"; return 1; }
    if [ "$ip" == 127.0.0.1 ] && { [ "$http" == 80 ] || [ "$https" == 443 ] || [ "$http" == 443 ] || [ "$https" == 80 ]; }; then
        echo "En 127.0.0.1 los puertos 80 y 443 son del Apache de LAMPP: usa otra direccion (127.0.0.2) u otros puertos"
        return 1
    fi
    echo "Apache de Docker: $ip, puertos $http (http) y $https (https)"
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] se guarda en $DOCKER_WEB_FILE y los dominios de Docker pasan a $ip en $HOSTS_FILE"
        return 0
    fi
    mkdir -p -m 700 "$DOCKER_DIR" || return 1
    docker_web_conf_write "$ip" "$http" "$https" "$(docker_web_tld)" "$(docker_web_get DNS)" || return 1
    docker_web_ports_ok || echo "Aviso: Docker sin root aun no puede usar esos puertos: pulsa «Permitir» (nexum docker-web permitir)"
    [ -d "$DOCKER_WEB_DIR" ] || return 0
    sudo_first || return 1
    # (con el DNS comodin, este responde con la direccion nueva)
    docker_dns_on && { docker_dns_install || return 1; }
    for p in $(docker_web_projects); do
        mapfile -t -O "${#domains[@]}" domains < <(docker_web_domains "$p")
    done
    docker_web_hosts poner "$(docker_web_pma)" "${domains[@]}" || return 1
    if docker_ready && [ "$(docker_web_state)" != nuevo ] && docker_web_ports_ok; then
        docker_web_up || return 1
    else
        docker_web_write
    fi
    echo "Listo: los proyectos de Docker se abren en $(docker_web_url "<proyecto>.$(docker_web_tld)")"
}

# docker-web permitir: Docker sin root puede abrir los puertos del Apache de Docker. Linux deja los de
# menos de 1024 solo a root; se baja ese limite (net.ipv4.ip_unprivileged_port_start, en DOCKER_SYSCTL)
# hasta el mas bajo de los dos. Desde entonces cualquier programa del equipo puede abrir esos puertos
# (en un equipo de desarrollo, como cualquier puerto alto): pide la contraseña de administrador
function docker_web_allow() {
    local http https low
    http=$(docker_web_get HTTP) https=$(docker_web_get HTTPS)
    low=$http
    [ "$https" -lt "$low" ] && low=$https
    if docker_web_ports_ok; then
        echo "Docker sin root ya puede usar los puertos $http y $https"
        return 0
    fi
    echo "Docker sin root podra usar los puertos desde el $low (net.ipv4.ip_unprivileged_port_start en $DOCKER_SYSCTL)"
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] sudo tee $DOCKER_SYSCTL y sudo sysctl -p $DOCKER_SYSCTL"
        return 0
    fi
    sudo_first || return 1
    printf '# lvm-instalador: Docker sin root puede usar los puertos del Apache de Docker\nnet.ipv4.ip_unprivileged_port_start = %s\n' "$low" \
        | sudo tee "$DOCKER_SYSCTL" > /dev/null && sudo sysctl -q -p "$DOCKER_SYSCTL" || return 1
    docker_web_ports_ok || { echo "No se ha podido cambiar el limite de los puertos"; return 1; }
    echo "Listo: Docker sin root ya puede usar los puertos $http y $https"
}

# El DNS en Linux: un servicio del sistema con un usuario sin privilegios que se crea cada vez
# (DynamicUser) y systemd-resolved, que le manda solo lo de docker.test (Domains=~docker.test: un DNS con
# solo dominios de enrutado no recibe ninguna otra pregunta). Todo de root
DOCKER_DNS_SCRIPT=${LVM_DNS_SCRIPT:-/usr/local/lib/nexum/nexum-dns.py}
DOCKER_DNS_UNIT=${LVM_DNS_UNIT:-/etc/systemd/system/nexum-dns.service}
DOCKER_DNS_RESOLVED=${LVM_DNS_RESOLVED:-/etc/systemd/resolved.conf.d/60-nexum-docker.conf}
function docker_dns_install() {
    local ip d
    ip=$(docker_web_get IP)
    [ "$DRY" -eq 1 ] && return 0
    for d in "$(dirname "$DOCKER_DNS_SCRIPT")" "$(dirname "$DOCKER_DNS_RESOLVED")"; do
        sudo install -d -m 755 "$d" || return 1
    done
    printf '%s\n' "$DOCKER_DNS_PY" | sudo tee "$DOCKER_DNS_SCRIPT" > /dev/null && sudo chmod 644 "$DOCKER_DNS_SCRIPT" || return 1
    printf '%s\n' "# Nexum Dev Stack: DNS de *.docker.test, solo en 127.0.0.1 (lo pone lvm-instalador docker-web dns activar)" \
        "[Unit]" "Description=Nexum Dev Stack: DNS de *.docker.test" "After=network.target" "" "[Service]" \
        "ExecStart=/usr/bin/python3 -I $DOCKER_DNS_SCRIPT 127.0.0.1 $DOCKER_DNS_PORT docker.test $ip" \
        "DynamicUser=yes" "ProtectSystem=strict" "ProtectHome=yes" "PrivateTmp=yes" "PrivateDevices=yes" "NoNewPrivileges=yes" \
        "RestrictAddressFamilies=AF_INET AF_INET6" "CapabilityBoundingSet=" "Restart=on-failure" "" "[Install]" "WantedBy=multi-user.target" \
        | sudo tee "$DOCKER_DNS_UNIT" > /dev/null || return 1
    printf '%s\n' "# Nexum Dev Stack: lo de docker.test, al DNS de Nexum (y nada mas)" "[Resolve]" \
        "DNS=127.0.0.1:$DOCKER_DNS_PORT" "Domains=~docker.test" | sudo tee "$DOCKER_DNS_RESOLVED" > /dev/null || return 1
    sudo systemctl daemon-reload && sudo systemctl enable nexum-dns.service > /dev/null 2>&1 \
        && sudo systemctl restart nexum-dns.service && sudo systemctl restart systemd-resolved
}

function docker_dns_uninstall() {
    [ "$DRY" -eq 1 ] && return 0
    sudo systemctl disable --now nexum-dns.service > /dev/null 2>&1
    sudo rm -f "$DOCKER_DNS_UNIT" "$DOCKER_DNS_RESOLVED" "$DOCKER_DNS_SCRIPT"
    sudo systemctl daemon-reload
    sudo systemctl restart systemd-resolved
}

# DNS comodin de *.docker.test (docker-web dns activar): un DNS minimo, solo en 127.0.0.1, que contesta
# la direccion del Apache de Docker a cualquier <algo>.docker.test y rechaza todo lo demas. Asi los
# dominios de Docker ya no van en /etc/hosts (ni piden la contraseña al añadir proyectos o versiones).
# Solo para *.docker.test: web.local, los proyectos de siempre y los dominios falseados de las tiendas
# siguen en /etc/hosts, que se mira antes. (.local es de mDNS: un DNS para *.docker.local no se
# consultaria nunca)
DOCKER_DNS_PORT=5354
DOCKER_DNS_PY=$(cat <<'DNSPY'
# DNS de *.docker.test de Nexum Dev Stack (lo pone lvm-instalador docker-web dns activar: no se edita a
# mano). nexum-dns.py <direccion> <puerto> <zona> <ip>: contesta <ip> a la zona y a lo que acabe en ella
# (registros A; los demas tipos, sin datos) y REFUSED a todo lo demas. UDP y TCP, sin estado
import socket, socketserver, struct, sys, threading

HOST, PORT, ZONE, IP = sys.argv[1], int(sys.argv[2]), sys.argv[3].lower().strip("."), sys.argv[4]
ADDR = socket.inet_aton(IP)


def answer(q):
    if len(q) < 17:
        return None
    tid, flags, qd = struct.unpack(">HHH", q[:6])
    # (solo preguntas normales, de una en una)
    if flags & 0x8000 or (flags >> 11) & 0xF or qd != 1:
        return None
    i, labels = 12, []
    while True:
        if i >= len(q):
            return None
        n = q[i]
        i += 1
        if n == 0:
            break
        if n > 63 or i + n > len(q):
            return None
        labels.append(q[i:i + n].decode("ascii", "replace").lower())
        i += n
    if i + 4 > len(q):
        return None
    qtype, qclass = struct.unpack(">HH", q[i:i + 4])
    question = q[12:i + 4]
    name = ".".join(labels)
    rd = flags & 0x0100
    if name != ZONE and not name.endswith("." + ZONE):
        return struct.pack(">HHHHHH", tid, 0x8000 | rd | 0x0080 | 5, 1, 0, 0, 0) + question
    if qtype == 1 and qclass == 1:
        rr = b"\xc0\x0c" + struct.pack(">HHIH", 1, 1, 60, 4) + ADDR
        return struct.pack(">HHHHHH", tid, 0x8400 | rd | 0x0080, 1, 1, 0, 0) + question + rr
    return struct.pack(">HHHHHH", tid, 0x8400 | rd | 0x0080, 1, 0, 0, 0) + question


class UDP(socketserver.BaseRequestHandler):
    def handle(self):
        data, sock = self.request
        out = answer(data)
        if out:
            sock.sendto(out, self.client_address)


class TCP(socketserver.StreamRequestHandler):
    def handle(self):
        self.connection.settimeout(5)
        try:
            size = struct.unpack(">H", self.rfile.read(2))[0]
            out = answer(self.rfile.read(size))
            if out:
                self.wfile.write(struct.pack(">H", len(out)) + out)
        except (OSError, struct.error):
            pass


class UDPServer(socketserver.ThreadingMixIn, socketserver.UDPServer):
    daemon_threads = True
    allow_reuse_address = True


class TCPServer(socketserver.ThreadingMixIn, socketserver.TCPServer):
    daemon_threads = True
    allow_reuse_address = True


udp = UDPServer((HOST, PORT), UDP)
tcp = TCPServer((HOST, PORT), TCP)
threading.Thread(target=tcp.serve_forever, daemon=True).start()
udp.serve_forever()
DNSPY
)

# ¿Contesta el DNS comodin? (como lo buscan los navegadores: con el sistema)
function docker_dns_works() {
    local ip got i
    ip=$(docker_web_get IP)
    for i in $(seq 20); do
        got=$(python3 -I -c 'import socket, sys
try:
    print(socket.getaddrinfo(sys.argv[1], None, socket.AF_INET)[0][4][0])
except OSError:
    pass' "nexum-comprobacion.docker.test" 2> /dev/null)
        [ "$got" == "$ip" ] && return 0
        sleep 0.5
    done
    return 1
}

# docker_web_retld: los proyectos del Apache de Docker con el final de los dominios de ahora (docker_web_tld):
# su dominio, su configuracion de cada version (WordPress: WP_HOME), el dominio de una tienda en su BBDD y
# sus contenedores de PHP en marcha, rehechos (su configuracion va montada fichero a fichero)
function docker_web_retld() {
    local p state
    for p in $(docker_web_projects); do
        docker_conf_set "$p" DOMINIO "$(docker_web_domain "$p" "$(docker_conf "$p" ACTIVA)")" || return 1
        for v in $(docker_conf "$p" PHP); do
            docker_web_config "$p" "$v" || return 1
        done
        docker_web_compose "$p" || return 1
        if docker_ready; then
            if [ "$(docker_conf "$p" TIPO)" == ps ] && docker_maria_up "$(docker_conf "$p" MARIADB)" > /dev/null; then
                docker_web_ps_domain "$p"
            fi
            state=$(docker_state "$p")
            if [ "$state" == marcha ] || [ "$state" == parcial ]; then
                dk compose --project-directory "$DOCKER_DIR/$p" -f "$DOCKER_DIR/$p/compose.yaml" up -d --force-recreate \
                    $(docker_web_services "$p") > /dev/null || return 1
            fi
        fi
        echo "  $(docker_conf "$p" CARPETA): $(docker_web_url "$(docker_web_domain "$p" "$(docker_conf "$p" ACTIVA)")")"
    done
}

# docker-web dns activar: pone el DNS comodin y pasa los proyectos del Apache de Docker a *.docker.test
# (sus lineas de /etc/hosts se quitan). Si no contesta, se quita y todo sigue como estaba. Pide la
# contraseña de administrador una vez
function docker_dns_activate() {
    local old p olds=()
    if docker_dns_on && docker_dns_works; then
        echo "El DNS de *.docker.test ya va: los dominios de Docker no van en /etc/hosts"
        return 0
    fi
    echo "DNS de *.docker.test: los dominios de Docker pasan a .docker.test y dejan de ir en /etc/hosts"
    echo "(web.local, los proyectos de siempre y los dominios falseados de las tiendas siguen igual)"
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] DNS en 127.0.0.1:$DOCKER_DNS_PORT para *.docker.test y los proyectos de Docker a .docker.test"
        return 0
    fi
    sudo_first || return 1
    docker_dns_install || { echo "No se ha podido poner el DNS de *.docker.test"; docker_dns_uninstall; return 1; }
    if ! docker_dns_works; then
        echo "El DNS de *.docker.test no contesta: se quita y todo sigue como estaba"
        docker_dns_uninstall
        return 1
    fi
    old=$(docker_web_tld)
    if [ "$old" != docker.test ]; then
        olds+=("pma.$old")
        for p in $(docker_web_projects); do
            mapfile -t -O "${#olds[@]}" olds < <(docker_web_domains "$p")
        done
    fi
    docker_web_conf_write "$(docker_web_get IP)" "$(docker_web_get HTTP)" "$(docker_web_get HTTPS)" docker.test 1 || return 1
    if [ "$old" != docker.test ] && [ -n "$(docker_web_projects)" ]; then
        echo "Los proyectos del Apache de Docker pasan a .docker.test:"
        docker_web_retld || return 1
    fi
    [ ${#olds[@]} -gt 0 ] && docker_web_hosts quitar "${olds[@]}"
    if [ -d "$DOCKER_WEB_DIR" ]; then
        docker_web_cert && docker_web_trust
        if docker_ready && [ "$(docker_web_state)" != nuevo ]; then
            docker_web_up || return 1
        else
            docker_web_write
        fi
    fi
    echo "Listo: los proyectos de Docker se abren en $(docker_web_url "<proyecto>.docker.test") y phpMyAdmin en $(docker_web_url "$(docker_web_pma)")"
}

# docker-web dns quitar: sin el DNS comodin. Los dominios siguen siendo .docker.test y vuelven a /etc/hosts
function docker_dns_deactivate() {
    local p domains=()
    echo "Se quita el DNS de *.docker.test: sus dominios vuelven a /etc/hosts"
    [ "$DRY" -eq 1 ] && return 0
    sudo_first || return 1
    docker_web_conf_write "$(docker_web_get IP)" "$(docker_web_get HTTP)" "$(docker_web_get HTTPS)" "$(docker_web_tld)" 0 || return 1
    docker_dns_uninstall
    for p in $(docker_web_projects); do
        mapfile -t -O "${#domains[@]}" domains < <(docker_web_domains "$p")
    done
    [ -d "$DOCKER_WEB_DIR" ] && { docker_web_hosts poner "$(docker_web_pma)" "${domains[@]}" || return 1; }
    echo "Listo: los dominios de Docker van otra vez en /etc/hosts"
}

function docker_dns_command() {
    case $1 in
        activar) docker_dns_activate ;;
        quitar) docker_dns_deactivate ;;
        *) echo "Uso: nexum docker-web dns activar|quitar"; return 1 ;;
    esac
}

# Configuracion de una version de PHP de un proyecto para su contenedor (config-83.php: su BBDD en la
# MariaDB comun y, en WordPress, el dominio de esa version). Nada si el proyecto no la tiene
function docker_web_config() {
    local slug=$1 v=$2 dir=$DOCKER_DIR/$1 rel
    # (el dominio, con el puerto si no es el 443: WordPress lo pone en sus enlaces)
    local url
    url=$(docker_web_url "$(docker_web_domain "$slug" "$v")")
    local folder hosts
    folder=$(docker_conf "$slug" CARPETA)
    # (las de la web en local: web.local y su dominio propio, si tiene. En lo que devuelve, las del contenedor)
    hosts="$PROJECT_VHOST $(custom_domain "$folder" 2> /dev/null)"
    local server
    # (la BBDD: la de una version LAMPP en vivo, por su puente, o la de la MariaDB comun)
    if [ -n "$(docker_conf "$slug" LAMPP_BD)" ]; then
        server=$(lampp_bd_bridge "$(docker_conf "$slug" LAMPP_BD)")
    else
        server=$(docker_maria_name "$(docker_conf "$slug" MARIADB)")
    fi
    rel=$(LVM_DOMINIOS_LOCALES=$hosts docker_project_config "$folder" "$dir" "${url#https://}" \
        "$(docker_conf "$slug" BBDD)" "$(docker_conf "$slug" USUARIO)" "$(sed -n 's/^DB_PASS=//p' "$dir/.env")" \
        "$server") || return 1
    [ -n "$rel" ] || return 0
    # (si ya estaba, se cambia en su sitio: el contenedor la tiene montada y la ve al momento)
    if [ -f "$dir/config-${v//./}.php" ]; then
        cat "$dir/config.php" > "$dir/config-${v//./}.php" && rm -f "$dir/config.php"
    else
        mv -f "$dir/config.php" "$dir/config-${v//./}.php"
    fi
}

# compose.yaml de un proyecto: un servicio por version de PHP (php83...), con la imagen nexum-php de esa
# version, PHP-FPM en el puerto 9000 de la red interna (fpm.conf), la carpeta en la misma ruta que ve
# el Apache de Docker, su configuracion de solo lectura encima de la del proyecto y, en PrestaShop 1.7
# o posterior, su cache en un volumen propio de cada version
function docker_web_compose() {
    local slug=$1 dir=$DOCKER_DIR/$1 folder rel v vv vols=""
    folder=$(docker_conf "$slug" CARPETA) rel=$(docker_conf "$slug" CONFIG)
    { printf 'name: nexum-%s\nservices:\n' "$slug"
      for v in $(docker_conf "$slug" PHP); do
          vv=${v//./}
          printf '  php%s:\n    image: nexum-php:%s\n    container_name: %s\n    restart: "no"\n' "$vv" "$v" "$(docker_web_container "$slug" "$v")"
          printf '    command: ["php-fpm", "-R", "-F"]\n    volumes:\n'
          printf '      - "%s:/opt/lampp/htdocs/%s"\n' "$HTDOCS_DIR/$folder" "$folder"
          printf '      - "./fpm.conf:/usr/local/etc/php-fpm.d/zz-nexum.conf:ro"\n'
          [ -n "$rel" ] && [ -f "$dir/config-$vv.php" ] && printf '      - "./config-%s.php:/opt/lampp/htdocs/%s/%s:ro"\n' "$vv" "$folder" "$rel"
          if [ "$rel" == app/config/parameters.php ]; then
              printf '      - "cache-%s:/opt/lampp/htdocs/%s/var/cache"\n' "$vv" "$folder"
              vols+="  cache-$vv: {}"$'\n'
          fi
          printf '    networks: [nexum]\n'
      done
      [ -n "$vols" ] && printf 'volumes:\n%s' "$vols"
      printf 'networks:\n  nexum:\n    external: true\n    name: nexum\n'; } > "$dir/compose.yaml.nuevo" \
        && mv -f "$dir/compose.yaml.nuevo" "$dir/compose.yaml"
}

# Pool de PHP-FPM de los contenedores (fpm.conf): los procesos se abren al llegar peticiones (ondemand)
# y se cierran a los 20 s sin trabajo. Un proyecto en marcha sin usar gasta solo su proceso principal (unos
# MB), no dos o tres procesos esperando (100-200 MB, lo de fabrica de la imagen). Al arrancar se rehace
function docker_fpm_conf() {
    printf '[global]\nerror_log = /proc/self/fd/2\ndaemonize = no\n[www]\nuser = root\ngroup = root\nlisten = 9000\nclear_env = no\ncatch_workers_output = yes\npm = ondemand\npm.max_children = 10\npm.process_idle_timeout = 20s\npm.max_requests = 50\n'
}

# El fpm.conf del proyecto, al dia (los de antes de la 1.56.7, sin ondemand). Devuelve 0 si ha cambiado:
# sus contenedores se rehacen al arrancar (lo leen al empezar)
function docker_fpm_refresh() {
    local f=$DOCKER_DIR/$1/fpm.conf
    docker_fpm_conf | cmp -s - "$f" && return 1
    ( umask 077; docker_fpm_conf > "$f" )
}

# Servicios que van en marcha: todas las versiones o, en una tienda, la elegida
function docker_web_services() {
    local v
    if [ "$(docker_conf "$1" TIPO)" == ps ]; then
        v=$(docker_conf "$1" ACTIVA)
        echo "php${v//./}"
    else
        for v in $(docker_conf "$1" PHP); do echo "php${v//./}"; done
    fi
}

# Cambia una clave de proyecto.conf
function docker_conf_set() {
    local f=$DOCKER_DIR/$1/proyecto.conf
    [ -f "$f" ] && [ ! -L "$f" ] || return 1
    awk -F= -v k="$2" -v v="$3" 'BEGIN { done = 0 } $1 == k { print k "=" v; done = 1; next } { print } END { if (!done) print k "=" v }' \
        "$f" > "$f.nuevo" && chmod 600 "$f.nuevo" && mv -f "$f.nuevo" "$f"
}

# Tienda PrestaShop en la MariaDB comun: su dominio pasa a ser el de Docker (la BBDD es una copia)
function docker_web_ps_domain() {
    local slug=$1 v db dom prefix
    v=$(docker_conf "$slug" MARIADB) db=$(docker_conf "$slug" BBDD)
    dom=$(docker_web_domain "$slug" "")
    [ "$(docker_web_get HTTPS)" == 443 ] || dom+=":$(docker_web_get HTTPS)"
    prefix=$(docker_maria_sql "$v" -N -e "SELECT LEFT(table_name, LENGTH(table_name) - 8) FROM information_schema.tables
        WHERE table_schema = '$db' AND table_name LIKE '%shop\\_url' AND table_type = 'BASE TABLE' LIMIT 1" < /dev/null 2> /dev/null | tr -d '\r')
    [[ "$prefix" =~ ^[A-Za-z0-9_]+$ ]] || return 0
    # (el de produccion, para traer de alli sus imagenes: ps-imagenes)
    local prod
    prod=$(docker_maria_sql "$v" -N -e "SELECT domain FROM \`$db\`.\`${prefix}shop_url\` ORDER BY main DESC, active DESC, id_shop_url LIMIT 1" \
        < /dev/null 2> /dev/null | tr -d '\r' | tr 'A-Z' 'a-z')
    prod=${prod%%:*}
    if valid_domain "$prod" && [[ "$prod" != *.docker.local && "$prod" != *.docker.test && "$prod" != *.local ]]; then
        docker_conf_set "$slug" PRODUCCION "$prod"
    fi
    echo "Tienda PrestaShop: su dominio pasa a $dom en la BBDD de Docker"
    docker_maria_sql "$v" "$db" << EOF
UPDATE \`${prefix}shop_url\` SET domain = '$dom', domain_ssl = '$dom';
UPDATE \`${prefix}configuration\` SET value = '$dom' WHERE name IN ('PS_SHOP_DOMAIN', 'PS_SHOP_DOMAIN_SSL');
UPDATE \`${prefix}configuration\` SET value = '1' WHERE name IN ('PS_SSL_ENABLED', 'PS_SSL_ENABLED_EVERYWHERE');
EOF
}

# docker-nuevo <carpeta> <php> <mariadb> [--bd <base> --desde <version LAMPP> | --volcado <fichero>]:
# proyecto en Docker con el Apache de Docker. Su BBDD (vacia, la de una version LAMPP o un volcado) va en
# la MariaDB comun de esa version, con su propio usuario. Mas versiones de PHP: docker-php-añadir
function docker_web_create() {
    local folder=${1%/} php=$2 maria=$3 db="" from="" dump="" slug dir tipo dbname user pass rel p live=0
    shift 3 2> /dev/null
    while [ $# -gt 0 ]; do
        case $1 in
            --en-vivo) live=1; shift ;;
            --bd|--desde|--volcado)
                [ -n "$2" ] || { echo "Falta el valor de $1"; return 1; }
                case $1 in --bd) db=$2 ;; --desde) from=$2 ;; --volcado) dump=$2 ;; esac
                shift 2 ;;
            *) echo "Opcion desconocida: $1"; return 1 ;;
        esac
    done
    if [ -z "$folder" ] || [ -z "$php" ] || [ -z "$maria" ]; then
        echo "Uso: nexum docker-nuevo <carpeta> <php> <mariadb> [--bd <base> --desde <version> | --volcado <fichero>]"
        return 1
    fi
    valid_project "$folder" || return 1
    [[ " $DOCKER_PHP_VERSIONS " == *" $php "* ]] || { echo "PHP $php no se ofrece en Docker ($DOCKER_PHP_VERSIONS)"; return 1; }
    [[ " $DOCKER_MARIADB_VERSIONS " == *" $maria "* ]] || { echo "MariaDB $maria no se ofrece en Docker ($DOCKER_MARIADB_VERSIONS)"; return 1; }
    if [ -n "$db" ]; then
        db_valid_name "$db" || return 1
    fi
    if [ -n "$from" ]; then
        [ -n "$db" ] && valid_version_name "$from" && [ -d "${TEST_DIR:-/opt}/lampp-$from" ] \
            || { echo "Con --desde hay que decir la base (--bd) y una version LAMPP que exista"; return 1; }
    elif [ -n "$db" ] && [ -z "$dump" ]; then
        echo "Con --bd hay que decir de que version LAMPP se copia (--desde)"
        return 1
    fi
    if [ -n "$dump" ] && { [ ! -f "$dump" ] || [ -L "$dump" ] || [ -n "$from" ]; }; then
        echo "El volcado tiene que ser un fichero (y sin --desde): $dump"
        return 1
    fi
    slug=$(docker_slug "$folder") && docker_valid_slug "$slug" || { echo "No se puede sacar un nombre corto de $folder"; return 1; }
    # (los nombres de lo comun no: la carpeta del Apache de Docker, las de las MariaDB y las del gestor)
    case $slug in web|bin|imagenes|mariadb-*) slug=$(cut -c1-31 <<< "$slug" | sed 's/-*$//')-proyecto ;; esac
    for p in $(docker_web_projects); do
        if [ "$(docker_conf "$p" CARPETA)" == "$folder" ]; then
            echo "$folder ya esta en Docker ($p): para otra version de PHP, nexum docker-php-añadir $p $php"
            return 1
        fi
    done
    dir=$DOCKER_DIR/$slug
    if [ -e "$dir" ]; then
        echo "Ya hay un proyecto en Docker con el nombre $slug (de antes, con LAMPP delante): pasalo con nexum docker-pasar $slug"
        return 1
    fi
    # shellcheck disable=SC2209  # (tipo=otro es un texto, no una orden)
    if is_prestashop "$folder"; then tipo=ps; elif is_wordpress "$folder"; then tipo=wp; else tipo=otro; fi
    if [ $live -eq 1 ]; then
        [ "$tipo" == wp ] && [ -n "$from" ] || { echo "--en-vivo: solo con un WordPress y su BBDD de una version LAMPP (--bd y --desde)"; return 1; }
    fi
    dbname=${db:-$(tr '-' '_' <<< "$slug")}
    user=$(cut -c1-32 <<< "nx_$dbname")
    echo "Proyecto en Docker: $folder con PHP $php y MariaDB $maria comun (BBDD $dbname)"
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] $dir con la imagen nexum-php:$php, la BBDD $dbname en $(docker_maria_name "$maria") y $(docker_web_url "$( [ $tipo == ps ] && echo "$slug" || echo "$slug-php${php//./}").docker.local")"
        [ -n "$db" ] && echo "  [simulacion] copia de $db ${from:+de lampp-$from}${dump:+de $dump}"
        return 0
    fi
    docker_ready || { echo "Docker sin root no esta en marcha: instalalo o arrancalo en la pestaña Docker."; return 1; }
    if ! docker_web_ports_ok; then
        echo "Docker sin root aun no puede usar los puertos $(docker_web_get HTTP) y $(docker_web_get HTTPS): pulsa «Permitir» en"
        echo "Configuracion, Docker (o: nexum docker-web permitir), o elige otros puertos."
        return 1
    fi
    # La contraseña antes de cambiar nada (hosts): cancelarla deja todo como estaba. Con el DNS comodin no
    # se toca /etc/hosts: no hace falta
    docker_dns_on || sudo_first || return 1
    if [ $live -eq 1 ]; then
        docker_web_create_live "$folder" "$php" "$maria" "$from" "$slug" "$dir"
        return
    fi
    task_plan "Montando $folder en Docker" "MariaDB $maria común" "Imagen de PHP $php" "BBDD $dbname" "Apache de Docker" "Certificado en el navegador"
    task_step
    echo "1/5 MariaDB $maria comun"
    docker_maria_up "$maria" || return 1
    if [ "$(docker_maria_sql "$maria" -N -e "SELECT COUNT(*) FROM information_schema.SCHEMATA WHERE SCHEMA_NAME = '$dbname'" < /dev/null 2> /dev/null | tr -d '\r')" != 0 ]; then
        echo "Ya hay una BBDD $dbname en la MariaDB $maria de Docker (de otro proyecto): elige otra o borra aquel proyecto"
        return 1
    fi
    mkdir -p -m 700 "$DOCKER_DIR" "$dir" || return 1
    pass=$(head -c 18 /dev/urandom | base64 | tr -d '/+=\n')
    for rel in wp-config.php app/config/parameters.php config/settings.inc.php; do
        [ -f "$HTDOCS_DIR/$folder/$rel" ] && [ ! -L "$HTDOCS_DIR/$folder/$rel" ] && break
        rel=""
    done
    ( umask 077
      printf 'DB_PASS=%s\n' "$pass" > "$dir/.env"
      printf 'MODO=web\nCARPETA=%s\nTIPO=%s\nPHP=%s\nACTIVA=%s\nMARIADB=%s\nBBDD=%s\nUSUARIO=%s\nCONFIG=%s\n' \
          "$folder" "$tipo" "$php" "$php" "$maria" "$dbname" "$user" "$rel" > "$dir/proyecto.conf"
      docker_fpm_conf > "$dir/fpm.conf" ) || return 1
    # (el dominio: el de la tienda o el de la version)
    docker_conf_set "$slug" DOMINIO "$(docker_web_domain "$slug" "$php")"
    docker_web_config "$slug" "$php" && docker_web_compose "$slug" || return 1
    task_step
    echo "2/5 Imagen de PHP $php"
    docker_php_image "$php" || { echo "No se ha podido preparar la imagen de PHP $php"; return 1; }
    task_step
    echo "3/5 BBDD $dbname"
    docker_maria_sql "$maria" << EOF || return 1
CREATE DATABASE \`$dbname\` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE USER IF NOT EXISTS '$user'@'%' IDENTIFIED BY '$pass';
ALTER USER '$user'@'%' IDENTIFIED BY '$pass';
GRANT ALL PRIVILEGES ON \`$dbname\`.* TO '$user'@'%';
EOF
    if [ -n "$from" ] || [ -n "$dump" ]; then
        local tmp=$dump
        if [ -n "$from" ]; then
            mkdir -p -m 700 "$LOG_DIR" || return 1
            tmp=$(mktemp "$LOG_DIR/docker-$slug-XXXXXX") && mv -f "$tmp" "$tmp.sql.gz" && tmp=$tmp.sql.gz || return 1
            echo "Copiando $db de lampp-$from..."
            export_database "$db" "$tmp" "$from" || { rm -f "$tmp"; tmp=""; echo "No se ha podido descargar $db de lampp-$from: la BBDD queda vacia."; }
            db_temp_stop
        fi
        if [ -n "$tmp" ]; then
            { if [[ "$tmp" == *.gz ]]; then gzip -dc "$tmp"; else cat "$tmp"; fi; } \
                | docker_maria_sql "$maria" --binary-mode "$dbname" \
                || echo "Aviso: la carga de la BBDD ha dado errores (mira el registro)."
            [ -n "$from" ] && rm -f "$tmp"
            [ $tipo == ps ] && docker_web_ps_domain "$slug"
            local admin
            admin=$(docker_test_admin "$slug")
            grep -v '^A|' <<< "$admin" | grep .
            grep -q '^A|' <<< "$admin" && echo "Administrador de pruebas del panel: $TEST_ADMIN_USER, contraseña $TEST_ADMIN_PASS"
        fi
    fi
    task_step
    echo "4/5 Apache de Docker y $(docker_web_domain "$slug" "$php")"
    docker_web_hosts poner "$(docker_web_pma)" "$(docker_web_domain "$slug" "$php")" || return 1
    docker_web_up || return 1
    dk compose --project-directory "$dir" -f "$dir/compose.yaml" up -d "php${php//./}" || return 1
    task_step
    echo "5/5 Certificado en el navegador"
    docker_web_trust
    echo "Proyecto en Docker listo: $(docker_web_url "$(docker_web_domain "$slug" "$php")") (PHP $php). phpMyAdmin: $(docker_web_url "$(docker_web_pma)")"
}

# docker-nuevo ... --en-vivo: el proyecto sin BBDD en Docker, con la de esa version LAMPP en vivo (con el
# usuario y la contraseña de su wp-config.php)
function docker_web_create_live() {
    local folder=$1 php=$2 maria=$3 from=$4 slug=$5 dir=$6 creds owner
    creds=$(lampp_bd_creds "$folder") || { echo "No se puede leer el usuario y la base del wp-config.php de $folder"; return 1; }
    owner=$(lampp_bd_owner "$from")
    mkdir -p -m 700 "$DOCKER_DIR" "$dir" || return 1
    ( umask 077
      printf 'DB_PASS=%s\n' "$(sed -n 2p <<< "$creds")" > "$dir/.env"
      printf 'MODO=web\nCARPETA=%s\nTIPO=wp\nPHP=%s\nACTIVA=%s\nMARIADB=%s\nBBDD=%s\nUSUARIO=%s\nCONFIG=wp-config.php\nLAMPP_BD=%s\n' \
          "$folder" "$php" "$php" "$maria" "$(head -1 <<< "$creds" | cut -d'|' -f2)" "${creds%%|*}" "$owner" > "$dir/proyecto.conf"
      docker_fpm_conf > "$dir/fpm.conf" ) || return 1
    docker_conf_set "$slug" DOMINIO "$(docker_web_domain "$slug" "$php")"
    docker_web_config "$slug" "$php" && docker_web_compose "$slug" || return 1
    task_plan "Montando $folder en Docker" "Imagen de PHP $php" "BBDD en vivo" "Apache de Docker" "Certificado en el navegador"
    task_step
    echo "1/4 Imagen de PHP $php"
    docker_php_image "$php" || { echo "No se ha podido preparar la imagen de PHP $php"; return 1; }
    task_step
    echo "2/4 BBDD $(docker_conf "$slug" BBDD) de lampp-$owner, en vivo (la misma que web.local)"
    lampp_bd_up "$owner" && lampp_bd_bridge_up "$owner" || return 1
    task_step
    echo "3/4 Apache de Docker y $(docker_web_domain "$slug" "$php")"
    docker_web_hosts poner "$(docker_web_pma)" "$(docker_web_domain "$slug" "$php")" || return 1
    docker_web_up || return 1
    dk compose --project-directory "$dir" -f "$dir/compose.yaml" up -d "php${php//./}" || return 1
    task_step
    echo "4/4 Certificado en el navegador"
    docker_web_trust
    echo "Proyecto en Docker listo: $(docker_web_url "$(docker_web_domain "$slug" "$php")") (PHP $php), con la BBDD de lampp-$owner en vivo"
}

# docker-php-añadir <nombre> <php>: otra version de PHP del mismo proyecto, con la misma carpeta y la
# misma BBDD. En WordPress va a la vez que las demas, con su dominio; en una tienda pasa a ser la elegida
function docker_web_add() {
    local slug=$1 php=$2 dir list
    docker_web_project "$slug" || { echo "No hay ningun proyecto en Docker (con el Apache de Docker) con el nombre $slug"; return 1; }
    [[ " $DOCKER_PHP_VERSIONS " == *" $php "* ]] || { echo "PHP $php no se ofrece en Docker ($DOCKER_PHP_VERSIONS)"; return 1; }
    dir=$DOCKER_DIR/$slug
    list=$(docker_conf "$slug" PHP)
    [[ " $list " == *" $php "* ]] && { echo "$slug ya tiene PHP $php"; return 0; }
    echo "$slug: añade PHP $php (la misma carpeta y la misma BBDD)"
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] contenedor $(docker_web_container "$slug" "$php") y $(docker_web_url "$(docker_web_domain "$slug" "$php")")"
        return 0
    fi
    docker_ready || { echo "Docker sin root no esta en marcha"; return 1; }
    docker_dns_on || sudo_first || return 1
    docker_php_image "$php" || { echo "No se ha podido preparar la imagen de PHP $php"; return 1; }
    docker_conf_set "$slug" PHP "$(tr ' ' '\n' <<< "$list $php" | sort -t. -k1,1nr -k2,2nr | tr '\n' ' ' | sed 's/ $//')" || return 1
    docker_web_config "$slug" "$php" && docker_web_compose "$slug" || return 1
    if [ "$(docker_conf "$slug" TIPO)" == ps ]; then
        docker_web_switch "$slug" "$php"
        return
    fi
    docker_web_hosts poner "$(docker_web_domain "$slug" "$php")" || return 1
    docker_maria_up "$(docker_conf "$slug" MARIADB)" && docker_web_up || return 1
    dk compose --project-directory "$dir" -f "$dir/compose.yaml" up -d "php${php//./}" || return 1
    echo "Listo: $(docker_web_url "$(docker_web_domain "$slug" "$php")") (PHP $php)"
}

# docker-php-quitar <nombre> <php>: quita una version de PHP de un proyecto (su contenedor, su
# configuracion y su dominio). La ultima no: para eso, borrar el proyecto de Docker
function docker_web_remove() {
    local slug=$1 php=$2 dir list rest dom
    docker_web_project "$slug" || { echo "No hay ningun proyecto en Docker (con el Apache de Docker) con el nombre $slug"; return 1; }
    dir=$DOCKER_DIR/$slug
    list=$(docker_conf "$slug" PHP)
    [[ " $list " == *" $php "* ]] || { echo "$slug no tiene PHP $php"; return 1; }
    rest=$(tr ' ' '\n' <<< "$list" | grep -vxF "$php" | tr '\n' ' ' | sed 's/ $//')
    [ -n "$rest" ] || { echo "PHP $php es la unica version de $slug: para quitarla, borra el proyecto de Docker"; return 1; }
    dom=$(docker_web_domain "$slug" "$php")
    echo "$slug: se quita PHP $php (la carpeta y la BBDD se quedan)"
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] fuera el contenedor $(docker_web_container "$slug" "$php")"
        return 0
    fi
    docker_dns_on || sudo_first || return 1
    if [ "$(docker_conf "$slug" TIPO)" == ps ] && [ "$(docker_conf "$slug" ACTIVA)" == "$php" ]; then
        docker_web_switch "$slug" "${rest%% *}" || return 1
    fi
    dk compose --project-directory "$dir" -f "$dir/compose.yaml" rm -sf "php${php//./}" > /dev/null 2>&1
    dk volume rm "nexum-${slug}_cache-${php//./}" > /dev/null 2>&1
    rm -f "$dir/config-${php//./}.php"
    docker_conf_set "$slug" PHP "$rest" && docker_web_compose "$slug" || return 1
    # (la que se enseña como suya, si era esa: la siguiente)
    if [ "$(docker_conf "$slug" ACTIVA)" == "$php" ]; then
        docker_conf_set "$slug" ACTIVA "${rest%% *}" && docker_conf_set "$slug" DOMINIO "$(docker_web_domain "$slug" "${rest%% *}")"
    fi
    [ "$(docker_conf "$slug" TIPO)" == ps ] || docker_web_hosts quitar "$dom"
    docker_web_reload
    echo "Listo: $slug sigue con PHP $rest"
}

# docker-php-elegir <nombre> <php>: la version de PHP con la que va una tienda PrestaShop (va con un
# solo dominio): se arranca esa, el dominio pasa a ella y se para la de antes
function docker_web_switch() {
    local slug=$1 php=$2 dir old
    docker_web_project "$slug" || { echo "No hay ningun proyecto en Docker (con el Apache de Docker) con el nombre $slug"; return 1; }
    [[ " $(docker_conf "$slug" PHP) " == *" $php "* ]] || { echo "$slug no tiene PHP $php: añadela antes (docker-php-añadir)"; return 1; }
    dir=$DOCKER_DIR/$slug
    old=$(docker_conf "$slug" ACTIVA)
    echo "$slug: $(docker_web_domain "$slug" "$php") pasa a PHP $php"
    [ "$DRY" -eq 1 ] && return 0
    docker_ready || { echo "Docker sin root no esta en marcha"; return 1; }
    docker_conf_set "$slug" ACTIVA "$php" || return 1
    docker_web_hosts poner "$(docker_web_domain "$slug" "$php")" || return 1
    docker_maria_up "$(docker_conf "$slug" MARIADB)" || return 1
    local fresh=()
    docker_fpm_refresh "$slug" && fresh=(--force-recreate)
    if ! dk compose --project-directory "$dir" -f "$dir/compose.yaml" up -d "${fresh[@]}" "php${php//./}"; then
        echo "No arranca con PHP $php: sigue con PHP $old"
        docker_conf_set "$slug" ACTIVA "$old"
        return 1
    fi
    docker_web_up || return 1
    if [ -n "$old" ] && [ "$old" != "$php" ]; then
        dk compose --project-directory "$dir" -f "$dir/compose.yaml" rm -sf "php${old//./}" > /dev/null 2>&1
    fi
    echo "Listo: $(docker_web_url "$(docker_web_domain "$slug" "$php")") con PHP $php"
}

# Acciones de un proyecto del sistema nuevo (las de docker_action): arrancar (con su MariaDB y el Apache
# de Docker), parar (sus PHP: lo comun se queda), registros y borrar (sus contenedores, su BBDD y su
# usuario de la MariaDB comun, sus dominios de hosts y su carpeta del gestor; la del proyecto, no)
function docker_web_action() {
    local action=$1 slug=$2 dir=$DOCKER_DIR/$2 maria
    local c=(dk compose --project-directory "$dir" -f "$dir/compose.yaml")
    maria=$(docker_conf "$slug" MARIADB)
    case $action in
        arrancar)
            [ "$DRY" -eq 1 ] && { echo "  [simulacion] MariaDB $maria, Apache de Docker y $(docker_web_services "$slug" | tr '\n' ' ')"; return 0; }
            docker_idle_ensure
            # (su configuracion, al dia: la de su wp-config.php y las direcciones de la web en local)
            if [ -n "$(docker_conf "$slug" CONFIG)" ]; then
                local v
                for v in $(docker_conf "$slug" PHP); do docker_web_config "$slug" "$v" > /dev/null || return 1; done
            fi
            if [ -n "$(docker_conf "$slug" LAMPP_BD)" ]; then
                lampp_bd_up "$(docker_conf "$slug" LAMPP_BD)" && lampp_bd_bridge_up "$(docker_conf "$slug" LAMPP_BD)" || return 1
                docker_web_up || return 1
            else
                docker_maria_up "$maria" && docker_web_up || return 1
            fi
            local fresh=()
            docker_fpm_refresh "$slug" && fresh=(--force-recreate)
            run "${c[@]}" up -d "${fresh[@]}" $(docker_web_services "$slug") ;;
        parar) run "${c[@]}" stop && docker_web_idle_stop && lampp_bd_release "$(docker_conf "$slug" LAMPP_BD)" "$slug" ;;
        registros) "${c[@]}" logs --no-color --tail 200 ;;
        borrar)
            local db user domains
            db=$(docker_conf "$slug" BBDD) user=$(docker_conf "$slug" USUARIO)
            mapfile -t domains < <(docker_web_domains "$slug")
            # (con la BBDD de LAMPP en vivo, la que se borra es su copia de Docker, si tiene: la de LAMPP nunca)
            if [ -n "$(docker_conf "$slug" LAMPP_BD)" ]; then
                db=$(docker_conf "$slug" BBDD_DOCKER) user=$(docker_conf "$slug" USUARIO_DOCKER)
            fi
            echo "Se borran los contenedores de $slug${db:+ y su BBDD $db de la MariaDB $maria de Docker} (la de LAMPP no se toca)"
            [ "$DRY" -eq 1 ] && return 0
            run "${c[@]}" down -v || return 1
            lampp_bd_release "$(docker_conf "$slug" LAMPP_BD)" "$slug"
            if db_valid_name "$db" > /dev/null && [[ "$user" =~ ^[A-Za-z0-9_]{1,32}$ ]] && docker_maria_up "$maria" > /dev/null; then
                printf 'DROP DATABASE IF EXISTS `%s`;\nDROP USER IF EXISTS '"'"'%s'"'"'@'"'"'%%'"'"';\n' "$db" "$user" | docker_maria_sql "$maria"
            fi
            docker_web_hosts quitar "${domains[@]}"
            rm -rf "$dir"
            docker_web_reload
            echo "Proyecto en Docker $slug borrado" ;;
    esac
}

# Lo comun que ya no usa nadie, parado: una MariaDB comun sin ningun PHP en marcha de los proyectos
# que van con ella y, sin ningun PHP del Apache de Docker en marcha, el Apache de Docker y su phpMyAdmin.
# (Nada de Nexum arranca solo: restart "no". Lo comun se queda al parar un proyecto por si lo usa otro)
function docker_web_idle_stop() {
    local up p v name used=() web_used=0
    [ "$DRY" -eq 1 ] && return 0
    up=$(dk ps --format '{{.Names}}' 2> /dev/null) || return 0
    for p in $(docker_web_projects); do
        if grep -qE "^nexum-$p-php[0-9]{2}\$" <<< "$up"; then
            web_used=1
            # (los que van en vivo con la BBDD de LAMPP no usan la MariaDB comun)
            [ -z "$(docker_conf "$p" LAMPP_BD)" ] && used+=("$(docker_conf "$p" MARIADB)")
        fi
    done
    for name in $(grep -E '^nexum-mariadb-[0-9]{1,2}-[0-9]{1,2}$' <<< "$up"); do
        v=${name#nexum-mariadb-} v=${v/-/.}
        if ! printf '%s\n' "${used[@]}" | grep -qxF "$v"; then
            echo "MariaDB $v de Docker: ya no la usa ningun proyecto en marcha, se para"
            run dk stop "$name" > /dev/null
        fi
    done
    if [ "$web_used" -eq 0 ] && grep -qxE 'nexum-(web|pma)' <<< "$up"; then
        echo "Apache de Docker: ya no hay ningun proyecto en marcha con el, se para (y su phpMyAdmin)"
        run dk stop $(grep -xE 'nexum-(web|pma)' <<< "$up") > /dev/null
    fi
    return 0
}

# ===========================================================================
# Proyectos de Docker sin visitas: se paran solos
# ===========================================================================
# Un proyecto del Apache de Docker en marcha que lleva DOCKER_IDLE_FILE horas sin ninguna visita (en el
# registro de nexum-web, que apunta el dominio de cada una: tambien las que llegan por el tunel) se para,
# y con el lo comun que ya no use nadie (su MariaDB, el Apache de Docker). Solo si el y nexum-web llevan
# en marcha al menos esas horas (si no, su registro no alcanza). Con 0, nunca. Por defecto, 3 horas
DOCKER_IDLE_FILE=$DOCKER_DIR/reposo
DOCKER_STOPPED_MSG="Este proyecto de Docker está parado (se para solo tras unas horas sin visitas). Arráncalo en Nexum Dev Stack, pestaña Docker."
DOCKER_IDLE_LOG=$LOG_DIR/docker-reposo.log
function docker_idle_hours() {
    local v
    v=$(head -c 10 "$DOCKER_IDLE_FILE" 2> /dev/null | tr -d ' \n')
    [ -f "$DOCKER_IDLE_FILE" ] || v=3
    [[ "$v" =~ ^([0-9]|1[0-9]|2[0-4])$ ]] || v=3
    echo "$v"
}

# El temporizador: uno de systemctl --user (sin root, como Docker sin root) que cada 15 minutos lanza
# docker-reposo comprobar, aunque la ventana este cerrada
DOCKER_IDLE_UNIT_DIR=${LVM_REPOSO_UNITS:-$HOME/.config/systemd/user}
function docker_idle_timer_on() {
    systemctl --user is-active --quiet nexum-reposo.timer 2> /dev/null || return 1
    # Uno puesto cuando la orden era lvm-instalador (ExecStart=/usr/local/bin/lvm-instalador o el script
    # de /opt/lvm-instalador, que ya no existen): se rehace con nexum, y asi sigue funcionando
    if grep -q '^ExecStart=\(.*/lvm-instalador\|/opt/lvm-instalador/lvm-instalador\.sh\) docker-reposo ' \
            "$DOCKER_IDLE_UNIT_DIR/nexum-reposo.service" 2> /dev/null; then
        docker_idle_timer poner > /dev/null 2>&1
    fi
    return 0
}
function docker_idle_timer() {
    local bin
    if [ "$1" == poner ]; then
        # (la orden nexum instalada; si no, este mismo)
        bin=$(command -v nexum 2> /dev/null)
        [ -n "$bin" ] || bin=$SELF
        mkdir -p "$DOCKER_IDLE_UNIT_DIR" || return 1
        printf '[Unit]\nDescription=Nexum Dev Stack: parar los proyectos de Docker sin visitas\n\n[Service]\nType=oneshot\nExecStart=%s docker-reposo comprobar\n' \
            "$bin" > "$DOCKER_IDLE_UNIT_DIR/nexum-reposo.service" || return 1
        printf '[Unit]\nDescription=Nexum Dev Stack: cada 15 minutos, los proyectos de Docker sin visitas\n\n[Timer]\nOnBootSec=10min\nOnUnitActiveSec=15min\n\n[Install]\nWantedBy=timers.target\n' \
            > "$DOCKER_IDLE_UNIT_DIR/nexum-reposo.timer" || return 1
        systemctl --user daemon-reload && systemctl --user enable --now nexum-reposo.timer > /dev/null 2>&1
    else
        systemctl --user disable --now nexum-reposo.timer > /dev/null 2>&1
        rm -f "$DOCKER_IDLE_UNIT_DIR/nexum-reposo.service" "$DOCKER_IDLE_UNIT_DIR/nexum-reposo.timer"
        systemctl --user daemon-reload > /dev/null 2>&1
    fi
}

# Segundos (de 1970) de cuando arranco un contenedor (nada si no esta)
function docker_started_at() {
    dk inspect -f '{{.State.StartedAt}}' "$1" 2> /dev/null | python3 -I -c '
import datetime, re, sys
t = sys.stdin.read().strip()
m = re.match(r"(\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d)", t)
if m:
    print(int(datetime.datetime.strptime(m.group(1), "%Y-%m-%dT%H:%M:%S").replace(tzinfo=datetime.timezone.utc).timestamp()))'
}

# docker-reposo comprobar: para los que llevan las horas sin visitas (lo lanza el temporizador)
function docker_idle_check() {
    local h now cutoff up visited p name t newest stopped=0 dom seen
    h=$(docker_idle_hours)
    [ "$h" -gt 0 ] || return 0
    docker_ready > /dev/null 2>&1 || return 0
    up=$(dk ps --format '{{.Names}}' 2> /dev/null)
    grep -qx nexum-web <<< "$up" || return 0
    now=$(date +%s) cutoff=$(( $(date +%s) - h * 3600 ))
    t=$(docker_started_at nexum-web)
    [ -n "$t" ] && [ "$t" -le "$cutoff" ] || return 0
    # (los dominios visitados en esas horas: el primero de cada linea del registro de nexum-web)
    visited=$(dk logs --since "${h}h" nexum-web 2> /dev/null | awk '{ print tolower($1) }' | sort -u)
    for p in $(docker_web_projects); do
        newest=""
        for name in $(grep -E "^nexum-$p-php[0-9]{2}\$" <<< "$up"); do
            t=$(docker_started_at "$name")
            [ -n "$t" ] && { [ -z "$newest" ] || [ "$t" -gt "$newest" ]; } && newest=$t
        done
        [ -n "$newest" ] && [ "$newest" -le "$cutoff" ] || continue
        seen=0
        for dom in $(docker_web_domains "$p"); do
            grep -qxF "${dom,,}" <<< "$visited" && { seen=1; break; }
        done
        [ $seen -eq 1 ] && continue
        if [ "$DRY" -eq 1 ]; then
            echo "  [simulacion] $p: $h h sin visitas, se pararia"
            stopped=$((stopped + 1))
            continue
        fi
        echo "$(date '+%Y-%m-%d %H:%M') $p: $h h sin visitas, se para" | tee -a "$DOCKER_IDLE_LOG"
        docker_web_action parar "$p" > /dev/null 2>&1 && stopped=$((stopped + 1))
    done
    # (el registro, con lo ultimo)
    [ -f "$DOCKER_IDLE_LOG" ] && [ "$(wc -l < "$DOCKER_IDLE_LOG")" -gt 500 ] \
        && tail -n 200 "$DOCKER_IDLE_LOG" > "$DOCKER_IDLE_LOG.nuevo" && mv -f "$DOCKER_IDLE_LOG.nuevo" "$DOCKER_IDLE_LOG"
    [ $stopped -gt 0 ] || [ "${1:-}" != --decir ] || echo "Ningún proyecto lleva $h h sin visitas"
    return 0
}

# Que el temporizador este si hace falta (al arrancar un proyecto de Docker): con horas y sin el, se pone
function docker_idle_ensure() {
    [ "$DRY" -eq 1 ] && return 0
    if [ "$(docker_idle_hours)" -gt 0 ]; then
        docker_idle_timer_on || docker_idle_timer poner > /dev/null 2>&1
    fi
    return 0
}

# docker-reposo [estado] | horas <0-24> | comprobar
#   estado: Q|horas (0: nunca)|temporizador puesto (1/0)|lo ultimo que se ha parado
function docker_idle_command() {
    case ${1:-estado} in
        estado) echo "Q|$(docker_idle_hours)|$(docker_idle_timer_on && echo 1 || echo 0)|$(tail -n 1 "$DOCKER_IDLE_LOG" 2> /dev/null | tr '|' ' ')" ;;
        horas)
            [[ "$2" =~ ^([0-9]|1[0-9]|2[0-4])$ ]] || { echo "Las horas van de 0 (nunca) a 24"; return 1; }
            [ "$DRY" -eq 1 ] && { echo "  [simulacion] proyectos de Docker parados tras $2 h sin visitas"; return 0; }
            mkdir -p -m 700 "$DOCKER_DIR" && ( umask 077; echo "$2" > "$DOCKER_IDLE_FILE" ) || return 1
            if [ "$2" -gt 0 ]; then
                docker_idle_timer poner || { echo "No se ha podido poner el temporizador"; return 1; }
                echo "Los proyectos de Docker sin visitas se paran solos a las $2 h"
            else
                docker_idle_timer quitar
                echo "Los proyectos de Docker ya no se paran solos"
            fi ;;
        comprobar) docker_idle_check "$2" ;;
        *) echo "Uso: nexum docker-reposo [estado] | horas <0-24> | comprobar"; return 1 ;;
    esac
}

# ===========================================================================
# BBDD de LAMPP en Docker (en vivo)
# ===========================================================================
# Un WordPress de Docker puede usar la BBDD de una version LAMPP en vivo: la misma que web.local, sin
# copias. Su MariaDB (si no esta en marcha, solo ella y sin red: no choca con la de la version activa
# en el 3306) y, en la red de Docker, un puente hasta su socket (socat, de la imagen de MariaDB; ella ve
# las conexiones como de localhost, como las de web.local). El proyecto entra con el usuario y la
# contraseña de su wp-config.php, los mismos que con web.local. PrestaShop no: guarda su dominio en la
# BBDD y una misma BBDD no puede servir a web.local y a Docker a la vez
LAMPP_BD_BRIDGE_IMAGE=mariadb:11.8
LAMPP_BD_MARK_DIR=$DOCKER_DIR/lampp-bd

# La version que tiene de verdad las BBDD de otra (las que comparten datos)
function lampp_bd_owner() {
    local o
    o=$(data_owner "${TEST_DIR:-/opt}/lampp-$1")
    echo "${o:-$1}"
}

function lampp_bd_data() {
    echo "${TEST_DIR:-/opt}/lampp-$1/var/mysql"
}

function lampp_bd_bridge() {
    echo "nexum-lampp-bd-${1//./-}"
}

# ¿Responde la MariaDB de esa version en su socket?
function lampp_bd_alive() {
    db_socket_alive "$(lampp_bd_data "$1")/mysql.sock"
}

# La MariaDB de una version, en marcha: si no lo esta, se arranca solo ella, sin red (pide la contraseña)
# y se apunta en LAMPP_BD_MARK_DIR (asi no se cierra al arrancar otra version ni al parar LAMPP)
function lampp_bd_up() {
    local f=$1 dir data user server=() i
    dir=${TEST_DIR:-/opt}/lampp-$f data=$(lampp_bd_data "$f")
    lampp_bd_alive "$f" && return 0
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] MariaDB de lampp-$f, sin red (solo su socket), para Docker"
        return 0
    fi
    [ -d "$data" ] || { echo "lampp-$f no tiene BBDD ($data)"; return 1; }
    # (con el dueño de sus datos, nunca root, como db_temp_start)
    user=$($SUDO stat -L -c %U "$data") || return 1
    if [ "$user" == root ] || ! [[ "$user" =~ ^[a-z_][a-z0-9_-]*$ ]]; then
        echo "Las BBDD de lampp-$f son de $user: no se arranca su MariaDB con ese usuario"
        return 1
    fi
    if [ -x "$dir/mysql/bin/mariadbd" ]; then
        server=("$dir/mysql/bin/mariadbd" --defaults-file="$dir/etc/my.cnf")
    elif [ -x "$dir/sbin/mysqld" ]; then
        server=(env LD_LIBRARY_PATH="$dir/lib" "$dir/sbin/mysqld" --defaults-file="$dir/etc/my.cnf"
            --basedir="$dir" --plugin-dir="$dir/lib/mysql/plugin/"
            --innodb-data-home-dir="$data/" --innodb-log-group-home-dir="$data/")
    else
        echo "lampp-$f no tiene el servidor de MariaDB"
        return 1
    fi
    echo "Arrancando la MariaDB de lampp-$f para Docker (sin red: solo su socket)..."
    mkdir -p -m 700 "$LAMPP_BD_MARK_DIR" && : > "$LAMPP_BD_MARK_DIR/$f" || return 1
    # (aparte de esta tarea: sigue al terminar)
    $SUDO setsid -f "${server[@]}" --datadir="$data" --user="$user" --skip-networking \
        --socket="$data/mysql.sock" --pid-file="$data/mysqld.pid" --log-error="$data/mysqld.err" \
        < /dev/null > /dev/null 2>&1
    for i in $(seq 300); do
        lampp_bd_alive "$f" && return 0
        sleep 0.2
    done
    rm -f "$LAMPP_BD_MARK_DIR/$f"
    echo "La MariaDB de lampp-$f no ha arrancado (¿la tiene otro programa?). Lo ultimo de su registro:"
    $SUDO ${SUDO:+-u "$user"} tail -8 "$data/mysqld.err" 2> /dev/null | sed 's/^/  /'
    return 1
}

# El puente de la red de Docker hasta el socket de esa version (nexum-lampp-bd-8-4, en el 3306)
function lampp_bd_bridge_up() {
    local f=$1 name data
    name=$(lampp_bd_bridge "$f") data=$(lampp_bd_data "$f")
    [ "$DRY" -eq 1 ] && { echo "  [simulacion] puente $name hasta $data/mysql.sock"; return 0; }
    [ "$(dk inspect -f '{{.State.Running}}' "$name" 2> /dev/null)" == true ] && return 0
    dk rm -f "$name" > /dev/null 2>&1
    docker_net || return 1
    dk run -d --name "$name" --network nexum --restart no --label "nexum.lampp-bd=$f" \
        -v "$(readlink -f "$data"):/run/nexum-bd:ro" --entrypoint socat "$LAMPP_BD_BRIDGE_IMAGE" \
        TCP-LISTEN:3306,fork,reuseaddr UNIX-CONNECT:/run/nexum-bd/mysql.sock > /dev/null
}

# Proyectos de Docker en marcha que usan la BBDD de esa version (menos el segundo argumento)
function lampp_bd_users() {
    local f=$1 skip=$2 p up
    up=$(dk ps --format '{{.Names}}' 2> /dev/null)
    for p in $(docker_web_projects); do
        [ "$p" != "$skip" ] && [ "$(docker_conf "$p" LAMPP_BD)" == "$f" ] && grep -qE "^nexum-$p-php[0-9]{2}\$" <<< "$up" && echo "$p"
    done
}

# Cuando ya no la usa ningun proyecto en marcha: fuera su puente y, si la arranco Docker, su MariaDB (sin
# contraseña de root: la para con el usuario del proyecto, que en LAMPP es root de MariaDB)
# lampp_bd_release <version> [proyecto que se para]
function lampp_bd_release() {
    local f=$1 slug=$2 dir data admin user pass
    [ -n "$f" ] || return 0
    [ -n "$(lampp_bd_users "$f" "$slug")" ] && return 0
    [ "$DRY" -eq 1 ] && { echo "  [simulacion] fuera el puente de lampp-$f (y su MariaDB, si la arranco Docker)"; return 0; }
    dk rm -f "$(lampp_bd_bridge "$f")" > /dev/null 2>&1
    [ -f "$LAMPP_BD_MARK_DIR/$f" ] || return 0
    # (la de la version activa con LAMPP en marcha no: es la suya)
    [ "$(active_dir)" == "${TEST_DIR:-/opt}/lampp-$f" ] && lampp_running && return 0
    dir=${TEST_DIR:-/opt}/lampp-$f data=$(lampp_bd_data "$f")
    admin=$dir/mysql/bin/mariadb-admin
    [ -x "$admin" ] || admin=$dir/bin/mysqladmin
    for p in ${slug:-} $(docker_web_projects); do
        [ "$(docker_conf "$p" LAMPP_BD)" == "$f" ] || continue
        user=$(docker_conf "$p" USUARIO) pass=$(sed -n 's/^DB_PASS=//p' "$DOCKER_DIR/$p/.env")
        if MYSQL_PWD=$pass LD_LIBRARY_PATH="$dir/lib" "$admin" --no-defaults -S "$data/mysql.sock" -u "$user" shutdown > /dev/null 2>&1; then
            rm -f "$LAMPP_BD_MARK_DIR/$f"
            echo "MariaDB de lampp-$f parada (ya no la usa ningun proyecto de Docker)"
            return 0
        fi
    done
    return 0
}

# Antes de arrancar LAMPP con esa version: si su MariaDB la tenia Docker (sin red), se para para que
# arranque la normal (con su puerto); los proyectos de Docker vuelven a entrar por el mismo socket
function lampp_bd_handover() {
    local f data pid
    f=${1##*/lampp-} data=$(lampp_bd_data "$f")
    [ -n "$f" ] && [ -f "$LAMPP_BD_MARK_DIR/$f" ] || return 0
    [ "$DRY" -eq 1 ] && { echo "  [simulacion] la MariaDB de lampp-$f que tenia Docker pasa a la de LAMPP"; return 0; }
    rm -f "$LAMPP_BD_MARK_DIR/$f"
    lampp_bd_alive "$f" || return 0
    # (solo si de verdad es ese servidor: el de su .pid, sin red y con su socket)
    pid=$(db_temp_pid "$data/mysqld.pid" "$data/mysql.sock") || return 0
    [[ "$($SUDO ps -ww -o args= -p "$pid" 2> /dev/null)" == *--skip-networking* ]] || return 0
    echo "La MariaDB de lampp-$f la tenia Docker: pasa a la de LAMPP"
    $SUDO kill "$pid" 2> /dev/null
    local i
    for i in $(seq 150); do lampp_bd_alive "$f" || break; sleep 0.2; done
    return 0
}

# Al parar LAMPP: si algun proyecto de Docker en marcha usaba la BBDD de esta version, vuelve su MariaDB
# (sin red, para Docker)
function lampp_bd_keep() {
    local f=${1##*/lampp-}
    [ -n "$f" ] && [ -n "$(lampp_bd_users "$f")" ] || return 0
    echo "Algun proyecto de Docker usa la BBDD de lampp-$f: su MariaDB sigue para el (sin red)"
    lampp_bd_up "$f"
}

# El usuario, la contraseña y la base del proyecto en LAMPP (los de su wp-config.php): usuario|base y la
# contraseña en la segunda linea
function lampp_bd_creds() {
    python3 -I - "$HTDOCS_DIR/$1/wp-config.php" << 'EOF'
import re, sys
try:
    text = open(sys.argv[1], encoding="utf-8", errors="replace").read(2000000)
except OSError:
    sys.exit(1)
def get(name):
    m = re.search(r"""(?m)^(?:(?!//|#)[^\n])*?\bdefine\(\s*['"]%s['"]\s*,\s*(?:'((?:[^'\\]|\\.)*)'|"((?:[^"\\]|\\.)*)")""" % name, text)
    return None if not m else re.sub(r"\\(.)", r"\1", m.group(1) if m.group(1) is not None else m.group(2))
user, db, pw = get("DB_USER"), get("DB_NAME"), get("DB_PASSWORD")
if not user or not db or pw is None or "\n" in pw or "|" in user + db:
    sys.exit(1)
print(user + "|" + db)
print(pw)
EOF
}

# docker-bd <nombre> lampp <version> | docker: la BBDD de un WordPress de Docker, en vivo la de esa
# version LAMPP (la misma que web.local) o su copia en la MariaDB comun de Docker (la de antes, que no
# se borra al pasar a LAMPP)
function docker_db_mode() {
    local slug=$1 mode=$2 v=$3 dir creds user db pass owner was
    docker_web_project "$slug" || { echo "No hay ningun proyecto en Docker (con el Apache de Docker) con el nombre $slug"; return 1; }
    dir=$DOCKER_DIR/$slug
    case $mode in
        lampp)
            [ "$(docker_conf "$slug" TIPO)" == wp ] || { echo "Solo WordPress: una tienda guarda su dominio en la BBDD y no puede servir a web.local y a Docker a la vez"; return 1; }
            valid_version_name "$v" && [ -d "${TEST_DIR:-/opt}/lampp-$v" ] || { echo "No existe la version lampp-$v"; return 1; }
            owner=$(lampp_bd_owner "$v")
            creds=$(lampp_bd_creds "$(docker_conf "$slug" CARPETA)") || { echo "No se puede leer el usuario y la base del wp-config.php de $(docker_conf "$slug" CARPETA)"; return 1; }
            user=${creds%%|*} db=$(head -1 <<< "$creds" | cut -d'|' -f2) pass=$(sed -n 2p <<< "$creds")
            echo "$slug: BBDD $db de lampp-$owner, en vivo (la misma que web.local; la copia de Docker se queda)"
            [ "$DRY" -eq 1 ] && return 0
            # (los de Docker de antes, para volver: BBDD y usuario de su copia)
            [ -z "$(docker_conf "$slug" LAMPP_BD)" ] && docker_conf_set "$slug" BBDD_DOCKER "$(docker_conf "$slug" BBDD)" \
                && docker_conf_set "$slug" USUARIO_DOCKER "$(docker_conf "$slug" USUARIO)" \
                && { grep -q '^DB_PASS_DOCKER=' "$dir/.env" || ( umask 077; sed -n 's/^DB_PASS=/DB_PASS_DOCKER=/p' "$dir/.env" >> "$dir/.env" ); }
            docker_conf_set "$slug" LAMPP_BD "$owner" && docker_conf_set "$slug" BBDD "$db" && docker_conf_set "$slug" USUARIO "$user" || return 1
            ( umask 077; { grep -v '^DB_PASS=' "$dir/.env"; printf 'DB_PASS=%s\n' "$pass"; } > "$dir/.env.nuevo" ) && mv -f "$dir/.env.nuevo" "$dir/.env" || return 1 ;;
        docker)
            owner=$(docker_conf "$slug" LAMPP_BD)
            [ -n "$owner" ] || { echo "$slug ya usa su copia de Docker"; return 0; }
            [ -n "$(docker_conf "$slug" BBDD_DOCKER)" ] || { echo "$slug no tiene copia en Docker: crea el proyecto de nuevo copiando la BBDD"; return 1; }
            echo "$slug: vuelve a su copia de Docker ($(docker_conf "$slug" BBDD_DOCKER))"
            [ "$DRY" -eq 1 ] && return 0
            docker_conf_set "$slug" BBDD "$(docker_conf "$slug" BBDD_DOCKER)" && docker_conf_set "$slug" USUARIO "$(docker_conf "$slug" USUARIO_DOCKER)" \
                && docker_conf_set "$slug" LAMPP_BD "" || return 1
            ( umask 077; { grep -v '^DB_PASS=' "$dir/.env"; sed -n 's/^DB_PASS_DOCKER=/DB_PASS=/p' "$dir/.env"; } > "$dir/.env.nuevo" ) && mv -f "$dir/.env.nuevo" "$dir/.env" || return 1 ;;
        *) echo "Uso: nexum docker-bd <nombre> lampp <version> | docker"; return 1 ;;
    esac
    # (su configuracion con la BBDD nueva; si estaba en marcha, se arranca de nuevo con ella)
    was=$(dk ps --format '{{.Names}}' 2> /dev/null | grep -cE "^nexum-$slug-php[0-9]{2}\$")
    for v in $(docker_conf "$slug" PHP); do docker_web_config "$slug" "$v" > /dev/null || return 1; done
    if [ "$was" -gt 0 ]; then
        docker_web_action arrancar "$slug" || return 1
        [ "$mode" == docker ] && lampp_bd_release "$owner" "$slug"
    fi
    echo "Listo"
}

# Aviso al parar algo comun (una MariaDB comun, el Apache de Docker o su phpMyAdmin) que usa algun
# proyecto en marcha: cuales se quedan sin el
function docker_shared_warn() {
    local name=$1 up p v="" users=() lampp=""
    if [[ "$name" =~ ^nexum-lampp-bd-([0-9]{1,2})-([0-9]{1,2})(-([0-9]{1,3}))?$ ]]; then
        lampp=${BASH_REMATCH[1]}.${BASH_REMATCH[2]}${BASH_REMATCH[4]:+.${BASH_REMATCH[4]}} v=x
    else
        [[ "$name" =~ ^nexum-(web|pma|mariadb-([0-9]{1,2})-([0-9]{1,2}))$ ]] || return 0
        [ -n "${BASH_REMATCH[2]}" ] && v=${BASH_REMATCH[2]}.${BASH_REMATCH[3]}
    fi
    up=$(dk ps --format '{{.Names}}' 2> /dev/null) || return 0
    for p in $(docker_web_projects); do
        if [ -n "$lampp" ]; then
            [ "$(docker_conf "$p" LAMPP_BD)" == "$lampp" ] || continue
        elif [ -n "$v" ] && { [ "$(docker_conf "$p" MARIADB)" != "$v" ] || [ -n "$(docker_conf "$p" LAMPP_BD)" ]; }; then
            continue
        fi
        grep -qE "^nexum-$p-php[0-9]{2}\$" <<< "$up" && users+=("$(docker_conf "$p" CARPETA)")
    done
    [ ${#users[@]} -eq 0 ] && return 0
    echo "Aviso: $name es comun y lo usan ahora: ${users[*]}. $([ -n "$v" ] && echo "Se quedan sin BBDD" || echo "Dejan de verse") hasta que lo arranques"
}

# docker-parar-todo: todos los contenedores de Nexum en marcha (los de los proyectos, las MariaDB
# comunes, el Apache de Docker y su phpMyAdmin), parados. Los de otros programas no se tocan
function docker_stop_all() {
    local up names=()
    up=$(dk ps --format '{{.Names}}' 2> /dev/null) || { echo "Docker no responde"; return 1; }
    mapfile -t names < <(grep -E '^nexum-([a-z0-9]([a-z0-9-]{0,38}[a-z0-9])?-((php|db|pma)-[0-9]{1,3}|php[0-9]{2})|web|pma|mariadb-[0-9]{1,2}-[0-9]{1,2}|lampp-bd-[0-9]{1,2}-[0-9]{1,2}(-[0-9]{1,3})?)$' <<< "$up")
    if [ ${#names[@]} -eq 0 ]; then
        echo "No hay ningun contenedor de Nexum en marcha"
        return 0
    fi
    echo "Parando ${#names[@]} contenedores de Nexum: ${names[*]}"
    run dk stop "${names[@]}" > /dev/null || return 1
    # (y la MariaDB de LAMPP que hubiera arrancado Docker para alguno)
    local f
    # shellcheck disable=SC2045  # (nombres de versión ya comprobados, sin espacios)
    for f in $(ls "$LAMPP_BD_MARK_DIR" 2> /dev/null); do valid_version_name "$f" && lampp_bd_release "$f"; done
    echo "Todos parados"
}

# docker-pasar <nombre> [--copia]: un proyecto de antes (PHP-FPM con LAMPP delante, con su MariaDB y su phpMyAdmin)
# pasa al Apache de Docker. Su BBDD se descarga a un fichero (con --copia, en ~/nexum-backups, y se queda;
# sin ella, uno temporal que se borra al acabar bien; si algo falla, ahi esta) y se carga
# en la MariaDB comun; despues se quitan sus contenedores, su vhost de LAMPP y su linea de hosts. Si la
# carpeta ya esta en el sistema nuevo (otra version de PHP del mismo proyecto), solo se le añade su PHP
function docker_pass() {
    local slug=$1 dir folder php maria db target="" p backup copy=0
    [ "$2" == "--copia" ] && copy=1
    if ! docker_valid_slug "$slug" || [ ! -f "$DOCKER_DIR/$slug/proyecto.conf" ] || docker_web_project "$slug"; then
        echo "No hay ningun proyecto de antes (con LAMPP delante) con el nombre $slug"
        return 1
    fi
    dir=$DOCKER_DIR/$slug
    folder=$(docker_conf "$slug" CARPETA) php=$(docker_conf "$slug" PHP) maria=$(docker_conf "$slug" MARIADB) db=$(docker_conf "$slug" BBDD)
    db_valid_name "$db" > /dev/null || { echo "$slug no tiene una BBDD valida en su proyecto.conf"; return 1; }
    for p in $(docker_web_projects); do
        [ "$(docker_conf "$p" CARPETA)" == "$folder" ] && target=$p
    done
    echo "$slug pasa al Apache de Docker${target:+ (como PHP $php de $target)}"
    if [ "$DRY" -eq 1 ]; then
        [ $copy -eq 1 ] && echo "  [simulacion] copia de $db en ~/nexum-backups, fuera sus contenedores, su vhost y su linea de hosts"
        [ $copy -eq 0 ] && echo "  [simulacion] sin copia: $db pasa por un fichero temporal; fuera sus contenedores, su vhost y su linea de hosts"
        return 0
    fi
    docker_ready || { echo "Docker sin root no esta en marcha"; return 1; }
    docker_web_ports_ok || { echo "Docker sin root aun no puede usar los puertos del Apache de Docker: pulsa «Permitir» en Configuracion"; return 1; }
    sudo_first || return 1
    task_plan "Pasando $folder al Apache de Docker" "Copiar su BBDD" "Quitar el proyecto de antes" "Montarlo en el Apache de Docker"
    task_step
    echo "Copia de su BBDD ($db)"
    if [ $copy -eq 1 ]; then
        mkdir -p -m 700 "$COPIES_DIR" || return 1
        backup="$COPIES_DIR/docker-$slug-$db-$(date +%Y%m%d-%H%M%S).sql.gz"
    else
        # (sin copia: un fichero solo tuyo en ~/.lvm-instalador, que se borra cuando ya esta cargada)
        mkdir -p -m 700 "$LOG_DIR" || return 1
        backup=$(mktemp "$LOG_DIR/pasar-$slug-XXXXXX") || return 1
        mv -f "$backup" "$backup.sql.gz" && backup=$backup.sql.gz || { rm -f "$backup"; return 1; }
    fi
    dk compose --project-directory "$dir" -f "$dir/compose.yaml" up -d db > /dev/null || { rm -f "$backup"; return 1; }
    local i
    for i in $(seq 60); do
        dk compose --project-directory "$dir" -f "$dir/compose.yaml" exec -T db \
            sh -c 'MYSQL_PWD=$MARIADB_ROOT_PASSWORD exec $(command -v mariadb || command -v mysql) -uroot -e "SELECT 1"' < /dev/null > /dev/null 2>&1 && break
        sleep 1
    done
    ( umask 077
      set -o pipefail
      dk compose --project-directory "$dir" -f "$dir/compose.yaml" exec -T db \
          sh -c 'MYSQL_PWD=$MARIADB_ROOT_PASSWORD exec $(command -v mariadb-dump || command -v mysqldump) -uroot --single-transaction --routines --triggers --events "$0"' "$db" \
          < /dev/null | gzip > "$backup" )
    if [ $? -ne 0 ] || [ "$(gzip -dc "$backup" 2> /dev/null | head -c 4096 | wc -c)" -lt 100 ]; then
        echo "No se ha podido copiar su BBDD: no se cambia nada"
        rm -f "$backup"
        return 1
    fi
    [ $copy -eq 1 ] && echo "Copia de $db: $backup"
    task_step
    docker_action borrar "$slug" || { echo "No se ha podido quitar el proyecto de antes (la copia de su BBDD esta en $backup)"; return 1; }
    task_step
    if [ -n "$target" ]; then
        docker_web_add "$target" "$php" || return 1
        echo "$folder ya tenia BBDD en el sistema nuevo: la de $slug no se carga (esta en $backup)"
    else
        docker_web_create "$folder" "$php" "$maria" --bd "$db" --volcado "$backup" \
            || { echo "La copia de su BBDD sigue en $backup"; return 1; }
    fi
    # (si no se ha cargado, porque ya tenia BBDD, la descarga se queda: es lo unico que hay de ella)
    if [ $copy -eq 0 ] && [ -z "$target" ]; then
        rm -f "$backup"
        echo "Sin copia: la descarga de $db ya esta cargada y se ha borrado (con --copia se guarda en ~/nexum-backups)"
    fi
    echo "$slug ya funciona con el Apache de Docker"
}

# Tunel de Cloudflare: una web de este equipo, a la vista de un cliente o de un compañero con una
# direccion publica (https://<algo>.trycloudflare.com, sin cuenta: cambia cada vez). cloudflared abre
# una conexion de salida a Cloudflare, sin abrir puertos, y lo que llega por ella pasa por un proxy
# del programa (TUNNEL_PY, solo en 127.0.0.1) antes de llegar a Apache:
#  - pide una contraseña (la de ese tunel: al azar o la que se elija al abrirlo) y se cierra solo pasadas
#    las horas que se elijan
#  - el admin de WordPress o PrestaShop, bloqueado (las BBDD llevan el administrador de pruebas, con
#    contraseña conocida), y siempre lo de LAMPP para este equipo (phpMyAdmin...): Apache ve las
#    peticiones del proxy como de 127.0.0.1
#  - cambia el dominio local (web.local, el de la tienda...) por el del tunel en lo que devuelve la web:
#    no se toca ni wp-config.php ni la BBDD, y al cerrarlo no hay nada que deshacer
# Un tunel cada vez. cloudflared va en ~/.lvm-instalador/tunel, con tu usuario (sin root): version fijada
# y sha256 de la publicacion en GitHub (sus digest, iguales a los de sus notas, el 27/10/2026)
TUNNEL_VERSION="2026.10.0"
TUNNEL_SHA_AMD64="d33ff2d14475178d2012c2c56beba87389ac5ded27649519f198a7d3134a99db"
TUNNEL_SHA_ARM64="e6422b9d4f72d3194bc5a38676f13667c06666523217b842a877d72a80b5ac08"
TUNNEL_DIR=$LOG_DIR/tunel
TUNNEL_BIN=$TUNNEL_DIR/cloudflared
# El tunel abierto (lo escribe TUNNEL_PY al tener su direccion, solo tuyo): JSON con pid, url, destino,
# carpeta, fin, su contraseña, sus horas y si bloquea el admin
TUNNEL_STATE=$TUNNEL_DIR/estado
TUNNEL_LOG=$TUNNEL_DIR/registro

function tunnel_installed() {
    [ -f "$TUNNEL_BIN" ] && [ -x "$TUNNEL_BIN" ] && [ ! -L "$TUNNEL_BIN" ]
}

function tunnel_installed_version() {
    tunnel_installed && head -c 40 "$TUNNEL_DIR/version" 2> /dev/null | tr -cd '0-9.'
}

# tunel-instalar: descarga cloudflared de GitHub y comprueba su sha256 antes de dejarlo en su sitio
function tunnel_install() {
    local arch sha url tmp got tls=(--proto '=https' --tlsv1.2)
    case $(uname -m) in
        x86_64|amd64) arch=amd64 sha=$TUNNEL_SHA_AMD64 ;;
        aarch64|arm64) arch=arm64 sha=$TUNNEL_SHA_ARM64 ;;
        *) echo "Cloudflare no publica cloudflared para este equipo ($(uname -m))"; return 1 ;;
    esac
    url=https://github.com/cloudflare/cloudflared/releases/download/$TUNNEL_VERSION/cloudflared-linux-$arch
    # (las pruebas, sin red: otro fichero y su suma)
    if [ -n "$TEST_DIR" ]; then
        url=${LVM_CLOUDFLARED_URL:-$url} sha=${LVM_CLOUDFLARED_SHA:-$sha} tls=()
    fi
    if [ "$(tunnel_installed_version)" == "$TUNNEL_VERSION" ]; then
        echo "cloudflared $TUNNEL_VERSION ya esta instalado en $TUNNEL_DIR"
        return 0
    fi
    task_plan "Instalando cloudflared $TUNNEL_VERSION" "Descargar cloudflared" "Comprobar la descarga" "Instalar cloudflared"
    echo "Instalando cloudflared $TUNNEL_VERSION (tunel de Cloudflare) en $TUNNEL_DIR"
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] descarga de $url y comprobacion de su sha256"
        return 0
    fi
    if [ -L "$TUNNEL_DIR" ] || [ -L "$TUNNEL_BIN" ]; then
        echo "$TUNNEL_DIR o su cloudflared son un enlace: no se instala"
        return 1
    fi
    mkdir -p -m 700 "$TUNNEL_DIR" || return 1
    tmp=$(mktemp "$TUNNEL_DIR/cloudflared-descarga.XXXXXX") || return 1
    task_step
    echo "Descargando cloudflared-linux-$arch (unos 40 MB)..."
    if ! curl -fsSL "${tls[@]}" --retry 2 --max-time 900 -o "$tmp" "$url"; then
        rm -f "$tmp"
        echo "No se ha podido descargar cloudflared ($url)"
        return 1
    fi
    task_step
    got=$(sha256sum "$tmp" 2> /dev/null | cut -d' ' -f1)
    if [ "$got" != "$sha" ]; then
        rm -f "$tmp"
        echo "La descarga de cloudflared no coincide con su suma sha256 (${got:-ninguna}): no se instala."
        return 1
    fi
    task_step
    chmod 755 "$tmp" && mv -f "$tmp" "$TUNNEL_BIN" && echo "$TUNNEL_VERSION" > "$TUNNEL_DIR/version" || { rm -f "$tmp"; return 1; }
    echo "cloudflared $TUNNEL_VERSION instalado: $TUNNEL_BIN"
}

# Contraseña nueva, facil de dictar: tres grupos de cuatro letras y numeros sin los que se confunden
function tunnel_new_pass() {
    local s
    s=$(LC_ALL=C tr -dc 'abcdefghjkmnpqrstuvwxyz23456789' < /dev/urandom | head -c 12)
    echo "${s:0:4}-${s:4:4}-${s:8:4}"
}

# PID del tunel abierto (el de TUNNEL_PY, si sigue vivo y es el)
function tunnel_pid() {
    local pid
    pid=$(python3 -I -c 'import json, sys
try:
    print(int(json.load(open(sys.argv[1]))["pid"]))
except Exception:
    pass' "$TUNNEL_STATE" 2> /dev/null)
    [[ "$pid" =~ ^[0-9]+$ ]] && tr '\0' ' ' < "/proc/$pid/cmdline" 2> /dev/null | grep -q "nexum-tunel" && echo "$pid"
}

# tunel-cerrar
function tunnel_close() {
    local pid n
    pid=$(tunnel_pid)
    if [ -z "$pid" ]; then
        rm -f "$TUNNEL_STATE"
        echo "No hay ningun tunel abierto"

        return 0
    fi
    [ "$DRY" -eq 1 ] && { echo "  [simulacion] se cierra el tunel ($pid)"; return 0; }
    kill -TERM "$pid" 2> /dev/null
    for n in $(seq 20); do
        kill -0 "$pid" 2> /dev/null || break
        sleep 0.25
    done
    kill -0 "$pid" 2> /dev/null && kill -KILL "$pid" 2> /dev/null
    rm -f "$TUNNEL_STATE"
    echo "Tunel cerrado: la direccion ya no lleva a ningun sitio"
}

# tunel-abrir <direccion local> [carpeta del proyecto] [--horas 1-12] [--admin bloquear|permitir]: la
# direccion, de una web de este equipo (http://web.local, https://proyecto-php83.docker.local:8443...); la
# carpeta, para saber que admin bloquear y el dominio de una tienda PrestaShop. Cada tunel con lo suyo: sus
# horas (2 si no se dice), el admin (bloqueado si no se dice) y su contraseña, siempre una nueva al azar
# (la de un tunel no vale para el siguiente). Cierra el que hubiera
function tunnel_open() {
    local url=$1 folder="" scheme host port ip clave horas=2 admin=bloquear params dir="" domains n url_t
    shift
    [ -n "$1" ] && [[ "$1" != --* ]] && { folder=${1%/}; shift; }
    while [ $# -gt 0 ]; do
        case $1 in
            --horas) [[ "$2" =~ ^([1-9]|1[0-2])$ ]] || { echo "Las horas van de 1 a 12"; return 1; }; horas=$2; shift 2 ;;
            --admin) [[ "$2" =~ ^(bloquear|permitir)$ ]] || { echo "--admin bloquear o permitir"; return 1; }; admin=$2; shift 2 ;;
            *) echo "Opcion desconocida: $1"; return 1 ;;
        esac
    done
    if [ -z "$url" ]; then
        echo "Uso: nexum tunel-abrir <direccion local> [carpeta] [--horas 1-12] [--admin bloquear|permitir]"

        return 1
    fi
    clave=$(tunnel_new_pass)
    if ! [[ "$url" =~ ^(https?)://([A-Za-z0-9.-]+)(:([0-9]{1,5}))?/?$ ]]; then
        echo "$url no es una direccion valida (como http://web.local)"

        return 1
    fi
    scheme=${BASH_REMATCH[1]} host=$(tr 'A-Z' 'a-z' <<< "${BASH_REMATCH[2]}") port=${BASH_REMATCH[4]}
    [ -n "$port" ] || { [ "$scheme" == https ] && port=443 || port=80; }
    # Solo webs de este equipo: el proxy no lleva a ningun otro sitio
    ip=$(getent ahostsv4 "$host" 2> /dev/null | awk '{ print $1; exit }')
    if ! valid_domain "$host" || [[ ! "$ip" =~ ^127\. ]]; then
        echo "$host no es una web de este equipo (no lleva a 127.x en /etc/hosts): no se comparte"

        return 1
    fi
    if [ -n "$folder" ]; then
        [[ "$folder" == /* ]] || folder=$HTDOCS_DIR/$folder
        dir=$(realpath -e "$folder" 2> /dev/null)
        if [ -z "$dir" ] || [ ! -d "$dir" ] || [[ "$dir" != "$(realpath -e "$HTDOCS_DIR")"/* ]]; then
            echo "$folder no es la carpeta de un proyecto de $HTDOCS_DIR"

            return 1
        fi
    fi
    if ! tunnel_installed; then
        echo "Falta cloudflared: nexum tunel-instalar (o en Configuracion, Tunel de Cloudflare)"

        return 1
    fi
    # Los dominios de la web que se cambian por el del tunel: el suyo y, en una tienda, el de su BBDD
    # (va con el dominio real falseado: la direccion local lleva a el)
    domains=$host
    if [ -n "$dir" ] && is_prestashop "$(basename "$dir")" 2> /dev/null; then
        n=$(ps_domain "$(basename "$dir")" 2> /dev/null)
        valid_domain "$n" && domains+=" $n"
    fi
    echo "Abriendo un tunel de Cloudflare a $scheme://$host$([[ "$port" =~ ^(80|443)$ ]] || echo ":$port")/"
    echo "(con contraseña, el admin $([ "$admin" == bloquear ] && echo bloqueado || echo "SIN bloquear") y se cierra solo en $horas h)"
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] cloudflared tunnel --url http://127.0.0.1:<puerto del proxy>"

        return 0
    fi
    tunnel_close > /dev/null
    mkdir -p -m 700 "$TUNNEL_DIR" || return 1
    # (lo que necesita el proxy, en un fichero solo tuyo que borra al leerlo: la contraseña no va en
    # la linea de ordenes)
    params=$(mktemp "$TUNNEL_DIR/abrir.XXXXXX") || return 1
    T_SCHEME=$scheme T_HOST=$host T_PORT=$port T_DOMAINS=$domains T_FOLDER=$dir T_CLAVE=$clave T_HORAS=$horas \
        T_ADMIN=$admin T_BIN=$TUNNEL_BIN T_STATE=$TUNNEL_STATE T_DIR=$TUNNEL_DIR T_ICON=$(tr -d ' \n' <<< "$ICON_PNG_B64") \
        python3 -I -c 'import json, os, sys
e = os.environ
json.dump({"scheme": e["T_SCHEME"], "host": e["T_HOST"], "port": int(e["T_PORT"]), "domains": e["T_DOMAINS"].split(),
           "folder": e["T_FOLDER"], "password": e["T_CLAVE"], "hours": int(e["T_HORAS"]), "admin": e["T_ADMIN"],
           "cloudflared": e["T_BIN"], "state": e["T_STATE"], "dir": e["T_DIR"], "icon": e["T_ICON"]}, open(sys.argv[1], "w"))' \
        "$params" || { rm -f "$params"; return 1; }
    rm -f "$TUNNEL_STATE"
    : > "$TUNNEL_LOG" && chmod 600 "$TUNNEL_LOG"
    # (aparte de esta tarea: sigue abierto al cerrar la ventana, hasta su hora o tunel-cerrar)
    setsid python3 -I -c "$TUNNEL_PY" nexum-tunel "$params" >> "$TUNNEL_LOG" 2>&1 < /dev/null &
    for n in $(seq 120); do
        [ -s "$TUNNEL_STATE" ] && break
        kill -0 $! 2> /dev/null || break
        sleep 0.5
    done
    url_t=$(python3 -I -c 'import json, sys; print(json.load(open(sys.argv[1]))["url"])' "$TUNNEL_STATE" 2> /dev/null)
    if [ -z "$url_t" ]; then
        kill -TERM $! 2> /dev/null
        rm -f "$params" "$TUNNEL_STATE"
        echo "No se ha podido abrir el tunel. Lo ultimo de cloudflared:"
        grep -v '^\s*$' "$TUNNEL_LOG" | tail -6 | sed 's/^/  /'
        echo "(sin conexion a Internet, o Cloudflare no da tuneles rapidos ahora mismo: prueba en un rato)"

        return 1
    fi
    echo "Tunel abierto: $url_t"
    echo "Contraseña para entrar: $clave"
    echo "URL|$url_t"
}

# tunel [estado]: para la ventana y la terminal
#   I|instalado (1/0)|version instalada|version del programa
#   T|url|direccion local|carpeta|fin (epoch)   (si hay uno abierto)
function tunnel_status() {
    local pid
    echo "I|$(tunnel_installed && echo 1 || echo 0)|$(tunnel_installed_version)|$TUNNEL_VERSION"
    pid=$(tunnel_pid)
    [ -n "$pid" ] && python3 -I -c 'import json, sys
s = json.load(open(sys.argv[1]))
print("T|%s|%s|%s|%d" % (s["url"], s["target"], s["folder"], s["expires"]))' "$TUNNEL_STATE" 2> /dev/null
    return 0
}

TUNNEL_PY=$(cat <<'PYEOF'
import hashlib, hmac, html, http.client, http.server, json, os, re, secrets, signal, socket
import socketserver, ssl, subprocess, sys, threading, time, urllib.parse

params_path = sys.argv[2]
P = json.load(open(params_path))
os.remove(params_path)
STATE, DIR = P["state"], P["dir"]
EXPIRES = int(time.time() + int(P["hours"]) * 3600)
PASSWORD = P["password"].encode()
KEY = secrets.token_bytes(32)
COOKIE = "nexum_tunel"
TOKEN = hmac.new(KEY, b"dentro", hashlib.sha256).hexdigest()
DOMAINS = [d.lower() for d in P["domains"]]
TEXT = re.compile(r"^(text/|application/(javascript|x-javascript|json|ld\+json|xml|rss\+xml|atom\+xml|"
                  r"manifest\+json)|image/svg\+xml)", re.I)
HOP = {"connection", "keep-alive", "proxy-connection", "transfer-encoding", "te", "trailer", "upgrade",
       "proxy-authorization", "proxy-authenticate"}
tunnel_host = None


def log(text):
    print(time.strftime("%H:%M:%S"), text, flush=True)


def loopback(host):
    try:
        return all(a[4][0].startswith("127.") for a in socket.getaddrinfo(host, None, socket.AF_INET))
    except OSError:
        return False


# A donde van las peticiones: el destino y, si la web redirige a otro de sus dominios de este equipo
# (web.local a https://tienda.es, http a https), ese desde entonces
origin = {"scheme": P["scheme"], "host": P["host"], "port": int(P["port"])}
origin_lock = threading.Lock()


def host_header(o):
    default = 443 if o["scheme"] == "https" else 80
    return o["host"] if o["port"] == default else "%s:%d" % (o["host"], o["port"])


# Lo que nunca va por el tunel: lo de LAMPP para este equipo (Apache ve el proxy como 127.0.0.1) y los
# ficheros ocultos. Y el admin, salvo que se permita
BLOCKED = ["/phpmyadmin", "/cgi-bin", "/server-status", "/server-info", "/dashboard", "/xampp", "/webalizer",
           "/licenses", "/__nexum"]
ADMIN = []
if P["admin"] != "permitir":
    ADMIN = ["/wp-login.php", "/wp-admin", "/xmlrpc.php"]
    folder = P["folder"]
    if folder:
        try:
            for n in os.listdir(folder):
                d = os.path.join(folder, n)
                if re.fullmatch(r"[A-Za-z0-9_-]+", n) and os.path.isdir(d) and os.path.isfile(os.path.join(d, "index.php")) \
                        and any(os.path.isfile(os.path.join(d, f)) for f in ("ajax-tab.php", "get-file-admin.php")):
                    ADMIN.append("/" + n.lower())
        except OSError:
            pass
# (wp-admin/admin-ajax.php lo usan las webs de cara al publico)
ALLOWED = ["/wp-admin/admin-ajax.php"]


def blocked(path):
    p = urllib.parse.unquote(path.split("?", 1)[0]).lower()
    p = re.sub(r"/+", "/", p)
    # (cualquier /../ o /./ se rechaza entero: Apache los normaliza y saltaria la lista)
    if re.search(r"(^|/)\.\.?(/|$)", p) or "\\" in p or "\x00" in p:
        return "ruta"
    if re.search(r"/\.(?!well-known/)", p):
        return "oculto"
    if any(p == a for a in ALLOWED):
        return None
    for b in BLOCKED:
        if p == b or p.startswith(b + "/"):
            return "local"
    for b in ADMIN:
        if p == b or p.startswith(b + "/") or p.startswith(b + "?"):
            return "admin"
    return None


def pattern():
    names = b"|".join(re.escape(d.encode()) for d in DOMAINS)
    return (re.compile(rb"(?:https?:)?(\\?/\\?/)(?:www\.)?(?:" + names + rb")(?::\d+)?(?![A-Za-z0-9.-])", re.I),
            re.compile(rb"https?%3A%2F%2F(?:www\.)?(?:" + names + rb")(?:%3A\d+)?(?![A-Za-z0-9.-])", re.I))


URL_RE, ENC_RE = pattern()


def to_tunnel(data):
    t = tunnel_host.encode()
    data = URL_RE.sub(lambda m: (b"https:\\/\\/" if b"\\" in m.group(1) else b"https://") + t, data)
    return ENC_RE.sub(b"https%3A%2F%2F" + t, data)


def to_local(text):
    """Al reves, en lo que manda el visitante (Origin, Referer, la consulta y los formularios)."""
    if not tunnel_host:
        return text
    o = origin
    local = "%s://%s" % (o["scheme"], host_header(o))
    text = re.sub(r"https?://" + re.escape(tunnel_host), local, text, flags=re.I)
    return re.sub(r"https?%3A%2F%2F" + re.escape(tunnel_host), urllib.parse.quote(local, safe=""), text, flags=re.I)


class HTTPS(http.client.HTTPSConnection):
    """A la direccion de este equipo del dominio, con su nombre en el certificado (SNI)."""

    def __init__(self, ip, host, port, timeout):
        ctx = ssl.create_default_context()
        # (los certificados de este equipo son propios: el que importa es el de Cloudflare)
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE
        super().__init__(ip, port, timeout=timeout, context=ctx)
        self.sni = host

    def connect(self):
        sock = socket.create_connection((self.host, self.port), self.timeout)
        self.sock = self._context.wrap_socket(sock, server_hostname=self.sni)


def connect(o):
    ip = socket.getaddrinfo(o["host"], None, socket.AF_INET)[0][4][0]
    if not ip.startswith("127."):
        raise OSError("%s ya no es de este equipo" % o["host"])
    if o["scheme"] == "https":
        return HTTPS(ip, o["host"], o["port"], 120)
    return http.client.HTTPConnection(ip, o["port"], timeout=120)


fails, fails_lock = {}, threading.Lock()


def page(title, body, status_note=""):
    return ("""<!doctype html><html lang="es"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex">
<title>%s</title><style>body{font-family:system-ui,sans-serif;background:#1e1e1e;color:#ddd;display:flex;
align-items:center;justify-content:center;min-height:100vh;margin:0;padding:16px;box-sizing:border-box}
main{text-align:center;max-width:26em;width:100%%}img{width:72px;height:72px}h1{font-size:1.3em;font-weight:500}
p{color:#9a9a9a;line-height:1.5}input{width:100%%;box-sizing:border-box;font-size:1.1em;padding:10px 12px;
border-radius:8px;border:1px solid #555;background:#2a2a2a;color:#fff;margin:6px 0 12px}
button{width:100%%;font-size:1.05em;padding:10px;border:0;border-radius:8px;background:#3584e4;color:#fff;
cursor:pointer}.err{color:#f66}small{color:#777}</style></head><body><main>
<img src="data:image/png;base64,%s" alt=""><h1>%s</h1>%s<p><small>Nexum Dev Stack · una web en pruebas</small></p>
</main></body></html>""" % (html.escape(title), P["icon"], html.escape(title), body)).encode()


class Proxy(http.server.BaseHTTPRequestHandler):
    server_version = "Nexum"
    sys_version = ""

    def log_message(self, fmt, *args):
        pass

    def visitor(self):
        return self.headers.get("Cf-Connecting-IP", "")[:64] or self.client_address[0]

    def send_page(self, status, data, extra=()):
        self.send_response(status)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Cache-Control", "no-store")
        self.send_header("X-Robots-Tag", "noindex, nofollow")
        for k, v in extra:
            self.send_header(k, v)
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(data)

    def logged_in(self):
        for part in self.headers.get("Cookie", "").split(";"):
            k, _, v = part.strip().partition("=")
            if k == COOKIE and hmac.compare_digest(v, TOKEN):
                return True
        return False

    def login(self):
        back = self.path if self.path.startswith("/") and not self.path.startswith("//") else "/"
        if self.command == "POST" and self.path.split("?")[0] == "/__nexum-tunel/entrar":
            ip = self.visitor()
            with fails_lock:
                recent = [t for t in fails.get(ip, []) if t > time.time() - 600]
                fails[ip] = recent
            if len(recent) >= 8:
                log("%s: demasiados intentos" % ip)
                return self.send_page(429, page("Demasiados intentos", "<p>Espera unos minutos y vuelve a probar.</p>"))
            n = int(self.headers.get("Content-Length") or 0)
            form = urllib.parse.parse_qs(self.rfile.read(min(n, 4096)).decode("utf-8", "replace"))
            given = (form.get("clave") or [""])[0].strip().encode()
            back = (form.get("volver") or ["/"])[0]
            if not back.startswith("/") or back.startswith("//") or "\\" in back:
                back = "/"
            if hmac.compare_digest(given, PASSWORD):
                log("%s: entra" % ip)
                self.send_response(303)
                self.send_header("Location", back)
                self.send_header("Set-Cookie", "%s=%s; Path=/; Secure; HttpOnly; SameSite=Lax" % (COOKIE, TOKEN))
                self.send_header("Content-Length", "0")
                self.end_headers()
                return
            with fails_lock:
                fails.setdefault(ip, []).append(time.time())
            log("%s: contraseña equivocada" % ip)
            err = '<p class="err">Esa no es la contraseña.</p>'
        else:
            err = ""
        body = ('<p>Esta web está en pruebas. Escribe la contraseña que te han dado.</p>%s'
                '<form method="post" action="/__nexum-tunel/entrar"><input type="hidden" name="volver" value="%s">'
                '<input type="password" name="clave" autocomplete="current-password" autofocus placeholder="Contraseña">'
                '<button type="submit">Entrar</button></form>' % (err, html.escape(back, quote=True)))
        self.send_page(401, page("Web en pruebas", body))

    def handle_any(self):
        if not self.logged_in():
            return self.login()
        why = blocked(self.path)
        if why:
            log("%s: %s %s (bloqueado: %s)" % (self.visitor(), self.command, self.path[:200], why))
            text = ("El panel de administración no se puede abrir desde aquí." if why == "admin"
                    else "Esto no se puede abrir desde aquí.")
            return self.send_page(403, page("No disponible", "<p>%s</p>" % text))
        body = self.read_body()
        if body is None:
            return self.send_page(400, page("Petición no válida", ""))
        ctype = self.headers.get("Content-Type", "")
        if body and len(body) < 10_000_000 and ctype.startswith(("application/x-www-form-urlencoded", "text/", "application/json")):
            body = to_local(body.decode("latin-1")).encode("latin-1")
        path = to_local(self.path)
        for _hop in range(4):
            with origin_lock:
                o = dict(origin)
            headers = {}
            for k, v in self.headers.items():
                lk = k.lower()
                if lk in HOP or lk in ("host", "content-length", "accept-encoding") or lk.startswith("cf-") \
                        or lk.startswith("x-forwarded-") or lk == "cdn-loop":
                    continue
                if lk == "cookie":
                    v = "; ".join(c for c in (x.strip() for x in v.split(";")) if c and not c.startswith(COOKIE + "="))
                    if not v:
                        continue
                elif lk in ("origin", "referer"):
                    v = to_local(v)
                headers[k] = v
            headers["Host"] = host_header(o)
            headers["Accept-Encoding"] = "identity"
            if body or self.command in ("POST", "PUT", "PATCH"):
                headers["Content-Length"] = str(len(body))
            try:
                conn = connect(o)
                conn.request(self.command, path, body=body or None, headers=headers)
                res = conn.getresponse()
            except OSError as exc:
                log("Sin respuesta de %s: %s" % (host_header(o), exc))
                return self.send_page(502, page("La web no responde", "<p>La web de este equipo no contesta. "
                                                "Puede que se haya parado: vuelve a probar en un momento.</p>"))
            # Redirige a otro de sus dominios de este equipo: se sigue aqui y desde entonces va ahi
            loc = res.getheader("Location", "")
            if res.status in (301, 302, 307, 308) and self.command in ("GET", "HEAD") and loc:
                u = urllib.parse.urlsplit(loc)
                new = {"scheme": (u.scheme or o["scheme"]).lower(), "host": (u.hostname or "").lower(),
                       "port": u.port or (443 if (u.scheme or o["scheme"]).lower() == "https" else 80)}
                if u.hostname and new != o and re.sub(r"^www\.", "", new["host"]) in [re.sub(r"^www\.", "", d) for d in DOMAINS] \
                        and new["scheme"] in ("http", "https") and new["port"] in (80, 443, int(P["port"])) and loopback(new["host"]):
                    res.read()
                    conn.close()
                    with origin_lock:
                        origin.update(new)
                    log("La web va a %s://%s" % (new["scheme"], host_header(new)))
                    path = urllib.parse.urlunsplit(("", "", u.path or "/", u.query, ""))
                    continue
            return self.relay(res, conn)
        return self.send_page(508, page("Demasiadas redirecciones", ""))

    def read_body(self):
        if "chunked" in self.headers.get("Transfer-Encoding", "").lower():
            out = b""
            while True:
                line = self.rfile.readline(65537)
                try:
                    size = int(line.split(b";")[0].strip(), 16)
                except ValueError:
                    return None
                if size == 0:
                    while self.rfile.readline(65537).strip():
                        pass
                    return out
                out += self.rfile.read(size)
                self.rfile.readline(3)
                if len(out) > 512_000_000:
                    return None
        n = self.headers.get("Content-Length")
        if not n:
            return b""
        if not n.isdigit() or int(n) > 512_000_000:
            return None
        return self.rfile.read(int(n))

    def relay(self, res, conn):
        ctype = res.getheader("Content-Type", "")
        rewrite = bool(TEXT.match(ctype)) and self.command != "HEAD"
        length = res.getheader("Content-Length")
        if rewrite and length and length.isdigit() and int(length) > 30_000_000:
            rewrite = False
        self.send_response(res.status, res.reason)
        for k, v in res.getheaders():
            lk = k.lower()
            if lk in HOP or lk == "content-length" or (rewrite and lk == "content-encoding"):
                continue
            if lk == "set-cookie":
                # (sin Domain: la cookie es del dominio del tunel)
                v = re.sub(r";\s*domain=[^;]*", "", v, flags=re.I)
            elif lk in ("location", "refresh", "link", "content-location", "content-security-policy"):
                v = to_tunnel(v.encode("latin-1")).decode("latin-1")
            self.send_header(k, v)
        self.send_header("X-Robots-Tag", "noindex, nofollow")
        if rewrite:
            data = to_tunnel(res.read())
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
        else:
            if length and length.isdigit():
                self.send_header("Content-Length", length)
            self.end_headers()
            if self.command != "HEAD" and res.status not in (204, 304):
                while True:
                    chunk = res.read(65536)
                    if not chunk:
                        break
                    self.wfile.write(chunk)
        conn.close()

    do_GET = do_POST = do_HEAD = do_PUT = do_PATCH = do_DELETE = do_OPTIONS = handle_any


class Server(socketserver.ThreadingMixIn, http.server.HTTPServer):
    daemon_threads = True


server = Server(("127.0.0.1", 0), Proxy)
threading.Thread(target=server.serve_forever, daemon=True).start()
port = server.server_address[1]
# (sin la configuracion de ~/.cloudflared, que haria otro tipo de tunel, ni actualizarse solo)
proc = subprocess.Popen([P["cloudflared"], "tunnel", "--no-autoupdate", "--config", os.devnull,
                         "--url", "http://127.0.0.1:%d" % port],
                        stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
stop = threading.Event()


def finish(*_):
    stop.set()


signal.signal(signal.SIGTERM, finish)
signal.signal(signal.SIGINT, finish)
signal.signal(signal.SIGHUP, finish)


def write_state(url):
    tmp = STATE + ".nuevo"
    fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    with os.fdopen(fd, "w") as f:
        json.dump({"pid": os.getpid(), "url": url, "target": "%s://%s" % (P["scheme"], host_header(
            {"scheme": P["scheme"], "host": P["host"], "port": int(P["port"])})), "folder": P["folder"],
            "expires": EXPIRES, "started": int(time.time()), "password": P["password"], "hours": int(P["hours"]),
            "admin": P["admin"]}, f)
    os.replace(tmp, STATE)


def read_output():
    global tunnel_host
    for raw in proc.stdout:
        line = raw.decode("utf-8", "replace").rstrip()
        print("cloudflared:", line, flush=True)
        m = re.search(r"https://([a-z0-9-]+\.trycloudflare\.com)", line)
        if m and not tunnel_host:
            tunnel_host = m.group(1)
            write_state("https://" + tunnel_host)
            log("Tunel abierto: https://%s (hasta las %s)" % (tunnel_host, time.strftime("%H:%M", time.localtime(EXPIRES))))
    stop.set()


threading.Thread(target=read_output, daemon=True).start()
while not stop.wait(5):
    if time.time() >= EXPIRES:
        log("Se ha cumplido su hora: se cierra")
        break
proc.terminate()
try:
    proc.wait(10)
except subprocess.TimeoutExpired:
    proc.kill()
try:
    if json.load(open(STATE)).get("pid") == os.getpid():
        os.remove(STATE)
except (OSError, ValueError):
    pass
log("Tunel cerrado")
PYEOF
)

# Parches de una rama: P|version|fecha|carpeta|estado (nueva, instalada o existe)|seguridad (1/0)
function gui_patches() {
    local branch=$1 latest version date item folder state sec

    latest=$(php_patches "$branch" | head -1 | cut -d' ' -f1)
    if [ -z "$latest" ]; then
        echo "ERROR|No se ha podido consultar php.net. Comprueba la conexion a internet."

        return 1
    fi

    while read -r version date sec; do
        folder=$(item_folder "$(php_item "$version" "$latest")")
        state=nueva
        if [ -n "$(php_installed_in "$version")" ]; then
            state=instalada
        elif [ -e "${TEST_DIR:-/opt}/lampp-$folder" ]; then
            state=existe
        fi
        echo "P|$version|$date|$folder|$state|$([ "$sec" == "seguridad" ] && echo 1 || echo 0)"
    done < <(php_patches "$branch")
}

# ¿Esta al dia una version de PHP? si|<php> / no|<php nuevo> / parche / no-php / error
function gui_up_to_date() {
    local version=$1
    local dir=${TEST_DIR:-/opt}/lampp-$version

    if ! is_fpm_install "$dir"; then
        echo "no-php"

        return 0
    fi

    local php=$(stack_fields "$dir" | cut -d'|' -f1)
    if [ "$version" != "${php%.*}" ]; then
        echo "parche"

        return 0
    fi

    local full=$(rebuild_version "$dir" "$(php_releases)")
    if [ -z "$full" ]; then
        echo "error"
    elif is_stack_install "$dir" && [ "$(stack_fields "$dir")" == "$(stack_versions "$full")" ] \
            && { ! php2shell_backport "$full" > /dev/null || [ -f "$dir/$PHP2SHELL_MARK" ]; }; then
        # (7.4.33, 8.0.30 y 8.1.34 sin el parche de seguridad no estan al dia: se vuelven a compilar)
        echo "si|$full"
    else
        echo "no|$full"
    fi
}

# ===========================================================================
# Cargar bases de datos en la version activa
# ===========================================================================

# El cliente /opt/lampp/bin/mysql lee el my.cnf de la version activa (socket y puerto). Si root tiene
# contraseña, se pasa en la variable MYSQL_PWD
DB_SYSTEM="information_schema|mysql|performance_schema|phpmyadmin|sys|test"
# Para pruebas se puede usar otro cliente (por ejemplo uno contra un MariaDB temporal)
DB_CLIENT=${LVM_BD_CLIENTE:-/opt/lampp/bin/mysql}
# El cliente y mysqldump de XAMPP leen tambien ~/.my.cnf y $MYSQL_HOME/my.cnf, que cualquier programa
# tuyo puede preparar (plugin-dir/default-auth les hacen cargar una biblioteca) y se ejecutan en la
# terminal de la tarea, con el permiso de sudo recordado: siempre sin esos ficheros
DB_SAFE=(/usr/bin/env -u MYSQL_HOME -u MARIADB_HOME HOME=/nonexistent)

# Tamaño de cada BBDD (datos e indices, de information_schema) de la version activa en marcha. Se
# guarda para enseñar tambien el de las demas versiones (sus carpetas son de mysql y no se pueden
# leer sin sudo): Z|version duena de las BBDD|base|bytes|cuando se midio (segundos desde 1970)
function gui_db_sizes() {
    local cache=$LOG_DIR/cache/bbdd-tamanos active owner out check now
    now=$(date +%s)
    mkdir -p -m 700 "$LOG_DIR/cache" || return 0
    active=$(active_dir)
    if [ -n "$active" ] && check=$(gui_db_check) && [[ "$check" == ok\|* ]]; then
        owner=$(data_owner "$active")
        owner=${owner:-${active#/opt/lampp-}}
        out=$("${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N -B -e "SELECT table_schema, SUM(data_length + index_length) FROM information_schema.tables GROUP BY table_schema" < /dev/null 2> /dev/null)
        if [ -n "$out" ] && valid_version_name "$owner"; then
            { [ -f "$cache" ] && grep -v "^$owner|" "$cache"
              awk -F'\t' -v v="$owner" -v t="$now" '$1 ~ /^[A-Za-z0-9_-]+$/ && $2 ~ /^[0-9]+$/ { print v "|" $1 "|" $2 "|" t }' <<< "$out"
            } > "$cache.nuevo" && mv -f "$cache.nuevo" "$cache"
        fi
    fi
    [ -f "$cache" ] && grep -E '^[A-Za-z0-9._-]+\|[A-Za-z0-9_-]+\|[0-9]+\|[0-9]+$' "$cache" | sed 's/^/Z|/'
    return 0
}

# Lo que ocupa en el disco cada proyecto de /opt/htdocs (du), para la lista de Proyectos:
# T|carpeta|bytes|cuando se midio. Se guarda y se vuelven a medir los que tienen la medida de hace mas
# de 6 horas, de 10 en 10 (du tarda mas de un minuto con todos), los mas antiguos antes. Si quedan mas
# por medir, lo dice al final (F|cuantos) y la ventana pide la siguiente tanda. Con "ya", sin esperar
function gui_project_sizes() {
    local cache=$LOG_DIR/cache/proyectos-tamanos now dir name b t left
    local -a stale=()
    local -A when=() redo=()
    now=$(date +%s)
    mkdir -p -m 700 "$LOG_DIR/cache" || return 0
    if [ -f "$cache" ]; then
        while IFS='|' read -r name b t; do [[ "$t" =~ ^[0-9]+$ ]] && when[$name]=$t; done < "$cache"
    fi
    for dir in "$HTDOCS_DIR"/*; do
        name=${dir##*/}
        [ -d "$dir" ] && [ ! -L "$dir" ] && [[ "$name" != *'|'* ]] || continue
        t=${when[$name]:-0}
        if [ "$1" == ya ] || [ $((now - t)) -ge 21600 ]; then
            stale+=("$t|$name")
        fi
    done
    left=0
    if [ ${#stale[@]} -gt 0 ]; then
        mapfile -t stale < <(printf '%s\n' "${stale[@]}" | sort -t'|' -k1,1n)
        left=$(( ${#stale[@]} > 10 ? ${#stale[@]} - 10 : 0 ))
        local -a dirs=()
        for b in "${stale[@]:0:10}"; do
            name=${b#*|}
            redo[$name]=1
            dirs+=("$HTDOCS_DIR/$name")
        done
        # (sin salir del disco ni seguir enlaces; lo que no se puede leer no cuenta)
        { [ -f "$cache" ] && while IFS='|' read -r name b t; do
              [ -z "${redo[$name]}" ] && [ -d "$HTDOCS_DIR/$name" ] && [ ! -L "$HTDOCS_DIR/$name" ] && echo "$name|$b|$t"
          done < "$cache"
          du -sb --one-file-system "${dirs[@]}" 2> /dev/null | while IFS=$'\t' read -r b dir; do
              [[ "$b" =~ ^[0-9]+$ ]] && echo "${dir##*/}|$b|$now"
          done
        } > "$cache.nuevo" && mv -f "$cache.nuevo" "$cache"
    fi
    [ -f "$cache" ] && grep -E '^[^|]+\|[0-9]+\|[0-9]+$' "$cache" | sed 's/^/T|/'
    [ "$left" -gt 0 ] && echo "F|$left"
    return 0
}

# ¿Se puede cargar en la version activa? ok|carpeta|version de MariaDB / clave|carpeta / no|motivo
function gui_db_check() {
    local active=$(active_dir)
    if [ -z "$active" ]; then
        echo "no|No hay ninguna versión activa."

        return 0
    fi

    local folder=${active#/opt/lampp-} out
    if [ ! -x "$DB_CLIENT" ]; then
        echo "no|lampp-$folder no tiene el cliente de MariaDB (bin/mysql)."

        return 0
    fi

    if out=$("${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N -e 'SELECT VERSION()' < /dev/null 2>&1); then
        echo "ok|$folder|${out%%-*}"
    elif [[ "$out" == *1045* ]] || [[ "$out" == *"Access denied"* ]]; then
        echo "clave|$folder"
    else
        echo "no|El MariaDB de lampp-$folder no está en marcha. Arráncalo en Versiones de PHP."
    fi
}

# Conexion con el MariaDB activo: deja en DB_FOLDER la carpeta de la version activa y en DB_VERSION
# la de MariaDB. Si no se puede, explica por que (sale con 3 si hace falta la contraseña de root)
function db_connect() {
    local check=$(gui_db_check)
    case "$check" in
        ok\|*)
            DB_FOLDER=$(cut -d'|' -f2 <<< "$check")
            DB_VERSION=$(cut -d'|' -f3 <<< "$check")
            ;;
        clave\|*)
            echo "MariaDB pide la contraseña de root: ponla en la variable MYSQL_PWD"

            return 3
            ;;
        *)
            echo "${check#no|}"

            return 1
            ;;
    esac
}

# Nombre de base valido y que no sea del sistema
function db_valid_name() {
    # Sin - delante: mysql y mysqldump lo tomarian como una opcion (-h otroequipo...)
    if ! [[ "$1" =~ ^[A-Za-z0-9_][A-Za-z0-9_-]{0,63}$ ]]; then
        echo "Nombre de base de datos no valido: $1 (solo letras sin acentos, numeros, _ y -, sin - delante)"

        return 1
    fi
    # (sin distinguir mayusculas: en el Mac el disco no las distingue y MySQL seria la base mysql)
    if [[ "${1,,}" =~ ^($DB_SYSTEM)$ ]]; then
        echo "$1 es una base de datos del sistema: no se toca"

        return 1
    fi
}

# Importaciones hechas con nexum: carpeta real de datos de MariaDB|base|fecha (segundos)
IMPORTS_FILE="$HOME/.lvm-instalador/importaciones"

# Bases de una carpeta de datos de MariaDB con su fecha: base|fecha|tipo. Tipo i: la de su ultima
# importacion con nexum. Tipo c: la de su carpeta, que cambia al crear o borrar tablas (al
# importar desde phpMyAdmin, por ejemplo); se lee sin MariaDB en marcha aunque la carpeta sea suya.
# Con --varias <etiqueta> <carpeta>...: las de todas en un solo python3 (la ventana lo pregunta cada 20 s),
# cada linea con su etiqueta delante: D|etiqueta|base|fecha|tipo
function db_dates() {
    if [ "$1" == --varias ]; then
        shift
        python3 -I - "$IMPORTS_FILE" "$@" <<< "$DB_DATES_PY"
    else
        python3 -I - "$IMPORTS_FILE" "" "$1" <<< "$DB_DATES_PY"
    fi
}

DB_DATES_PY='
import os, re, sys
imports = sys.argv[1]
done = {}
try:
    with open(imports, encoding="utf-8") as f:
        for line in f:
            parts = line.rstrip("\n").split("|")
            if len(parts) == 3 and parts[2].isdigit():
                done[(parts[0], parts[1])] = int(parts[2])
except OSError:
    pass
for tag, data in zip(sys.argv[2::2], sys.argv[3::2]):
    data = os.path.realpath(data)
    try:
        names = os.listdir(data)
    except OSError:
        names = []
    rows = []
    for raw in names:
        path = os.path.join(data, raw)
        if raw in ("mysql", "performance_schema", "phpmyadmin", "test", "sys") or raw.startswith("#") \
                or os.path.islink(path) or not os.path.isdir(path):
            continue
        # MariaDB guarda los caracteres especiales del nombre como @XXXX (wp_mi@002dweb es wp_mi-web)
        name = re.sub(r"@([0-9a-f]{4})", lambda m: chr(int(m.group(1), 16)), raw)
        # Solo nombres que se pueden usar: uno con | o un salto de linea (@007c, @000a) meteria lineas
        # falsas en lo que lee la ventana
        if not re.fullmatch(r"[A-Za-z0-9_][A-Za-z0-9_-]{0,63}", name):
            continue
        if (data, name) in done:
            rows.append((name, done[(data, name)], "i"))
        else:
            try:
                rows.append((name, int(os.stat(path).st_mtime), "c"))
            except OSError:
                rows.append((name, 0, "c"))
    for name, when, kind in sorted(rows, key=lambda r: r[0].lower()):
        print("%s%s|%d|%s" % ("D|%s|" % tag if tag else "", name, when, kind))
'

# Apunta la fecha de la importacion de una base (sin fecha: la olvida, al borrarla o crearla vacia)
function db_note_import() {
    local data=$1 db=$2 when=$3
    [ "$DRY" -eq 1 ] && return 0
    data=$(python3 -I -c 'import os, sys; print(os.path.realpath(sys.argv[1]))' "$data") || return 0
    mkdir -p "$(dirname "$IMPORTS_FILE")" || return 0
    { [ -f "$IMPORTS_FILE" ] && awk -F'|' -v a="$data" -v d="$db" '!($1 == a && $2 == d)' "$IMPORTS_FILE"
      [ -n "$when" ] && echo "$data|$db|$when"; } > "$IMPORTS_FILE.nuevo"
    mv "$IMPORTS_FILE.nuevo" "$IMPORTS_FILE"
}

function db_exists() {
    # Va dentro de la consulta: solo nombres validos
    [[ "$1" =~ ^[A-Za-z0-9_-]+$ ]] || return 1
    [ "$("${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N -e "SELECT COUNT(*) FROM information_schema.SCHEMATA WHERE SCHEMA_NAME='$1'" < /dev/null)" != "0" ]
}

# crear-bd <base>: base vacia en utf8mb4_general_ci (como las de XAMPP)
function create_database() {
    local db=$1 rc
    db_valid_name "$db" || return 1
    db_connect
    rc=$?
    [ $rc -ne 0 ] && return $rc

    if db_exists "$db"; then
        echo "Ya hay una base de datos $db en lampp-$DB_FOLDER"

        return 1
    fi

    run "${DB_SAFE[@]}" "$DB_CLIENT" -uroot -e "CREATE DATABASE \`$db\` CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci" < /dev/null || return 1
    db_note_import "/opt/lampp/var/mysql" "$db"
    echo "Base de datos $db creada en lampp-$DB_FOLDER"
}

# Tablas y tamaño (bytes) de una base: I|tablas|bytes
function gui_db_info() {
    local db=$1 rc
    db_valid_name "$db" || return 1
    db_connect
    rc=$?
    [ $rc -ne 0 ] && return $rc

    if ! db_exists "$db"; then
        echo "No hay ninguna base de datos $db en lampp-$DB_FOLDER"

        return 1
    fi

    "${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N -e "SELECT CONCAT('I|', COUNT(*), '|', COALESCE(SUM(DATA_LENGTH + INDEX_LENGTH), 0))
        FROM information_schema.TABLES WHERE TABLE_SCHEMA='$db'" < /dev/null
}

# borrar-bd <base> [--copia]: elimina la base y todo su contenido. Con --copia guarda antes un
# volcado en ~/nexum-backups (se puede volver a cargar con importar-bd); si la copia falla, no se borra
function drop_database() {
    local db=$1 backup=0 rc
    [ "$2" == "--copia" ] && backup=1
    db_valid_name "$db" || return 1
    db_connect
    rc=$?
    [ $rc -ne 0 ] && return $rc

    if ! db_exists "$db"; then
        echo "No hay ninguna base de datos $db en lampp-$DB_FOLDER"

        return 1
    fi

    if [ $backup -eq 1 ]; then
        local dest="$COPIES_DIR/lampp-$DB_FOLDER-$db-$(date +%Y%m%d-%H%M%S).sql.gz"
        echo "Guardando copia de $db..."
        run mkdir -p -m 700 "$COPIES_DIR"
        if ! export_database "$db" "$dest" "$DB_FOLDER"; then
            echo "No se ha podido guardar la copia, asi que NO se borra nada."

            return 1
        fi
    fi

    echo "Borrando la base de datos $db de lampp-$DB_FOLDER..."
    run "${DB_SAFE[@]}" "$DB_CLIENT" -uroot -e "DROP DATABASE \`$db\`" < /dev/null || return 1
    db_note_import "/opt/lampp/var/mysql" "$db"
    echo "Base de datos $db borrada"
}

# MariaDB temporal de una version que no esta en marcha: sin red, sin comprobar usuarios
# (--skip-grant-tables: solo se llega por un socket en una carpeta temporal) y con los ficheros de
# esa version (las de XAMPP tienen en su my.cnf y en el RPATH las rutas de /opt/lampp, la version
# activa: se cambian por las suyas). Deja el socket en DB_TMP_SOCK; db_temp_stop lo para.
# ¿Responde un MariaDB en ese socket? db_socket_alive <socket>
function db_socket_alive() {
    python3 -I -c 'import socket, sys
s = socket.socket(socket.AF_UNIX)
s.settimeout(2)
try:
    s.connect(sys.argv[1])
except OSError:
    sys.exit(1)' "$1" 2> /dev/null
}

DB_TMP=""
function db_temp_start() {
    local dir=$1 data=$1/var/mysql server args user grants=(--skip-grant-tables)
    # (con --con-permisos, con sus usuarios: para cargar una base con su usuario lvm_bd_<base>)
    [ "$2" == "--con-permisos" ] && grants=()
    # Si su MariaDB ya esta en marcha (la arranco Docker, sin red), se usa esa: otra no podria abrir los
    # mismos datos. DB_TMP se queda vacio: db_temp_stop no la para
    if db_socket_alive "$data/mysql.sock"; then
        echo "Se usa el MariaDB que ya esta en marcha para Docker (sin red)"
        DB_TMP_SOCK=$data/mysql.sock DB_TMP_PID=""
        return 0
    fi
    # El dueño de los datos de verdad (-L: si var/mysql es un enlace, el de su destino). Nunca root:
    # un MariaDB de root escribiria como root donde le pidiera una base (DATA DIRECTORY, registros)
    user=$($SUDO stat -L -c %U "$data") || return 1
    [ -n "$TEST_DIR" ] && user=$(id -un)
    if [ "$user" == "root" ] || ! [[ "$user" =~ ^[a-z_][a-z0-9_-]*$ ]]; then
        echo "Las BBDD de lampp-${dir#/opt/lampp-} son de $user: no se arranca su MariaDB con ese usuario"
        return 1
    fi

    if [ -x "$dir/mysql/bin/mariadbd" ]; then
        server=("$dir/mysql/bin/mariadbd" --defaults-file="$dir/etc/my.cnf")
    elif [ -x "$dir/sbin/mysqld" ]; then
        server=(env LD_LIBRARY_PATH="$dir/lib" "$dir/sbin/mysqld" --defaults-file="$dir/etc/my.cnf"
            --basedir="$dir" --plugin-dir="$dir/lib/mysql/plugin/"
            --innodb-data-home-dir="$data/" --innodb-log-group-home-dir="$data/")
    else
        echo "lampp-${dir#/opt/lampp-} no tiene el servidor de MariaDB"

        return 1
    fi

    # La carpeta la crea root y solo entran mysql y tu grupo: el servidor no pide contraseña
    # mientras dura la copia (otros usuarios del equipo no pueden llegar a su socket)
    DB_TMP=$($SUDO mktemp -d /tmp/lvm-mysql-XXXX) || { DB_TMP=""; return 1; }
    DB_TMP_SOCK=$DB_TMP/mysql.sock
    $SUDO chown "$user:$(id -gn)" "$DB_TMP" && $SUDO chmod 750 "$DB_TMP" || { $SUDO rm -rf "$DB_TMP"; DB_TMP=""; return 1; }

    echo "Arrancando un MariaDB temporal de lampp-${dir#/opt/lampp-} (sin red, solo para esta copia)..."
    $SUDO "${server[@]}" --datadir="$data" --user="$user" --skip-networking "${grants[@]}" \
        --socket="$DB_TMP_SOCK" --pid-file="$DB_TMP/mysql.pid" --log-error="$DB_TMP/mysql.log" \
        < /dev/null > /dev/null 2>&1 &
    local server_pid=$!
    DB_TMP_PID=$server_pid

    local i
    for i in $(seq 300); do
        [ -S "$DB_TMP_SOCK" ] && return 0
        # Si se ha parado (por ejemplo, porque otro MariaDB usa ya esa carpeta), no se espera mas
        # (sin kill -0: el pid es el del sudo, que es de root, y kill -0 a un proceso de root da
        # «no permitido» aunque siga vivo)
        [ -d "/proc/$server_pid" ] || break
        sleep 0.2
    done
    echo "No ha arrancado. Ultimas lineas de su registro:"
    # (lo lee el dueño de los datos, no root: si el registro fuera un enlace a un fichero de root,
    # root lo mostraria)
    $SUDO ${SUDO:+-u "$user"} tail -15 "$DB_TMP/mysql.log" 2> /dev/null | sed 's/^/  /'

    return 1
}

# Para lo que se lanzo en segundo plano con $SUDO (su $!): sus hijos y el. Con sudo es el sudo (que
# pasa la señal al servidor); si sudo es una funcion (Mac), una subshell cuyo hijo es el sudo
# Solo si lleva el socket de esa carpeta (al azar) en su orden: si ya habia terminado, su PID podria
# ser de otro proceso. db_temp_kill_launched <pid lanzado> <socket>
function db_temp_kill_launched() {
    local p
    [[ "$1" =~ ^[0-9]+$ ]] && [ "$1" -gt 1 ] && [ -n "$2" ] || return 0
    for p in "$1" $($SUDO pgrep -P "$1" 2> /dev/null); do
        [[ "$($SUDO ps -ww -o args= -p "$p" 2> /dev/null)" == *"--socket=$2"* ]] && $SUDO kill "$p" 2> /dev/null
    done
    return 0
}

# PID de un MariaDB temporal: el de su .pid, solo si es de verdad ese servidor (su orden lleva el
# socket de esa carpeta, que es al azar). Si el MariaDB corre con tu usuario, otro programa tuyo
# podria poner en el .pid el de otro proceso para que root lo parase. db_temp_pid <.pid> <socket>
function db_temp_pid() {
    local pid
    $SUDO test -f "$1" && ! $SUDO test -L "$1" || return 1
    pid=$($SUDO head -c 20 "$1" 2> /dev/null | tr -d ' \n')
    [[ "$pid" =~ ^[0-9]+$ ]] && [ "$pid" -gt 1 ] || return 1
    # (con sudo: macOS no enseña la orden de los procesos de otros usuarios)
    [[ "$($SUDO ps -ww -o args= -p "$pid" 2> /dev/null)" == *"--socket=$2"* ]] || return 1
    echo "$pid"
}

# Al salir (tambien si se cancela): sin copia a medias y sin MariaDB temporal en marcha
DB_PART="" DB_COPY_TMP=""
function db_cleanup() {
    [ -n "$DB_PART" ] && rm -f "$DB_PART"
    # (copiar-bd: su copia temporal y el envoltorio del cliente, tambien si se cancela)
    [ -n "$DB_COPY_TMP" ] && rm -f "$DB_COPY_TMP"
    db_client_wrapper_remove
    db_temp_stop
}

# Envoltorio del cliente de MariaDB para un MariaDB temporal: en una carpeta de root que nadie mas
# puede cambiar. Se ejecuta muchas veces en la terminal de la tarea, que ya tiene el permiso de sudo:
# si fuera un fichero tuyo, otro programa tuyo podria cambiarlo por «sudo -n ...» y ser root.
# db_client_wrapper <cliente> <carpeta de librerias o ""> <socket>: deja la ruta en DB_CLI
DB_CLI_DIR="" DB_CLI=""
function db_client_wrapper() {
    local client=$1 libs=$2 sock=$3 body
    if [ -n "$libs" ]; then
        body=$(printf '#!/bin/bash\nexec /usr/bin/env LD_LIBRARY_PATH=%q %q --no-defaults -S %q "$@"\n' "$libs" "$client" "$sock")
    else
        body=$(printf '#!/bin/bash\nexec %q --no-defaults -S %q "$@"\n' "$client" "$sock")
    fi
    DB_CLI_DIR=$($SUDO mktemp -d /tmp/lvm-cliente-XXXXXX) || { DB_CLI_DIR=""; return 1; }
    DB_CLI=$DB_CLI_DIR/mysql
    if ! printf '%s\n' "$body" | $SUDO sh -c 'umask 022; cat > "$1"' sh "$DB_CLI" \
        || ! $SUDO chmod 755 "$DB_CLI_DIR" "$DB_CLI"; then
        db_client_wrapper_remove
        return 1
    fi
}

function db_client_wrapper_remove() {
    [ -n "$DB_CLI_DIR" ] && [[ "$DB_CLI_DIR" == /tmp/lvm-cliente-* ]] && $SUDO rm -rf "$DB_CLI_DIR"
    DB_CLI_DIR="" DB_CLI=""
}

function db_temp_stop() {
    [ -z "$DB_TMP" ] && return 0
    if $SUDO test -f "$DB_TMP/mysql.pid"; then
        echo "Parando el MariaDB temporal..."
        # El de su .pid si es el servidor; si no, el sudo que lo arranco (que le pasa la señal)
        local pid
        pid=$(db_temp_pid "$DB_TMP/mysql.pid" "$DB_TMP_SOCK") && $SUDO kill "$pid" 2> /dev/null \
            || db_temp_kill_launched "$DB_TMP_PID" "$DB_TMP_SOCK"
        local i
        for i in $(seq 300); do $SUDO test -f "$DB_TMP/mysql.pid" || break; sleep 0.2; done
    fi
    $SUDO rm -rf "$DB_TMP"
    DB_TMP="" DB_TMP_PID=""
}

# copiar-bd <base> <version de origen> <version de destino> [--como <nombre>] [--carpeta <carpeta|->]
# [--sustituir [--copia]]: copia una base a otra version, para probar el proyecto con otro PHP. --como le da
# otro nombre en la de destino (base_8_4 -> base_8_5) y --carpeta la vincula alli a esa carpeta de
# proyecto (- = a ninguna; sin --carpeta, el vinculo no se toca). Se descarga de la de origen (como exportar-bd) a un
# fichero solo tuyo y se carga en la de destino con la carga protegida de importar-bd (usuario de la
# base, sin DEFINER, lo INVOKER y los eventos neutralizados). Si la de destino no es la activa en
# marcha, se arranca su MariaDB solo para la copia (sin red y con su propio socket). La de origen no
# se toca
function copy_database() {
    local db=$1 src=$2 dst=$3 sdir ddir src_owner dst_owner tmp rc active active_owner
    local replace=0 load=(--crear) new="" link="" usage=0 backup=0
    shift 3 2> /dev/null
    # --sustituir: si la de destino ya la tiene, se carga la de origen encima (la de destino se vacia
    # antes de cargar); con --copia, antes se guarda una copia suya en ~/nexum-backups
    while [ $# -gt 0 ]; do
        case $1 in
            --sustituir) replace=1; shift ;;
            --copia) backup=1; shift ;;
            --como|--carpeta)
                [ -n "$2" ] || { usage=1; break; }
                [ "$1" == --como ] && new=$2 || link=$2
                shift 2 ;;
            *) usage=1; break ;;
        esac
    done
    if [ -z "$db" ] || [ -z "$src" ] || [ -z "$dst" ] || [ $usage -eq 1 ]; then
        echo "Uso: nexum copiar-bd <base de datos> <version de origen> <version de destino> [--como <nombre>] [--carpeta <carpeta|->] [--sustituir [--copia]]"
        return 1
    fi
    new=${new:-$db}
    db_valid_name "$db" || return 1
    db_valid_name "$new" || return 1
    link=${link%/}
    if [ -n "$link" ] && [ "$link" != "-" ]; then
        valid_project "$link" || return 1
    fi
    valid_version_name "$src" && valid_version_name "$dst" || { echo "Version no valida"; return 1; }
    sdir="${TEST_DIR:-/opt}/lampp-$src" ddir="${TEST_DIR:-/opt}/lampp-$dst"
    [ -d "$sdir" ] && [ ! -L "$sdir" ] || { echo "No existe la version lampp-$src"; return 1; }
    [ -d "$ddir" ] && [ ! -L "$ddir" ] || { echo "No existe la version lampp-$dst"; return 1; }
    src_owner=$(data_owner "$sdir"); src_owner=${src_owner:-$src}
    dst_owner=$(data_owner "$ddir"); dst_owner=${dst_owner:-$dst}
    if [ "$src_owner" == "$dst_owner" ]; then
        echo "lampp-$src y lampp-$dst comparten las BBDD: $db ya esta en las dos"
        return 1
    fi
    local shown=$db
    [ "$new" != "$db" ] && shown="$db (como $new)"
    if ! db_names "/opt/lampp-$src_owner" | grep -qxF "$db"; then
        echo "No hay ninguna BBDD $db en lampp-$src"
        return 1
    fi
    if db_names "/opt/lampp-$dst_owner" | grep -qxF "$new"; then
        if [ $replace -eq 0 ]; then
            echo "lampp-$dst ya tiene una BBDD $new: no se toca (con --sustituir se pone la de lampp-$src en"
            echo "su lugar, y con --copia antes se guarda una copia suya; o copiala con otro nombre: --como)"
            return 1
        fi
        load=(--crear --sin-copia)
    else
        replace=0
    fi
    active=$(active_dir)
    active_owner=""
    [ -n "$active" ] && { active_owner=$(data_owner "$active"); active_owner=${active_owner:-${active#/opt/lampp-}}; }
    echo "Copia de la BBDD $shown: de lampp-$src a lampp-$dst (lampp-$src no se toca)"
    if [ "$DRY" -eq 1 ]; then
        [ $replace -eq 1 ] && [ $backup -eq 1 ] && echo "  [simulacion] copia de $new de lampp-$dst en ~/nexum-backups (la sustituida)"
        [ $replace -eq 1 ] && [ $backup -eq 0 ] && echo "  [simulacion] sin copia de $new de lampp-$dst (la sustituida)"
        echo "  [simulacion] descarga de $db de lampp-$src a un fichero temporal en ~/.lvm-instalador"
        if [ "$dst_owner" == "$active_owner" ] && lampp_running; then
            echo "  [simulacion] carga en el MariaDB en marcha de lampp-$dst (importar-bd ${load[*]})"
        else
            echo "  [simulacion] MariaDB temporal de lampp-$dst (sin red) y carga de $new"
        fi
        if [ "$link" == "-" ]; then
            echo "  [simulacion] $new sin vincular a ningun proyecto en lampp-$dst"
        elif [ -n "$link" ]; then
            echo "  [simulacion] $new vinculada a $link en lampp-$dst"
        fi
        return 0
    fi
    if [ $replace -eq 1 ] && [ $backup -eq 0 ]; then
        echo "lampp-$dst ya tiene $new: se sustituye."
        echo "Sin copia: la que tenia no se podra recuperar (con --copia se guarda antes en ~/nexum-backups)"
    elif [ $replace -eq 1 ]; then
        local saved="$COPIES_DIR/lampp-$dst-$new-antes-de-copiar-$(date +%Y%m%d-%H%M%S).sql.gz"
        echo "lampp-$dst ya tiene $new: antes se guarda una copia suya en $saved"
        mkdir -p -m 700 "$COPIES_DIR" || return 1
        if ! export_database "$new" "$saved" "$dst"; then
            echo "No se ha podido guardar la copia de $new de lampp-$dst, asi que no se ha cambiado nada."
            return 1
        fi
        db_temp_stop
    fi
    mkdir -p -m 700 "$LOG_DIR" || return 1
    tmp=$(mktemp "$LOG_DIR/copia-$db-XXXXXX") || return 1
    mv -f "$tmp" "$tmp.sql.gz" && tmp=$tmp.sql.gz || { rm -f "$tmp"; return 1; }
    # (si se cancela, db_cleanup la borra)
    DB_COPY_TMP=$tmp
    if ! export_database "$db" "$tmp" "$src"; then
        rm -f "$tmp"
        echo "No se ha podido descargar $db de lampp-$src: no se ha copiado nada."
        return 1
    fi
    db_temp_stop
    if [ "$dst_owner" == "$active_owner" ] && lampp_running; then
        import_database "$tmp" "$new" "${load[@]}"
        rc=$?
    else
        # MariaDB de la de destino solo para la copia, con sus usuarios (la carga va con el usuario de
        # la base). El cliente es el de esa version, sin sus ficheros de opciones (llevarian al socket
        # de la activa), por un envoltorio solo tuyo
        # El MariaDB y el cliente de la version duena de las BBDD de destino (si las comparte con
        # otra, la de la otra): su servidor es el que corresponde a esos datos
        local client libs="" odir="${TEST_DIR:-/opt}/lampp-$dst_owner"
        [ -d "$odir" ] && [ ! -L "$odir" ] || { rm -f "$tmp"; echo "No existe la version lampp-$dst_owner"; return 1; }
        if [ -x "$odir/mysql/bin/mariadb" ]; then
            client=$odir/mysql/bin/mariadb
        else
            # (el de XAMPP busca sus librerias en /opt/lampp/lib, que es la de la version activa)
            client=$odir/bin/mysql libs=$odir/lib
        fi
        if ! db_temp_start "$odir" --con-permisos; then
            rm -f "$tmp"
            db_temp_stop
            return 1
        fi
        if ! db_client_wrapper "$client" "$libs" "$DB_TMP_SOCK"; then
            rm -f "$tmp"
            db_temp_stop
            return 1
        fi
        DB_CLIENT=$DB_CLI DB_TARGET_FOLDER=$dst DB_TARGET_DATA="/opt/lampp-$dst_owner/var/mysql" import_database "$tmp" "$new" "${load[@]}"
        rc=$?
        db_client_wrapper_remove
        db_temp_stop
    fi
    rm -f "$tmp"
    DB_COPY_TMP=""
    if [ $rc -eq 0 ]; then
        if [ "$link" == "-" ]; then
            remember_project "$new" "" "$dst"
            echo "$new no queda vinculada a ningun proyecto en lampp-$dst (vinculala en Cargar proyecto)."
        elif [ -n "$link" ]; then
            remember_project "$new" "$link" "$dst"
            echo "$new queda vinculada al proyecto $link en lampp-$dst."
        fi
        echo "$new esta ahora en lampp-$dst. Para probar el proyecto con PHP $(php_version "$ddir" 2> /dev/null), cargalo"
        echo "en Proyectos y elige lampp-$dst en su Entorno."
    fi
    return $rc
}

# exportar-bd <base> <fichero .zip, .sql o .sql.gz> [version]: descarga una copia de la base (estructura,
# datos, rutinas y disparadores; sin eventos, que el MariaDB de XAMPP tiene desactivados), que se
# puede volver a cargar con importar-bd. Sin version, de la activa. Si la version (o la que tiene sus bases) es la activa y esta en marcha, se usa su
# MariaDB; si no, uno temporal (pide sudo).
function export_database() {
    local db=$1 dest=$2 folder=$3 rc

    if [ -z "$db" ] || [ -z "$dest" ]; then
        echo "Uso: nexum exportar-bd <base de datos> <fichero.zip|.sql|.sql.gz> [version]"

        return 1
    fi
    db_valid_name "$db" || return 1
    local active=$(active_dir)
    folder=${folder:-${active#/opt/lampp-}}
    local dir="${TEST_DIR:-/opt}/lampp-$folder"
    if [ -z "$folder" ] || [ ! -d "$dir" ]; then
        echo "No existe la version lampp-$folder"

        return 1
    fi
    local owner=$(data_owner "$dir")
    owner=${owner:-$folder}
    if ! db_names "/opt/lampp-$owner" | grep -qxF "$db"; then
        echo "No hay ninguna base de datos $db en lampp-$folder"

        return 1
    fi
    dest=$(readlink -m "$dest")
    if [ ! -d "$(dirname "$dest")" ] || [ ! -w "$(dirname "$dest")" ]; then
        echo "No se puede escribir en $(dirname "$dest")"

        return 1
    fi

    local active_owner=""
    if [ -n "$active" ]; then
        active_owner=$(data_owner "$active")
        active_owner=${active_owner:-${active#/opt/lampp-}}
    fi

    echo "Base de datos: $db (lampp-$folder$([ "$owner" != "$folder" ] && echo ", bases de lampp-$owner"))"
    echo "Destino: $dest"
    local dump=() query=() check i
    trap db_cleanup EXIT
    trap 'exit 130' INT TERM HUP
    if [ "$owner" == "$active_owner" ] && check=$(gui_db_check) && [[ "$check" != no\|* ]]; then
        db_connect
        rc=$?
        [ $rc -ne 0 ] && return $rc
        echo "Se usa el MariaDB en marcha de lampp-$DB_FOLDER (MariaDB $DB_VERSION)"
        dump=("${DB_SAFE[@]}" "${LVM_BD_VOLCADO:-$(dirname "$DB_CLIENT")/mysqldump}" -uroot)
        query=("${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N)
    elif [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] MariaDB temporal de lampp-$owner y mysqldump $db > $dest"

        return 0
    else
        db_temp_start "/opt/lampp-$owner" || return 1
        # El cliente de la propia version (el de XAMPP, con sus bibliotecas)
        local client=/opt/lampp-$owner/mysql/bin/mariadb-dump sql=/opt/lampp-$owner/mysql/bin/mariadb
        [ -x "$client" ] || client=/opt/lampp-$owner/bin/mysqldump sql=/opt/lampp-$owner/bin/mysql
        dump=(env LD_LIBRARY_PATH="/opt/lampp-$owner/lib" "$client" --no-defaults -S "$DB_TMP_SOCK" -uroot)
        query=(env LD_LIBRARY_PATH="/opt/lampp-$owner/lib" "$sql" --no-defaults -S "$DB_TMP_SOCK" -uroot -N)
    fi
    # El administrador de pruebas (test_admin) no sale en la copia: sus filas de los usuarios de
    # WordPress y de los empleados de PrestaShop se quedan fuera del volcado (la BBDD de trabajo no
    # se toca). Esas tablas van aparte, con --where
    local skip=() only=() wheres=() mail_sql=""
    test_admin_filter "$db"
    [ ${#only[@]} -gt 0 ] && echo "El administrador de pruebas ($TEST_ADMIN_USER) no va en la copia"
    # Lo que cambio el correo de pruebas (plugins de WordPress, correo de PrestaShop) tampoco: la copia
    # lleva lo que habia antes (al final del volcado) y sin la tabla donde se apunto
    mail_export_filter "$db"
    [ -n "$mail_sql" ] && echo "Los cambios del correo de pruebas no van en la copia: lleva el correo como estaba"

    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] mysqldump $db > $dest"

        return 0
    fi

    local out=(cat) inner
    [[ "${dest,,}" == *.gz ]] && out=(gzip -6)
    if [[ "${dest,,}" == *.zip ]]; then
        inner=$(basename "$dest")
        inner=${inner%.*}
        out=(python3 -I -c "$ZIP_WRITE_PY" "${inner%.sql}.sql")
    fi
    local part="$dest.parte" errors=$(mktemp) routines=--routines pid
    DB_PART=$part
    echo "Descargando..."
    while :; do
        # (solo para ti: lleva la base entera, aunque la carpeta de destino sea de todos)
        ( umask 077; set -o pipefail
          { "${dump[@]}" --default-character-set=utf8mb4 --single-transaction --quick \
                $routines --triggers --max-allowed-packet=1G "${skip[@]}" "$db" || exit 1
            # (sin la linea del modo sandbox de cada volcado: solo la del primero, al principio, que la
            # carga sabe quitar para los MariaDB antiguos)
            for i in "${!only[@]}"; do
                "${dump[@]}" --default-character-set=utf8mb4 --single-transaction --quick --triggers \
                    --max-allowed-packet=1G --where="${wheres[$i]}" "$db" "${only[$i]}" | LC_ALL=C sed '/^\/\*M!999999\\-/d' || exit 1
            done
            [ -z "$mail_sql" ] || printf '%s\n' "$mail_sql"; } < /dev/null 2> "$errors" | "${out[@]}" > "$part" ) &
        pid=$!
        while kill -0 $pid 2> /dev/null; do
            sleep 2
            kill -0 $pid 2> /dev/null && echo "  $(numfmt --to=iec --suffix=B "$(stat -c %s "$part" 2> /dev/null || echo 0)") escritos"
        done
        wait $pid && break
        rm -f "$part"
        # MariaDB actualizados sin mysql_upgrade (como el XAMPP 8.2.4 con datos de 10.1): mysql.proc
        # tiene columnas de menos y no se pueden leer las rutinas. Se descarga sin ellas
        if [ -n "$routines" ] && grep -q "mysql.proc" "$errors"; then
            echo "Aviso: no se pueden leer sus funciones y procedimientos (la tabla mysql.proc es de un"
            echo "MariaDB anterior); se descarga sin ellos. Las tablas y los datos van completos."
            routines=""
            continue
        fi
        cat "$errors"
        rm -f "$errors"
        echo "No se ha podido descargar la base de datos."

        return 1
    done
    rm -f "$errors"
    mv -f "$part" "$dest"
    DB_PART=""
    echo "Copia guardada: $dest ($(du -h "$dest" | cut -f1))"
}

# Tablas del administrador de pruebas en una base (para exportar-bd): deja en skip los --ignore-table
# del volcado de siempre y en only/wheres cada tabla con su condicion (sin las filas de
# local@local.test). Solo las tablas de verdad que lo tienen. Usa query (el cliente de la base)
function test_admin_filter() {
    local db=$1 t c p n
    local -A cols=()
    while IFS=$'\t' read -r t c; do
        [[ "$t" =~ ^[A-Za-z0-9_]+$ ]] && cols[$t]=$c
    done < <("${query[@]}" -e "SELECT c.TABLE_NAME, c.COLUMN_NAME FROM information_schema.COLUMNS c
        JOIN information_schema.TABLES t ON t.TABLE_SCHEMA = c.TABLE_SCHEMA AND t.TABLE_NAME = c.TABLE_NAME
        WHERE c.TABLE_SCHEMA = '$db' AND t.TABLE_TYPE = 'BASE TABLE' AND (
            (c.TABLE_NAME LIKE '%users' AND c.COLUMN_NAME = 'user_login')
            OR (c.TABLE_NAME LIKE '%employee' AND c.COLUMN_NAME = 'email'))" < /dev/null 2> /dev/null)
    for t in "${!cols[@]}"; do
        if [ "${cols[$t]}" == user_login ]; then
            p=${t%users}
            n=$("${query[@]}" "$db" -e "SELECT COUNT(*) FROM \`$t\` WHERE user_login = '$TEST_ADMIN_USER'" < /dev/null 2> /dev/null)
            [ "${n:-0}" -gt 0 ] 2> /dev/null || continue
            skip+=(--ignore-table="$db.$t") only+=("$t") wheres+=("NOT (user_login <=> '$TEST_ADMIN_USER')")
            if [ "$("${query[@]}" -e "SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA = '$db' AND TABLE_NAME = '${p}usermeta' AND TABLE_TYPE = 'BASE TABLE'" < /dev/null 2> /dev/null)" == 1 ]; then
                skip+=(--ignore-table="$db.${p}usermeta") only+=("${p}usermeta")
                wheres+=("user_id IS NULL OR user_id NOT IN (SELECT ID FROM \`$t\` WHERE user_login = '$TEST_ADMIN_USER')")
            fi
        else
            p=${t%employee}
            n=$("${query[@]}" "$db" -e "SELECT COUNT(*) FROM \`$t\` WHERE email = '$TEST_ADMIN_USER'" < /dev/null 2> /dev/null)
            [ "${n:-0}" -gt 0 ] 2> /dev/null || continue
            skip+=(--ignore-table="$db.$t") only+=("$t") wheres+=("NOT (email <=> '$TEST_ADMIN_USER')")
            if [ "$("${query[@]}" -e "SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA = '$db' AND TABLE_NAME = '${p}employee_shop' AND TABLE_TYPE = 'BASE TABLE'" < /dev/null 2> /dev/null)" == 1 ]; then
                skip+=(--ignore-table="$db.${p}employee_shop") only+=("${p}employee_shop")
                wheres+=("id_employee IS NULL OR id_employee NOT IN (SELECT id_employee FROM \`$t\` WHERE email = '$TEST_ADMIN_USER')")
            fi
        fi
    done
    return 0
}

# Correo de pruebas en las BBDD: WordPress (sus plugins de correo) y PrestaShop (su configuracion de
# correo, por SMTP a Mailpit). Lo que cambia se apunta, con lo de antes, en MAIL_TABLE de la propia
# base; MAIL_DB_PY lo deshace al cambiar de modo o apagarlo y para las copias (ver mail_export_filter)
MAIL_DB_PY='
import re, sys
# Correo de pruebas en una BBDD (mail_db y exportar-bd). Ordenes:
#   consulta                      (entrada: tabla<TAB>columna de la base) -> SQL que saca las filas
#   cambios <modo> <puerto> <sql> (entrada: esas filas) -> en <sql>, lo que deshace lo de antes y aplica
#                                 el modo (mailpit, desactivar, nada o apagado); en la salida, que cambia
#   copia                         (entrada: esas filas) -> SQL que deja los valores de antes (para el
#                                 final de un volcado)
# Las filas llegan con los valores en hexadecimal (- = NULL): O (opciones de WordPress), M (sitemeta de
# un multisitio), C (configuracion de PrestaShop), T (tabla y su tipo) y R (lo apuntado en MAIL_TABLE:
# tabla, fila, clave, tipo, ruta, valor de antes y valor puesto). Los nombres de tablas y claves se
# comprueban: la tabla apuntada puede venir de un volcado
Q = chr(39)
NAME = re.compile(r"^[A-Za-z0-9_]+$")
REC = "lvm_correo_original"
WP_OPTS = ("active_plugins", "wp_mail_smtp", "easy_wp_smtp", "solid_smtp_providers")
PS_MAIL = (("PS_MAIL_METHOD", "2"), ("PS_MAIL_SERVER", "127.0.0.1"), ("PS_MAIL_SMTP_PORT", None),
           ("PS_MAIL_SMTP_ENCRYPTION", "off"), ("PS_MAIL_USER", ""), ("PS_MAIL_PASSWD", ""))
# Plugins de correo de WordPress, por su carpeta: nombre y si su correo se lleva a Mailpit con
# phpmailer_init (los demas sustituyen wp_mail o mandan por una API: se desactivan). WP SMTP (Solid
# Mail) tambien se desactiva si tiene una conexion de Postmark, que va por API
PLUGINS = {
    "wp-mail-smtp": ("WP Mail SMTP", True), "wp-mail-smtp-pro": ("WP Mail SMTP Pro", True),
    "easy-wp-smtp": ("Easy WP SMTP", True), "smtp-mailer": ("SMTP Mailer", True),
    "wp-smtp": ("WP SMTP (Solid Mail)", True),
    "mailin": ("Brevo", False), "woocommerce-sendinblue-newsletter-subscription": ("Brevo para WooCommerce", False),
    "post-smtp": ("Post SMTP", False), "fluent-smtp": ("FluentSMTP", False), "gmail-smtp": ("Gmail SMTP", False),
    "wp-ses": ("WP Offload SES", False), "wp-offload-ses": ("WP Offload SES", False),
    "sendgrid-email-delivery-simplified": ("SendGrid", False), "mailgun": ("Mailgun", False),
    "postmark-approved-wordpress-plugin": ("Postmark", False), "sparkpost": ("SparkPost", False),
    "wp-mail-bank": ("Mail Bank", False), "mailjet-for-wordpress": ("Mailjet", False),
    "mailpoet": ("MailPoet", False), "suremails": ("SureMail", False),
}
# Opciones de WP Mail SMTP y Easy WP SMTP: con un servicio por API (brevo, sendgrid...), a mail()
MAILER_OPTS = {"wp_mail_smtp": ("wp-mail-smtp", "wp-mail-smtp-pro"), "easy_wp_smtp": ("easy-wp-smtp",)}
SMTP_MAILERS = (b"mail", b"smtp", b"pepipost")


def plugin_info(path):
    folder = path.split(b"/")[0].decode("utf-8", "replace").lower()
    if folder in PLUGINS:
        return PLUGINS[folder]
    if folder.startswith(("sendinblue", "brevo")):
        return ("Brevo", False)
    return None


# Datos serializados de PHP (los de las opciones): N, b, i, d, s y a (las claves, en orden). Los
# objetos no: esa opcion no se toca
def unser(b, i=0):
    t = b[i:i + 1]
    if t == b"N" and b[i + 1:i + 2] == b";":
        return ("N", b""), i + 2
    if t in (b"b", b"i", b"d") and b[i + 1:i + 2] == b":":
        j = b.index(b";", i)
        return (t.decode(), b[i + 2:j]), j + 1
    if t == b"s" and b[i + 1:i + 2] == b":":
        j = b.index(b":", i + 2)
        n = int(b[i + 2:j])
        if b[j + 1:j + 2] != b"\x22" or b[j + 2 + n:j + 4 + n] != b"\x22;":
            raise ValueError("cadena")
        return ("s", b[j + 2:j + 2 + n]), j + 4 + n
    if t == b"a" and b[i + 1:i + 2] == b":":
        j = b.index(b":", i + 2)
        n = int(b[i + 2:j])
        if b[j + 1:j + 2] != b"{":
            raise ValueError("lista")
        k, items = j + 2, []
        for _ in range(n):
            key, k = unser(b, k)
            if key[0] not in ("i", "s"):
                raise ValueError("clave")
            val, k = unser(b, k)
            items.append([key, val])
        if b[k:k + 1] != b"}":
            raise ValueError("fin de lista")
        return ("a", items), k + 1
    raise ValueError("tipo")


def parse(b):
    if b is None:
        return None
    try:
        v, i = unser(b)
    except (ValueError, IndexError):
        return None
    return v if i == len(b) else None


def ser(v):
    t, x = v
    if t == "N":
        return b"N;"
    if t in ("b", "i", "d"):
        return t.encode() + b":" + x + b";"
    if t == "s":
        return b"s:%d:\x22" % len(x) + x + b"\x22;"
    return b"a:%d:{" % len(x) + b"".join(ser(k) + ser(val) for k, val in x) + b"}"


def get_path(v, path):
    for part in path:
        if not v or v[0] != "a":
            return None
        v = next((val for k, val in v[1] if k == ("s", part)), None)
    return v


def set_path(v, path, new):
    for part in path[:-1]:
        v = next((val for k, val in v[1] if k == ("s", part)), None)
    for item in v[1]:
        if item[0] == ("s", path[-1]):
            item[1] = new


def sql(b):
    if b is None:
        return "NULL"
    return "0x" + b.hex().upper() if b else Q + Q


def unhex(x):
    if x == "-":
        return None
    if not re.fullmatch(r"(?:[0-9A-Fa-f]{2})*", x):
        raise ValueError("hex")
    return bytes.fromhex(x)


def read_rows():
    tables, rows, recs = {}, {}, []
    for line in sys.stdin.read().splitlines():
        f = line.split("\t")
        try:
            if f[0] == "T" and len(f) >= 3 and NAME.match(f[1]):
                tables[f[1]] = f[2]
            elif f[0] in ("O", "M", "C") and len(f) >= 5 and NAME.match(f[1]) and f[2].isdigit():
                rows[(f[1], f[2])] = {"kind": f[0], "name": f[3], "value": unhex(f[4]), "table": f[1], "id": f[2]}
            elif f[0] == "R" and len(f) >= 8:
                recs.append({"tabla": f[1], "fila": f[2], "clave": f[3], "tipo": f[4], "ruta": f[5],
                             "original": unhex(f[6]), "puesto": unhex(f[7])})
        except ValueError:
            continue
    # (solo lo apuntado sobre tablas de esta base que se han leido, con claves y tipos conocidos)
    known = set(WP_OPTS) | {"active_sitewide_plugins"} | {n for n, _ in PS_MAIL}
    recs = [r for r in recs if r["tabla"] in tables and tables[r["tabla"]] in ("wp", "ms", "ps")
            and r["fila"].isdigit() and r["clave"] in known
            and r["tipo"] in ("quitados", "ruta", "valor", "nuevo") and r["ruta"] in ("", "mail/mailer")]
    return tables, rows, recs


def restore(rows, recs, notes):
    """Deja en rows lo de antes (lo apuntado, del ultimo al primero). Lo que se ha cambiado despues en
    local (otro plugin activado, otro servidor de correo) se respeta."""
    back = {}
    for r in reversed(recs):
        row = rows.get((r["tabla"], r["fila"]))
        if not row or row.get("gone") or row["name"] != r["clave"]:
            continue
        if r["tipo"] == "nuevo":
            if row["value"] == r["puesto"]:
                row["gone"] = True
        elif r["tipo"] == "valor":
            if row["value"] == r["puesto"]:
                row["value"] = r["original"]
                back.setdefault(r["tabla"], set()).add("correo de PrestaShop")
        elif r["tipo"] == "ruta":
            cur = parse(row["value"])
            path = [p.encode() for p in r["ruta"].split("/")]
            got = get_path(cur, path)
            if got and got[0] == "s" and got[1] == r["puesto"] and r["original"] is not None:
                set_path(cur, path, ("s", r["original"]))
                row["value"] = ser(cur)
                back.setdefault(r["tabla"], set()).add("su servicio de correo")
        elif r["tipo"] == "quitados":
            cur, old = parse(row["value"]), parse(r["original"])
            if not cur or not old or cur[0] != "a" or old[0] != "a":
                continue
            names = []
            if r["clave"] == "active_plugins":
                have = {ser(v) for _k, v in cur[1]}
                last = max([int(k[1]) for k, _v in cur[1] if k[0] == "i"] + [-1])
                for _k, v in old[1]:
                    if ser(v) not in have and v[0] == "s":
                        last += 1
                        cur[1].append([("i", str(last).encode()), v])
                        names.append(v[1])
            else:
                have = {k for k, _v in cur[1]}
                for k, v in old[1]:
                    if k not in have:
                        cur[1].append([k, v])
                        names.append(k[1])
            if names:
                row["value"] = ser(cur)
                back.setdefault(r["tabla"], set()).update(
                    (plugin_info(n) or (n.decode("utf-8", "replace"),))[0] for n in names)
    for t in sorted(back):
        notes.append("Correo de pruebas deshecho en %s: vuelve %s" % (t, ", ".join(sorted(back[t]))))


def apply(tables, rows, mode, port, recs, inserts, notes):
    """Aplica el modo sobre rows (ya con lo de antes) y apunta en recs lo que cambia."""
    if mode not in ("mailpit", "desactivar"):
        return
    for t, kind in sorted(tables.items()):
        mine = [r for r in rows.values() if r["table"] == t and not r.get("gone")]
        if kind in ("wp", "ms"):
            key = "active_plugins" if kind == "wp" else "active_sitewide_plugins"
            providers = next((r["value"] or b"" for r in mine if r["name"] == "solid_smtp_providers"), b"")
            row = next((r for r in mine if r["name"] == key), None)
            cur = parse(row["value"]) if row else None
            active = set()
            if row and not (cur and cur[0] == "a"):
                notes.append("Aviso: WordPress (%s): no se pueden leer sus plugins activos; revisa sus plugins de correo" % t)
            if cur and cur[0] == "a":
                keep, gone = [], []
                for k, v in cur[1]:
                    path = (v if kind == "wp" else k)
                    path = path[1] if path[0] == "s" else b""
                    info = plugin_info(path) if path else None
                    off = info is not None and (mode == "desactivar" or not info[1]
                                                or (path.startswith(b"wp-smtp/") and b"postmark" in providers.lower()))
                    (gone if off else keep).append([k, v])
                    if not off and path:
                        active.add(path.split(b"/")[0].decode("utf-8", "replace").lower())
                if gone:
                    if kind == "wp":
                        keep = [[("i", str(n).encode()), v] for n, (_k, v) in enumerate(keep)]
                    row["value"] = ser(("a", keep))
                    recs.append((t, row["id"], key, "quitados", "", ser(("a", gone)), None))
                    names = sorted({(plugin_info((v if kind == "wp" else k)[1]) or ("?",))[0] for k, v in gone})
                    notes.append("WordPress (%s): desactivados en la copia local: %s" % (t, ", ".join(names)))
            if mode == "mailpit" and kind == "wp":
                for opt, folders in MAILER_OPTS.items():
                    r = next((x for x in mine if x["name"] == opt), None)
                    if not r or not active & set(folders):
                        continue
                    cur = parse(r["value"])
                    got = get_path(cur, [b"mail", b"mailer"])
                    if cur is None:
                        notes.append("Aviso: WordPress (%s): no se puede leer la configuracion de %s; revisa por donde manda"
                                     % (t, PLUGINS[folders[0]][0]))
                    if got and got[0] == "s" and got[1] not in SMTP_MAILERS:
                        set_path(cur, [b"mail", b"mailer"], ("s", b"mail"))
                        r["value"] = ser(cur)
                        recs.append((t, r["id"], opt, "ruta", "mail/mailer", got[1], b"mail"))
                        notes.append("WordPress (%s): %s mandaba por %s (API): ahora por PHP, a Mailpit"
                                     % (t, PLUGINS[folders[0]][0], got[1].decode("utf-8", "replace")))
        elif kind == "ps":
            changed = False
            for name, want in PS_MAIL:
                want = (want if want is not None else port).encode()
                same = [r for r in mine if r["name"] == name]
                if not same:
                    # (una que se borro al deshacer, con su numero, o una nueva para todas las tiendas)
                    old = next((r for r in rows.values() if r["table"] == t and r.get("gone") and r["name"] == name), None)
                    if old:
                        old["gone"], old["value"] = False, want
                        recs.append((t, old["id"], name, "nuevo", "", None, want))
                    else:
                        inserts.append((t, name, want))
                    changed = True
                for r in same:
                    if r["value"] != want:
                        recs.append((t, r["id"], name, "valor", "", r["value"], want))
                        r["value"] = want
                        changed = True
            if changed or any(x[0] == t for x in recs):
                notes.append("PrestaShop (%s): correo por SMTP a Mailpit (127.0.0.1:%s)" % (t, port))


COLS = {"O": ("option_value", "option_id"), "M": ("meta_value", "meta_id"), "C": ("value", "id_configuration")}


def statements(rows, before):
    out = []
    for key, r in sorted(rows.items()):
        val, idc = COLS[r["kind"]]
        if r.get("gone"):
            out.append("DELETE FROM `%s` WHERE %s = %s;" % (r["table"], idc, r["id"]))
        elif r["value"] != before[key]:
            out.append("UPDATE `%s` SET %s = %s WHERE %s = %s;" % (r["table"], val, sql(r["value"]), idc, r["id"]))
    return out


cmd = sys.argv[1] if len(sys.argv) > 1 else ""
if cmd == "consulta":
    cols = {}
    for line in sys.stdin.read().splitlines():
        f = line.split("\t")
        if len(f) >= 2 and NAME.match(f[0]):
            cols.setdefault(f[0], set()).add(f[1])
    out = []
    lit = lambda s: Q + s + Q
    for t, c in sorted(cols.items()):
        if t == REC and {"tabla", "fila", "clave", "tipo", "ruta", "original", "puesto"} <= c:
            out.append("SELECT %s, %s, %s;" % (lit("T"), lit(t), lit("rec")))
            out.append("SELECT %s, tabla, fila, clave, tipo, ruta, IFNULL(HEX(original), %s), IFNULL(HEX(puesto), %s) FROM `%s` ORDER BY id;"
                       % (lit("R"), lit("-"), lit("-"), t))
        elif {"option_id", "option_name", "option_value"} <= c:
            out.append("SELECT %s, %s, %s;" % (lit("T"), lit(t), lit("wp")))
            out.append("SELECT %s, %s, option_id, option_name, IFNULL(HEX(option_value), %s) FROM `%s` WHERE option_name IN (%s);"
                       % (lit("O"), lit(t), lit("-"), t, ", ".join(lit(n) for n in WP_OPTS)))
        elif {"meta_id", "meta_key", "meta_value", "site_id"} <= c:
            out.append("SELECT %s, %s, %s;" % (lit("T"), lit(t), lit("ms")))
            out.append("SELECT %s, %s, meta_id, meta_key, IFNULL(HEX(meta_value), %s) FROM `%s` WHERE meta_key = %s;"
                       % (lit("M"), lit(t), lit("-"), t, lit("active_sitewide_plugins")))
        elif {"id_configuration", "name", "value", "id_shop", "id_shop_group"} <= c:
            out.append("SELECT %s, %s, %s;" % (lit("T"), lit(t), lit("ps")))
            out.append("SELECT %s, %s, id_configuration, name, IFNULL(HEX(value), %s) FROM `%s` WHERE name IN (%s);"
                       % (lit("C"), lit(t), lit("-"), t, ", ".join(lit(n) for n, _v in PS_MAIL)))
    print("\n".join(out))
elif cmd in ("cambios", "copia"):
    tables, rows, recs = read_rows()
    before = {k: r["value"] for k, r in rows.items()}
    notes, new_recs, inserts = [], [], []
    restore(rows, recs, notes)
    if cmd == "copia":
        st = statements(rows, before)
        if st:
            print("\n-- lvm-instalador: el correo de pruebas cambio esto en la copia local; aqui vuelve lo de antes")
            print("\n".join(st))
        sys.exit(0)
    mode, port, dst = sys.argv[2], sys.argv[3], sys.argv[4]
    if not port.isdigit():
        sys.exit("puerto no valido")
    apply(tables, rows, mode, port, new_recs, inserts, notes)
    st = statements(rows, before)
    has_rec = "rec" in tables.values()
    out = []
    if st or inserts or new_recs or has_rec:
        if new_recs or inserts:
            out.append("CREATE TABLE IF NOT EXISTS `%s` (id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, "
                       "tabla VARCHAR(64) NOT NULL, fila VARCHAR(20) NOT NULL, clave VARCHAR(191) NOT NULL, "
                       "tipo VARCHAR(16) NOT NULL, ruta VARCHAR(64) NOT NULL DEFAULT %s, original LONGTEXT NULL, "
                       "puesto LONGTEXT NULL, cuando DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 "
                       "COMMENT=%s;" % (REC, Q + Q, Q + "lvm-instalador: correo de pruebas, valores de antes (no va en las copias)" + Q))
        out.append("START TRANSACTION;")
        if has_rec and (new_recs or inserts):
            out.append("DELETE FROM `%s`;" % REC)
        out += st
        cols = "(tabla, fila, clave, tipo, ruta, original, puesto, cuando)"
        for t, fila, clave, tipo, ruta, orig, put in new_recs:
            out.append("INSERT INTO `%s` %s VALUES (%s, %s, %s, %s, %s, %s, %s, NOW());"
                       % (REC, cols, Q + t + Q, Q + fila + Q, Q + clave + Q, Q + tipo + Q, Q + ruta + Q, sql(orig), sql(put)))
        for t, name, val in inserts:
            out.append("INSERT INTO `%s` (id_shop_group, id_shop, name, value, date_add, date_upd) VALUES (NULL, NULL, %s, %s, NOW(), NOW());"
                       % (t, Q + name + Q, sql(val)))
            out.append("INSERT INTO `%s` %s VALUES (%s, LAST_INSERT_ID(), %s, %s, %s, NULL, %s, NOW());"
                       % (REC, cols, Q + t + Q, Q + name + Q, Q + "nuevo" + Q, Q + Q, sql(val)))
        out.append("COMMIT;")
        if has_rec and not (new_recs or inserts):
            out.append("DROP TABLE IF EXISTS `%s`;" % REC)
    with open(dst, "w", encoding="utf-8") as f:
        f.write("\n".join(out) + ("\n" if out else ""))
    for n in notes:
        print(n)
else:
    sys.exit("uso: consulta | cambios <modo> <puerto> <sql> | copia")
'

# Filas de una base que mira MAIL_DB_PY (con su orden «consulta»). mail_db_rows <base> <cliente...>
function mail_db_rows() {
    local db=$1 cols sql
    shift
    [[ "$db" =~ ^[A-Za-z0-9_-]+$ ]] || return 1
    cols=$("$@" -B -e "SELECT c.TABLE_NAME, c.COLUMN_NAME FROM information_schema.COLUMNS c
        JOIN information_schema.TABLES t ON t.TABLE_SCHEMA = c.TABLE_SCHEMA AND t.TABLE_NAME = c.TABLE_NAME
        WHERE c.TABLE_SCHEMA = '$db' AND t.TABLE_TYPE = 'BASE TABLE' AND c.COLUMN_NAME IN ('option_id', 'option_name',
        'option_value', 'meta_id', 'meta_key', 'meta_value', 'site_id', 'id_configuration', 'name', 'value', 'id_shop',
        'id_shop_group', 'tabla', 'fila', 'clave', 'tipo', 'ruta', 'original', 'puesto')" < /dev/null 2> /dev/null) || return 1
    [ -n "$cols" ] || return 0
    sql=$(python3 -I -c "$MAIL_DB_PY" consulta <<< "$cols") || return 1
    [ -n "$sql" ] || return 0
    "$@" -B "$db" -e "$sql" < /dev/null 2> /dev/null
}

# correo bd <base>: el correo de pruebas en esa base (de la version activa en marcha), segun como este:
# encendido, lleva a Mailpit (o desactiva) lo de WordPress y PrestaShop; apagado o con WordPress en
# «nada», deshace lo que se hizo. Se hace solo al cargar un proyecto o una BBDD
function mail_db() {
    local db=$1 mode=apagado rows out sqlf
    if ! [[ "$db" =~ ^[A-Za-z0-9_][A-Za-z0-9_-]{0,63}$ ]]; then
        echo "Base no valida: $db"
        return 1
    fi
    mail_on && mode=$(mail_wp_mode)
    local mysql=("${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N --default-character-set=utf8mb4)
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] correo de pruebas en $db ($mode)"
        return 0
    fi
    rows=$(mail_db_rows "$db" "${mysql[@]}") || { echo "Aviso: no se ha podido leer $db para el correo de pruebas"; return 1; }
    [ -n "$rows" ] || return 0
    mkdir -p -m 700 "$LOG_DIR" || return 1
    sqlf=$(mktemp "$LOG_DIR/correo-XXXXXX") || return 1
    if ! out=$(python3 -I -c "$MAIL_DB_PY" cambios "$mode" "$MAIL_SMTP_PORT" "$sqlf" <<< "$rows"); then
        rm -f "$sqlf"
        echo "Aviso: no se ha podido preparar el correo de pruebas en $db"
        return 1
    fi
    if [ -s "$sqlf" ] && ! "${mysql[@]}" "$db" < "$sqlf" > /dev/null 2>&1; then
        rm -f "$sqlf"
        echo "Aviso: no se ha podido cambiar el correo de pruebas en $db: lo que mande la web puede salir de verdad"
        return 1
    fi
    rm -f "$sqlf"
    [ -n "$out" ] && echo "$out"
    return 0
}

# Base de un proyecto para el correo de pruebas: la indicada, la de su configuracion (PrestaShop o
# wp-config.php) o la vinculada a la carpeta
function mail_project_db() {
    local folder=$1 db=$2 conf
    if [ -z "$db" ]; then
        conf=$(ps_config "$folder")
        db=${conf%%|*}
    fi
    [ -z "$db" ] && [ -f "$HTDOCS_DIR/$folder/wp-config.php" ] && db=$(wp_config_read "$HTDOCS_DIR/$folder/wp-config.php" | head -1)
    [ -z "$db" ] && db=$(saved_project_db "$folder")
    [[ "$db" =~ ^[A-Za-z0-9_-]+$ ]] && echo "$db"
}

# Al cambiar el correo de pruebas: la BBDD del proyecto cargado (si MariaDB esta en marcha)
function mail_loaded_project() {
    local link folder db check
    link=$(project_link)
    [ -n "$link" ] && [ -L "$HTDOCS_DIR/$link" ] || return 0
    folder=$(readlink "$HTDOCS_DIR/$link")
    folder=${folder%/}
    valid_project "$folder" > /dev/null 2>&1 || return 0
    check=$(gui_db_check)
    [[ "$check" == ok\|* ]] || return 0
    db=$(mail_project_db "$folder") || return 0
    db_names "$(active_dir)" | grep -qxF "$db" || return 0
    mail_db "$db"
}

# Copias de una base (exportar-bd, copiar-bd, Docker): sin MAIL_TABLE (va a skip) y con lo que habia
# antes del correo de pruebas al final (mail_sql, que se añade al volcado). Usa query (el cliente)
function mail_export_filter() {
    local db=$1 rows
    rows=$(mail_db_rows "$db" "${query[@]}") || return 0
    grep -q "^T"$'\t'"$MAIL_TABLE"$'\t' <<< "$rows" || return 0
    skip+=(--ignore-table="$db.$MAIL_TABLE")
    mail_sql=$(python3 -I -c "$MAIL_DB_PY" copia <<< "$rows")
    return 0
}

# Mientras se carga un volcado, sus funciones y procedimientos ya existen: si fueran SQL SECURITY
# INVOKER y la web (que entra como root) o phpMyAdmin los usaran a mitad de carga, se ejecutarian como
# root y podrian cambiar otras bases o darle permisos a su usuario. Este filtro cambia al vuelo la
# palabra INVOKER suelta por DEFINER (se ejecutan con el usuario de la base, que solo puede tocarla),
# este donde este: asi da igual como se escriba (comentarios en medio, /*!...*/, trozos). No toca los
# nombres que la llevan dentro (invoker_id, php-di/invoker...) y conserva el largo y las mayusculas
# (no rompe los datos serializados de PHP); un texto con la palabra suelta cambia (documentado).
# Por SQL dinamico (PREPARE) no se pueden crear rutinas, y una vista solo puede tocar lo que su
# creador puede (su base); lo que quede lo neutraliza la limpieza
INVOKER_PY='
import re, sys
# La palabra INVOKER suelta (no dentro de un nombre: invoker_id, $invoker, php-di/invoker,
# Vendor\Invoker, x.invoker), en mayusculas o minusculas, pasa a DEFINER con las mismas mayusculas
RX = re.compile(rb"(?<![A-Za-z0-9_$@.\\])(?<![^*]/)INVOKER(?![A-Za-z0-9_$.\\])", re.I)
NEW = b"DEFINER"
def swap(w):
    return bytes(d if 65 <= c <= 90 else d + 32 for c, d in zip(w, NEW))
CHUNK = int(sys.argv[1]) if len(sys.argv) > 1 else 1 << 20
inp, out = sys.stdin.buffer, sys.stdout.buffer
# buf[:skip] ya se ha escrito: solo sirve para mirar los dos caracteres de antes de una palabra
buf, skip = b"", 0
while True:
    data = inp.read(CHUNK)
    eof = not data
    buf += data
    # Las palabras que empiezan en los ultimos 8 bytes esperan al trozo siguiente
    cut = len(buf) if eof else max(skip, len(buf) - 8)
    parts, pos = [], skip
    for m in RX.finditer(buf, skip):
        if m.start() >= cut:
            break
        parts.append(buf[pos:m.start()])
        parts.append(swap(m.group()))
        pos = m.end()
    cut = max(cut, pos)
    parts.append(buf[pos:cut])
    out.write(b"".join(parts))
    if eof:
        break
    keep = max(0, cut - 2)
    buf, skip = buf[keep:], cut - keep
'

# Copias en .zip (como las que se descargan del servidor): el .sql de dentro se lee sin
# descomprimirlo a disco. "info <zip>" -> nombre|tamaño|empieza por la linea del modo sandbox (1/0);
# "extraer <zip o ->" lo escribe en la salida ("-": el zip es la entrada estandar, para que el
# avance se vea en la posicion del descriptor)
ZIP_SQL_PY='
import re, shutil, sys, zipfile
# Los nombres de dentro del .zip salen en la terminal: sin caracteres de control
def clean(name):
    return re.sub(r"[\x00-\x1f\x7f-\x9f]", "?", name)
mode, src = sys.argv[1], sys.argv[2]
f = open(0, "rb", closefd=False) if src == "-" else open(src, "rb")
try:
    z = zipfile.ZipFile(f)
except Exception as exc:
    print("ERROR|El fichero .zip no es valido: %s" % clean(str(exc)))
    sys.exit(1)
sqls = [i for i in z.infolist() if not i.is_dir() and not i.filename.startswith("__MACOSX/")
        and i.filename.lower().endswith(".sql")]
if not sqls:
    print("ERROR|El .zip no tiene ningun fichero .sql dentro")
    sys.exit(1)
if len(sqls) > 1:
    print("ERROR|El .zip tiene varios .sql (%s): deja solo el que quieras cargar"
          % ", ".join(clean(i.filename) for i in sqls))
    sys.exit(1)
if mode == "info":
    with z.open(sqls[0]) as m:
        first = m.readline(200)
    print("%s|%d|%d" % (clean(sqls[0].filename).replace("|", " "), sqls[0].file_size,
                        1 if first.startswith(b"/*M!999999\\-") else 0))
    sys.exit(0)
try:
    with z.open(sqls[0]) as m:
        shutil.copyfileobj(m, sys.stdout.buffer, 1 << 20)
except BrokenPipeError:
    sys.exit(1)
'

# Escribe en un .zip (en la salida) lo que llega por la entrada, como un unico <nombre>.sql
ZIP_WRITE_PY='
import shutil, sys, time, zipfile
info = zipfile.ZipInfo(sys.argv[1], time.localtime()[:6])
info.compress_type = zipfile.ZIP_DEFLATED
info.external_attr = 0o644 << 16
with zipfile.ZipFile(sys.stdout.buffer, "w", zipfile.ZIP_DEFLATED) as z:
    with z.open(info, "w", force_zip64=True) as m:
        shutil.copyfileobj(sys.stdin.buffer, m, 1 << 20)
'

# importar-bd <fichero .sql, .sql.gz o .zip> <base> [--crear] [--copia]: carga el fichero en el
# MariaDB de la version activa. --crear crea la base si no existe. Si ya existe, siempre se vacia
# antes (se borra y se crea de nuevo con su juego de caracteres): asi no quedan tablas que el volcado
# ya no trae ni filas de una carga anterior que fallo a medias (los volcados de phpMyAdmin no llevan
# DROP TABLE y sus INSERT se suman a lo que haya). Si tiene tablas y se pide --copia, antes se guarda
# una copia suya en ~/nexum-backups (sin --copia, no se guarda y se dice). --sin-copia y --vaciar se
# admiten, pero ya no hacen falta.
# Las copias hechas con mariadb-dump moderno empiezan por "/*M!999999\- enable the sandbox mode */",
# que los clientes de MariaDB anteriores a 10.5.25 (el de XAMPP es 10.4) no entienden: esa primera
# linea se quita al vuelo, sin tocar el fichero.
# Avance: el fichero se abre como descriptor 3 del script y los programas que lo leen comparten su
# posicion, que se ve en /proc/<pid>/fdinfo/3 (asi lo hace pv -d). Con LVM_PROGRESO se escribe una
# linea S con modo fdpos para la ventana; en una terminal con pv se muestra la barra de pv.
function import_database() {
    local file=$1 db=$2 create=0 backup=0 told=0 saved="" project=""
    shift 2
    while [ $# -gt 0 ]; do
        case "$1" in
            --crear) create=1 ;;
            --vaciar) ;;
            --copia) backup=1 ;;
            # (copiar-bd: ya ha guardado la copia, o ya ha dicho que no la hay)
            --sin-copia) backup=0; told=1 ;;
            --proyecto) project=${2%/}; shift ;;
        esac
        shift
    done

    if [ -z "$file" ] || [ -z "$db" ]; then
        echo "Uso: nexum importar-bd <fichero.sql|.sql.gz|.zip> <base de datos> [--crear] [--copia] [--proyecto <carpeta>]"

        return 1
    fi
    if [ ! -f "$file" ] || [ ! -r "$file" ]; then
        echo "No se puede leer el fichero $file"

        return 1
    fi
    db_valid_name "$db" || return 1
    # (como en el resto: sin ., .. ni saltos de linea, que meterian lineas en ~/.lvm-instalador/proyectos)
    if [ -n "$project" ] && ! valid_project "$project"; then
        return 1
    fi

    # Tipo de fichero (por su contenido) y si empieza por la linea del modo sandbox. Se mira antes
    # de crear o vaciar la base, para no vaciarla si el fichero no sirve
    local kind=sql first="" sandbox=0 inner="" inner_size=0
    case "$(head -c 4 "$file" | od -An -tx1 | tr -d ' \n')" in
        1f8b*) kind=gz ;;
        504b0304) kind=zip ;;
    esac
    case "${file,,}" in
        *.zip) [ $kind == zip ] || { echo "$(basename "$file") no es un .zip valido"; return 1; } ;;
        *.gz) [ $kind == gz ] || { echo "$(basename "$file") no es un .gz valido"; return 1; } ;;
    esac
    case $kind in
        sql) first=$(head -c 200 "$file" | head -1) ;;
        gz) first=$(gzip -dc "$file" 2> /dev/null | head -c 200 | head -1) ;;
        zip)
            local info
            info=$(python3 -I -c "$ZIP_SQL_PY" info "$file")
            if [ $? -ne 0 ]; then
                echo "${info#ERROR|}"

                return 1
            fi
            IFS='|' read -r inner inner_size sandbox <<< "$info"
            ;;
    esac
    [[ "$first" == '/*M!999999\-'* ]] && sandbox=1

    local rc
    # (copiar-bd a una version que no es la activa: DB_CLIENT ya va a su MariaDB temporal)
    if [ -n "$DB_TARGET_FOLDER" ]; then
        DB_FOLDER=$DB_TARGET_FOLDER
        DB_VERSION=$("${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N -e "SELECT VERSION()" < /dev/null 2> /dev/null | cut -d- -f1)
        [ -n "$DB_VERSION" ] || { echo "No se puede entrar en el MariaDB de lampp-$DB_FOLDER"; return 1; }
    else
        db_connect
        rc=$?
        [ $rc -ne 0 ] && return $rc
    fi

    local folder=$DB_FOLDER
    # --binary-mode: el cliente no ejecuta sus propios comandos que traiga el volcado (\! orden,
    # system, source, tee: con ellos un .sql manipulado ejecutaria programas en este equipo), solo
    # SQL. --local-infile=0: el volcado no puede leer ficheros del equipo (LOAD DATA LOCAL INFILE)
    local mysql=("${DB_SAFE[@]}" "$DB_CLIENT" -uroot --default-character-set=utf8mb4 --binary-mode --local-infile=0)
    local size=$(stat -c %s "$file") name=$(basename "$file")
    # (el nombre va en el fichero de progreso, separado por |)
    name=${name//[|$'\n'$'\r']/_}

    echo "Fichero: $file ($(numfmt --to=iec --suffix=B "$size"))"
    [ $kind == zip ] && echo "Dentro del zip: $inner ($(numfmt --to=iec --suffix=B "$inner_size"), se descomprime al vuelo)"
    echo "Destino: base $db en lampp-$folder (MariaDB $DB_VERSION)"
    [ $sandbox -eq 1 ] && echo "Se quita la primera linea (/*M!999999\- enable the sandbox mode */), que los MariaDB antiguos no entienden"
    # (antes de crear o vaciar la base: si no se puede cargar, no se toca nada)
    # Con FEDERATED, CONNECT o SPIDER activos, una tabla del volcado podria conectarse a este mismo
    # MariaDB como root (sin contraseña) y leer o cambiar cualquier base: no se carga (vienen
    # desactivados; se activan a mano con INSTALL SONAME)
    local engines
    engines=$("${mysql[@]}" -N -e "SELECT GROUP_CONCAT(ENGINE) FROM information_schema.ENGINES
        WHERE ENGINE IN ('FEDERATED', 'CONNECT', 'SPIDER', 'OQGRAPH') AND SUPPORT IN ('YES', 'DEFAULT')" < /dev/null 2> /dev/null)
    if [ -n "$engines" ] && [ "$engines" != NULL ]; then
        echo "No se carga: MariaDB tiene activos los motores $engines, con los que una tabla del volcado"
        echo "podria entrar como root en este MariaDB. Desactivalos (UNINSTALL SONAME) y vuelve a cargarlo."
        return 1
    fi
    if ! db_exists "$db"; then
        if [ $create -eq 0 ]; then
            echo "La base $db no existe en lampp-$folder (con --crear se crea)"

            return 1
        fi
        echo "Creando la base de datos $db..."
        run "${mysql[@]}" -e "CREATE DATABASE \`$db\` CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci" < /dev/null || return 1
    else
        # (ya existe: se vacia siempre, con copia antes si tiene tablas y se ha pedido)
        local tables
        tables=$("${mysql[@]}" -N -e "SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA='$db'" < /dev/null)
        if ! [[ "$tables" =~ ^[0-9]+$ ]]; then
            echo "No se pueden ver las tablas de $db: no se ha cambiado nada."
            return 1
        fi
        if [ "$tables" -gt 0 ] && [ $backup -eq 1 ]; then
            saved="$COPIES_DIR/lampp-$DB_FOLDER-$db-antes-de-cargar-$(date +%Y%m%d-%H%M%S).sql.gz"
            echo "$db ya tiene $tables $([ "$tables" == 1 ] && echo tabla || echo tablas): se borran todas antes de cargar."
            echo "Antes se guarda una copia suya en $saved"
            run mkdir -p -m 700 "$COPIES_DIR"
            if ! export_database "$db" "$saved" "$DB_FOLDER"; then
                echo "No se ha podido guardar la copia de $db, asi que no se ha cambiado nada."
                return 1
            fi
        fi
        if [ "$tables" -gt 0 ] && [ $backup -eq 0 ] && [ $told -eq 0 ]; then
            echo "$db ya tiene $tables $([ "$tables" == 1 ] && echo tabla || echo tablas): se borran todas antes de cargar."
            echo "Sin copia: lo que tenia no se podra recuperar (con --copia se guarda antes en ~/nexum-backups)"
        fi
        echo "Vaciando la base de datos $db..."
        local charset=$("${mysql[@]}" -N -e "SELECT CONCAT(DEFAULT_CHARACTER_SET_NAME, ' COLLATE ', DEFAULT_COLLATION_NAME)
            FROM information_schema.SCHEMATA WHERE SCHEMA_NAME='$db'" < /dev/null)
        run "${mysql[@]}" -e "DROP DATABASE \`$db\`; CREATE DATABASE \`$db\` CHARACTER SET $charset" < /dev/null || return 1
    fi

    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] mysql $db < $file"
        [ -n "$project" ] && import_project "$db" "$project"

        return 0
    fi

    # Las copias de WordPress o PrestaShop pueden traer filas grandes: el servidor admite paquetes
    # de hasta 1 GB (hasta que se reinicie) y el cliente tambien
    "${mysql[@]}" -e "SET GLOBAL max_allowed_packet = GREATEST(@@GLOBAL.max_allowed_packet, 1073741824)" < /dev/null 2> /dev/null

    # El volcado se carga con el usuario de esa base (lvm_bd_<base>), que solo puede tocarla (no
    # root): un .sql de una web comprometida no puede cambiar otras bases, crear usuarios ni leer o
    # escribir ficheros desde el servidor (sin el permiso FILE). En el permiso, el _ va escapado
    # (si no, wp_x valdria tambien para wpYx). Al terminar se bloquea: no puede entrar, pero las
    # vistas y disparadores del volcado (que son suyos) siguen funcionando.
    local imp_user="lvm_bd_$db" imp_pass grant_db=${db//_/\\_}
    imp_pass=$(head -c 18 /dev/urandom | base64 | tr -d '/+=\n')
    db_drop_import_users "${mysql[@]}"
    # (con su huella, no con la contraseña: la orden se ve en ps; la contraseña va en MYSQL_PWD)
    local imp_hash
    imp_hash=$(printf '%s' "$imp_pass" | db_pass_hash) || return 1
    if ! "${mysql[@]}" -e "CREATE USER IF NOT EXISTS '$imp_user'@'localhost' IDENTIFIED BY PASSWORD '$imp_hash';
            ALTER USER '$imp_user'@'localhost' IDENTIFIED BY PASSWORD '$imp_hash' ACCOUNT UNLOCK;
            GRANT ALL PRIVILEGES ON \`$grant_db\`.* TO '$imp_user'@'localhost'" < /dev/null; then
        echo "No se ha podido preparar el usuario de la base para cargar el volcado"
        return 1
    fi
    # Si la carga se interrumpe, solo se marca: despues se limpia lo que haya cargado (con su
    # usuario, que aun puede entrar) y se bloquea igual
    local imp_stop=0
    trap 'imp_stop=1' INT TERM HUP PIPE
    local imp=(env MYSQL_PWD="$imp_pass" "${DB_SAFE[@]}" "$DB_CLIENT" -u"$imp_user" --default-character-set=utf8mb4
               --binary-mode --local-infile=0)

    # Lectura: descomprimir (gzip o zip), quitar la linea del modo sandbox y los DEFINER de vistas,
    # disparadores y rutinas (son de otro usuario: con el temporal no se podrian crear)
    local source=(cat) filter=(env LC_ALL=C sed -E -e 's/DEFINER=`[^`]*`@`[^`]*`//g')
    case $kind in
        gz) source=(gzip -dc) ;;
        zip) source=(python3 -I -c "$ZIP_SQL_PY" extraer -) ;;
    esac
    [ $sandbox -eq 1 ] && filter=(env LC_ALL=C sed -E -e '/^\/\*M!999999\\-/d' -e 's/DEFINER=`[^`]*`@`[^`]*`//g')
    local definer=(python3 -I -c "$INVOKER_PY")
    local start=$(date +%s)

    exec 3< "$file"
    if [ -n "$TASK_OWNER" ]; then
        task_detail "cargando" fdpos "/proc/$BASHPID/fdinfo/3" "$size" "$start"
    elif [ -n "$LVM_PROGRESO" ]; then
        { echo "I|1|1|Cargando $name en $db|$start"
          echo "S|1|0|100|cargando|fdpos|/proc/$BASHPID/fdinfo/3|$size|$start"; } >> "$LVM_PROGRESO"
    fi
    echo "Cargando..."
    if [ -z "$LVM_PROGRESO" ] && [ -t 2 ] && command -v pv > /dev/null; then
        # En una terminal, la barra de pv (el zip necesita poder saltar dentro del fichero: pv va
        # sobre el .sql ya descomprimido)
        if [ $kind == zip ]; then
            ( set -o pipefail; python3 -I -c "$ZIP_SQL_PY" extraer "$file" | pv -s "$inner_size" \
                | "${filter[@]}" | "${definer[@]}" | "${imp[@]}" --max-allowed-packet=1G "$db" )
        else
            ( set -o pipefail; pv -s "$size" <&3 | "${source[@]}" | "${filter[@]}" \
                | "${definer[@]}" | "${imp[@]}" --max-allowed-packet=1G "$db" )
        fi
    else
        ( set -o pipefail; "${source[@]}" <&3 | "${filter[@]}" | "${definer[@]}" | "${imp[@]}" --max-allowed-packet=1G "$db" )
    fi
    rc=$?
    exec 3<&-
    # Primero se cortan sus conexiones (un evento del volcado que ya estuviera corriendo), despues
    # eventos y tablas con DIRECTORY, luego lo INVOKER; se bloquea y root repasa que no quede nada
    db_kill_user "$imp_user" "${mysql[@]}"
    db_neutralize_extras "$db" "${imp[@]}"
    db_neutralize_invoker "$db" "${imp[@]}"
    db_lock_import_user "$imp_user" "${mysql[@]}"
    db_root_cleanup "$db" "${mysql[@]}"
    trap - INT TERM HUP PIPE
    if [ $imp_stop -eq 1 ]; then
        echo "Carga interrumpida. Lo anterior ya esta en $db."
        [ -n "$saved" ] && echo "Lo que tenia antes esta en $saved (se vuelve a cargar con importar-bd)."
        return 130
    fi
    [ -n "$LVM_PROGRESO" ] && [ -z "$TASK_OWNER" ] && echo "R|bd:$db|$rc" >> "$LVM_PROGRESO"

    local secs=$(( $(date +%s) - start ))
    if [ $rc -ne 0 ]; then
        echo "Error al cargar $name. Lo anterior al error ya esta en $db."
        echo "Si el error es «Access denied», el volcado intenta tocar otra base o crear usuarios:"
        echo "solo se carga lo que va en $db (un volcado de una sola base, como los de phpMyAdmin)."
        [ -n "$saved" ] && echo "Lo que tenia antes esta en $saved (se vuelve a cargar con importar-bd)."

        return 1
    fi

    local tables=$("${mysql[@]}" -N -e "SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA='$db'" < /dev/null)
    echo "Cargado en $((secs / 60)) min $((secs % 60)) s. La base $db tiene ahora $tables $([ "$tables" == 1 ] && echo tabla || echo tablas)."
    db_note_import "${DB_TARGET_DATA:-/opt/lampp/var/mysql}" "$db" "$(date +%s)"
    # Administrador de pruebas para el boton del panel de Cargar proyecto (WordPress o PrestaShop)
    local admin
    admin=$(test_admin "$db" "$project")
    grep -v '^A|' <<< "$admin" | grep .
    grep -q '^A|' <<< "$admin" && echo "Administrador de pruebas del panel: $TEST_ADMIN_USER, contraseña $TEST_ADMIN_PASS"
    # Correo de pruebas: lo que mande la web (sus plugins de correo, la configuracion de la tienda) va a
    # Mailpit (o, apagado, se deshace lo que traiga hecho)
    mail_db "$db"
    [ -n "$project" ] && { import_project "$db" "$project" || return 1; }
    return 0
}

# ¿Va a necesitar sudo importar-bd? Solo habla con el MariaDB en marcha (con la version parada no carga
# nada), salvo al cargarla para una tienda PrestaShop (--proyecto) cuya var/cache tiene ficheros de otro
# usuario (los que creo Apache): ps_clear_cache los borra con sudo. import_need_root <opciones de importar-bd>
function import_need_root() {
    local project=""
    while [ $# -gt 0 ]; do
        [ "$1" == --proyecto ] && project=${2%/}
        shift
    done
    [ -n "$project" ] && valid_project "$project" > /dev/null 2>&1 && is_prestashop "$project" 2> /dev/null || return 1
    find "$HTDOCS_DIR/$project/var/cache" -mindepth 1 ! -user "$(id -un)" -print -quit 2> /dev/null | grep -q .
}
# Vistas y rutinas SQL SECURITY INVOKER de un volcado: se ejecutarian con los permisos de quien las
# use (root en phpMyAdmin, o en la web si su wp-config.php usa root). Pasan a DEFINER, de
# lvm_bd_<base> (lo hace ese mismo usuario). Con --force: una vista rota del volcado no para las
# demas. Las que no se dejen cambiar se borran, y se avisa. db_neutralize_invoker <base> <cliente...>
function db_neutralize_invoker() {
    local db=$1 left
    shift
    local list="FROM information_schema.VIEWS WHERE TABLE_SCHEMA = DATABASE() AND SECURITY_TYPE = 'INVOKER'"
    local rlist="FROM information_schema.ROUTINES WHERE ROUTINE_SCHEMA = DATABASE() AND SECURITY_TYPE = 'INVOKER'"
    "$@" --raw -N "$db" -e "SELECT CONCAT('ALTER SQL SECURITY DEFINER VIEW \`', REPLACE(TABLE_NAME, '\`', '\`\`'), '\` AS ', VIEW_DEFINITION, ';') $list;
        SELECT CONCAT('ALTER ', ROUTINE_TYPE, ' \`', REPLACE(ROUTINE_NAME, '\`', '\`\`'), '\` SQL SECURITY DEFINER;') $rlist" \
        < /dev/null 2> /dev/null | "$@" --force "$db" > /dev/null 2>&1
    left=$("$@" --raw -N "$db" -e "SELECT CONCAT('vista ', TABLE_NAME) $list; SELECT CONCAT(LOWER(ROUTINE_TYPE), ' ', ROUTINE_NAME) $rlist" < /dev/null 2> /dev/null)
    [ -z "$left" ] && return 0
    "$@" --raw -N "$db" -e "SELECT CONCAT('DROP VIEW IF EXISTS \`', REPLACE(TABLE_NAME, '\`', '\`\`'), '\`;') $list;
        SELECT CONCAT('DROP ', ROUTINE_TYPE, ' IF EXISTS \`', REPLACE(ROUTINE_NAME, '\`', '\`\`'), '\`;') $rlist" \
        < /dev/null 2> /dev/null | "$@" --force "$db" > /dev/null 2>&1
    echo "Aviso: el volcado traia vistas o rutinas SQL SECURITY INVOKER que no se han podido pasar a"
    echo "DEFINER (rotas o mal hechas). Se han borrado, porque se ejecutarian con los permisos de quien"
    echo "las usara: $(printf '%s' "$left" | tr -c '[:alnum:]_ \n-' '?' | head -20 | paste -sd ',' - | sed 's/,/, /g')"
    # (lo que no haya podido borrar este usuario, como los paquetes de MariaDB 10.4, lo borra root
    # en db_root_cleanup)
    return 0
}

# Eventos y tablas con DATA DIRECTORY o INDEX DIRECTORY de un volcado. Los eventos se ejecutan solos
# (si el planificador de MariaDB esta encendido) aunque el usuario de la base este bloqueado, y
# podrian volver a crear vistas INVOKER. Las tablas con esas opciones guardan sus ficheros fuera de
# la carpeta de MariaDB (en las de otras versiones, en /tmp...). Se borran, y se avisa (lo hace el
# usuario de la base). db_neutralize_extras <base> <cliente...>
DB_DIRECTORY_PY='
import re, sys
# Salida de SHOW CREATE TABLE con -N --batch: nombre<TAB>sentencia, con \n \t \\ escapados
def unesc(s):
    return re.sub(r"\\(.)", lambda m: {"n": "\n", "t": "\t", "0": "\0"}.get(m.group(1), m.group(1)), s)
# La opcion de verdad es DATA DIRECTORY = <cadena>: las cadenas (un COMMENT o un DEFAULT que digan
# data directory), los nombres entre comillas y los comentarios no cuentan
def options(sql):
    sql = re.sub(r"\x27(?:[^\x27\\]|\\.|\x27\x27)*\x27", " Q ", sql)
    sql = re.sub(r"`(?:[^`]|``)*`", " I ", sql)
    return re.sub(r"/\*.*?\*/", " ", sql, flags=re.S)
for line in sys.stdin:
    name, _, create = line.rstrip("\n").partition("\t")
    if re.search(r"(?i)\b(DATA|INDEX)\s+DIRECTORY\s*=?\s*Q", options(unesc(create))):
        print("DROP TABLE IF EXISTS `%s`;" % unesc(name).replace("`", "``"))
'
function db_neutralize_extras() {
    local db=$1 events tables drop
    shift
    local elist="FROM information_schema.EVENTS WHERE EVENT_SCHEMA = DATABASE()"
    events=$("$@" --raw -N "$db" -e "SELECT EVENT_NAME $elist" < /dev/null 2> /dev/null)
    if [ -n "$events" ]; then
        "$@" --raw -N "$db" -e "SELECT CONCAT('DROP EVENT IF EXISTS \`', REPLACE(EVENT_NAME, '\`', '\`\`'), '\`;') $elist" \
            < /dev/null 2> /dev/null | "$@" --force "$db" > /dev/null 2>&1
        echo "Aviso: el volcado traia eventos programados (se ejecutan solos en el servidor). Se han"
        echo "borrado: $(printf '%s' "$events" | tr -c '[:alnum:]_ \n-' '?' | head -20 | paste -sd ',' - | sed 's/,/, /g')"
    fi
    # Las particionadas no lo dicen en CREATE_OPTIONS: se mira su SHOW CREATE TABLE
    local tlist="FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_TYPE = 'BASE TABLE'"
    drop=$( { "$@" --raw -N "$db" -e "SELECT CONCAT('DROP TABLE IF EXISTS \`', REPLACE(TABLE_NAME, '\`', '\`\`'), '\`;')
                $tlist AND CREATE_OPTIONS LIKE '%DIRECTORY%'" < /dev/null 2> /dev/null
              "$@" --raw -N "$db" -e "SELECT CONCAT('SHOW CREATE TABLE \`', REPLACE(TABLE_NAME, '\`', '\`\`'), '\`;')
                $tlist AND CREATE_OPTIONS LIKE '%partitioned%'" < /dev/null 2> /dev/null \
                  | "$@" -N --batch --force "$db" 2> /dev/null | /usr/bin/python3 -I -c "$DB_DIRECTORY_PY"; } | sort -u)
    [ -z "$drop" ] && return 0
    tables=$(printf '%s\n' "$drop" | sed -e 's/^DROP TABLE IF EXISTS `//' -e 's/`;$//')
    printf '%s\n' "$drop" | "$@" --force "$db" > /dev/null 2>&1
    echo "Aviso: el volcado traia tablas con DATA DIRECTORY o INDEX DIRECTORY, que guardan sus ficheros"
    echo "fuera de la carpeta de MariaDB. Se han borrado (con sus ficheros): $(printf '%s' "$tables" \
        | tr -c '[:alnum:]_ \n-' '?' | head -20 | paste -sd ',' - | sed 's/,/, /g')"
    if [ -n "$("$@" --raw -N "$db" -e "SELECT 1 $tlist AND CREATE_OPTIONS LIKE '%DIRECTORY%' LIMIT 1" < /dev/null 2> /dev/null)" ]; then
        echo "ATENCION: siguen quedando tablas con DATA DIRECTORY en $db."
    fi
    return 0
}

# Huella mysql_native_password de una contraseña leida de la entrada (asi no va en ninguna linea de
# ordenes, que cualquier usuario del equipo ve con ps)
function db_pass_hash() {
    python3 -I -c 'import hashlib, sys; p = sys.stdin.buffer.read(); print("*" + hashlib.sha1(hashlib.sha1(p).digest()).hexdigest().upper())'
}

# Bloquea el usuario de una base (con otra contraseña al azar): ya no puede entrar, pero lo suyo
# (vistas, disparadores) sigue funcionando. Se borra y se vuelve a crear con solo los permisos de su
# base: si durante la carga hubiera conseguido otros (globales, de otras bases, roles), no le quedan.
# db_lock_import_user <usuario> <cliente como root...>
function db_lock_import_user() {
    local user=$1 pass extra
    shift
    [[ "$user" =~ ^lvm_bd_[A-Za-z0-9_-]+$ ]] || return 0
    pass=$(head -c 18 /dev/urandom | base64 | tr -d '/+=\n')
    # Sin permiso para crear vistas, rutinas ni eventos: una rutina suya (DEFINER) no podria crear
    # despues otra INVOKER. Lo que ya tiene sigue funcionando (la proxima carga le vuelve a dar todo)
    local gdb=${user#lvm_bd_}
    gdb=${gdb//_/\\_}
    db_kill_user "$user" "$@"
    if ! "$@" -e "DROP USER IF EXISTS '$user'@'localhost';
            CREATE USER '$user'@'localhost' IDENTIFIED BY '$pass' ACCOUNT LOCK;
            GRANT ALL PRIVILEGES ON \`$gdb\`.* TO '$user'@'localhost';
            REVOKE CREATE VIEW, CREATE ROUTINE, ALTER ROUTINE, EVENT ON \`$gdb\`.* FROM '$user'@'localhost'" < /dev/null 2> /dev/null; then
        # (MariaDB sin DROP USER IF EXISTS o sin ACCOUNT LOCK: como antes, y sin lo de fuera de su base)
        "$@" -e "ALTER USER '$user'@'localhost' IDENTIFIED BY '$pass' ACCOUNT LOCK" < /dev/null 2> /dev/null
        "$@" -e "REVOKE ALL PRIVILEGES, GRANT OPTION FROM '$user'@'localhost'" < /dev/null 2> /dev/null
        "$@" -e "GRANT ALL PRIVILEGES ON \`$gdb\`.* TO '$user'@'localhost'" < /dev/null 2> /dev/null
        "$@" -e "REVOKE CREATE VIEW, CREATE ROUTINE, ALTER ROUTINE, EVENT ON \`$gdb\`.* FROM '$user'@'localhost'" < /dev/null 2> /dev/null
    fi
    # Lo que le quede fuera de su base (no deberia haber nada) se avisa
    extra=$("$@" -N --raw -e "SHOW GRANTS FOR '$user'@'localhost'" < /dev/null 2> /dev/null \
        | LVM_ON="ON \`$gdb\`.* TO " awk 'index($0, "GRANT USAGE ON *.* TO ") != 1 && !index($0, ENVIRON["LVM_ON"])' | wc -l)
    [ "${extra:-0}" -gt 0 ] && echo "Aviso: el usuario $user conserva permisos fuera de su base. Revisalo en phpMyAdmin (Cuentas de usuario)."
    db_kill_user "$user" "$@"
    return 0
}

# Corta las conexiones de un usuario de base (tambien un evento suyo en marcha). Como root.
# db_kill_user <usuario> <cliente como root...>
function db_kill_user() {
    local user=$1
    shift
    [[ "$user" =~ ^lvm_bd_[A-Za-z0-9_-]+$ ]] || return 0
    "$@" -e "KILL USER '$user'@'localhost'" < /dev/null 2> /dev/null
    return 0
}

# Repaso como root, al final de una carga (o de una que se corto): si en la base quedan vistas,
# rutinas o paquetes INVOKER, eventos o tablas con DATA DIRECTORY, root los borra (solo DROP: nunca
# se ejecutan ni se pasan a DEFINER de root) y avisa. db_root_cleanup <base> <cliente como root...>
function db_root_cleanup() {
    local db=$1 drop left
    shift
    [[ "$db" =~ ^[A-Za-z0-9_-]+$ ]] || return 0
    local w="TABLE_SCHEMA = '$db'" rw="ROUTINE_SCHEMA = '$db'" ew="EVENT_SCHEMA = '$db'"
    # (--force: en una MariaDB con las tablas del sistema antiguas, EVENTS o ROUTINES dan error y lo
    # demas tiene que seguir)
    drop=$( { "$@" --raw -N --force -e "SELECT CONCAT('DROP VIEW IF EXISTS \`$db\`.\`', REPLACE(TABLE_NAME, '\`', '\`\`'), '\`;')
                FROM information_schema.VIEWS WHERE $w AND SECURITY_TYPE = 'INVOKER';
            SELECT CONCAT(IF(ROUTINE_TYPE LIKE 'PACKAGE%', 'SET sql_mode = ORACLE; ', ''), 'DROP ', ROUTINE_TYPE,
                ' IF EXISTS \`$db\`.\`', REPLACE(ROUTINE_NAME, '\`', '\`\`'), '\`; SET sql_mode = DEFAULT;')
                FROM information_schema.ROUTINES WHERE $rw AND SECURITY_TYPE = 'INVOKER'
                ORDER BY ROUTINE_TYPE = 'PACKAGE';
            SELECT CONCAT('DROP EVENT IF EXISTS \`$db\`.\`', REPLACE(EVENT_NAME, '\`', '\`\`'), '\`;')
                FROM information_schema.EVENTS WHERE $ew;
            SELECT CONCAT('DROP TABLE IF EXISTS \`$db\`.\`', REPLACE(TABLE_NAME, '\`', '\`\`'), '\`;')
                FROM information_schema.TABLES WHERE $w AND TABLE_TYPE = 'BASE TABLE' AND CREATE_OPTIONS LIKE '%DIRECTORY%'" \
                < /dev/null 2> /dev/null
          "$@" --raw -N -e "SELECT CONCAT('SHOW CREATE TABLE \`$db\`.\`', REPLACE(TABLE_NAME, '\`', '\`\`'), '\`;')
                FROM information_schema.TABLES WHERE $w AND TABLE_TYPE = 'BASE TABLE' AND CREATE_OPTIONS LIKE '%partitioned%'" \
                < /dev/null 2> /dev/null | "$@" -N --batch --force 2> /dev/null | /usr/bin/python3 -I -c "$DB_DIRECTORY_PY" \
                | sed "s/^DROP TABLE IF EXISTS /DROP TABLE IF EXISTS \`$db\`./"; } )
    [ -z "$drop" ] && return 0
    printf '%s\n' "$drop" | "$@" --force > /dev/null 2>&1
    left=$("$@" --raw -N --force -e "SELECT CONCAT('vista ', TABLE_NAME) FROM information_schema.VIEWS WHERE $w AND SECURITY_TYPE = 'INVOKER';
        SELECT CONCAT(LOWER(ROUTINE_TYPE), ' ', ROUTINE_NAME) FROM information_schema.ROUTINES WHERE $rw AND SECURITY_TYPE = 'INVOKER';
        SELECT CONCAT('evento ', EVENT_NAME) FROM information_schema.EVENTS WHERE $ew" < /dev/null 2> /dev/null)
    echo "Aviso: en $db quedaban $(printf '%s\n' "$drop" | grep -c 'DROP ') cosas del volcado que no deben estar (vistas o"
    echo "rutinas INVOKER, eventos o tablas con DATA DIRECTORY): las ha borrado root."
    if [ -n "$left" ]; then
        echo "ATENCION: siguen en $db: $(printf '%s' "$left" | tr -c '[:alnum:]_ \n-' '?' | head -10 | paste -sd ',' - | sed 's/,/, /g')."
        echo "No abras esa base como root en phpMyAdmin hasta quitarlas."
    fi
    return 0
}

# Borra los usuarios temporales de la 1.37 (lvm_imp_*) y bloquea los de las bases (lvm_bd_*) que
# hayan quedado abiertos (una carga que no termino). Recibe el cliente de MariaDB como root.
function db_drop_import_users() {
    local u
    for u in $("$@" -N -e "SELECT User FROM mysql.user WHERE User LIKE 'lvm\\_imp\\_%' AND Host='localhost'" < /dev/null 2> /dev/null); do
        [[ "$u" =~ ^lvm_imp_[0-9a-f]+$ ]] && "$@" -e "DROP USER IF EXISTS '$u'@'localhost'" < /dev/null 2> /dev/null
    done
    local open_users old_tables=0
    open_users=$("$@" -N -e "SELECT User FROM mysql.global_priv WHERE User LIKE 'lvm\\_bd\\_%' AND Host='localhost'
            AND IFNULL(JSON_VALUE(Priv, '$.account_locked'), 'false') <> 'true'" < /dev/null 2> /dev/null) \
        || { old_tables=1; open_users=$("$@" -N -e "SELECT User FROM mysql.user WHERE User LIKE 'lvm\\_bd\\_%' AND Host='localhost'" \
            < /dev/null 2> /dev/null); }
    # (con las tablas del sistema antiguas no hay global_priv ni se sabe si estan bloqueados: todos)
    for u in $open_users; do
        # (una carga que se corto: lo que dejara en su base lo repasa root)
        db_kill_user "$u" "$@"
        db_lock_import_user "$u" "$@"
        # (con las tablas antiguas no se sabe cuales se cortaron: se bloquean todos, pero su base no se
        # repasa, que borraria lo que hayas creado despues a proposito)
        [ $old_tables -eq 0 ] && db_root_cleanup "${u#lvm_bd_}" "$@"
    done
    return 0
}

# MariaDB de XAMPP trae un usuario anonimo (sin nombre ni contraseña) y permisos para cualquiera
# sobre las bases test y test_*: se quitan (las pilas propias ya se crean sin ellos). Con la version
# montada en marcha; si root tiene contraseña, con MYSQL_PWD.
# Tablas del sistema de MariaDB (mysql.*) de una version anterior a la del servidor: los datos de
# XAMPP vienen de una MariaDB antigua sin poner al dia, y el servidor escribe un error en su registro
# cada vez que usa las estadisticas de una tabla (en una 8.2.4 llego a 28 GB). 0 si la version
# montada, en marcha, las tiene asi (en las de 10.4 en adelante: varbinary(255) y varchar(199))
function db_system_outdated() {
    [ -x "$DB_CLIENT" ] && lampp_running || return 1
    local t
    t=$("${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N -e "SELECT CONCAT(TABLE_NAME, '.', COLUMN_NAME, '=', COLUMN_TYPE) FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = 'mysql' AND ((TABLE_NAME = 'column_stats' AND COLUMN_NAME = 'min_value')
        OR (TABLE_NAME = 'innodb_table_stats' AND COLUMN_NAME = 'table_name'))" < /dev/null 2> /dev/null) || return 1
    [ -n "$t" ] || return 1
    grep -q "^column_stats.min_value=varbinary" <<< "$t" && grep -q "^innodb_table_stats.table_name=varchar(199)" <<< "$t" && return 1
    return 0
}

# Registro de errores de MariaDB de una version: el .err mas grande de var/mysql (solo su ruta)
function db_error_log() {
    find "$1/var/mysql" -maxdepth 1 -type f -name '*.err' -printf '%s %p\n' 2> /dev/null | sort -rn | head -1 | cut -d' ' -f2-
}

# reparar-bd-sistema [--copia]: pone al dia las tablas del sistema de MariaDB de la version montada (con su
# propio mysql_upgrade, solo las del sistema: las bases de los proyectos no se tocan), despues de
# guardar (con --copia) una copia de la base mysql en ~/nexum-backups, y vacia su registro de errores si es grande
function repair_db_system() {
    local dir name upgrade dump log size backup="" out copy=0
    [ "$1" == "--copia" ] && copy=1
    dir=$(active_dir)
    if [ -z "$dir" ] || ! lampp_running; then
        echo "La version activa tiene que estar en marcha: arrancala y vuelve a intentarlo."
        return 1
    fi
    if ! wait_mariadb; then
        echo "MariaDB no responde o root tiene contraseña (ponla en MYSQL_PWD y vuelve a intentarlo)."
        return 1
    fi
    name=$(basename "$dir")
    if [ -x "$dir/mysql/bin/mariadb-upgrade" ]; then
        upgrade=("$dir/mysql/bin/mariadb-upgrade") dump=("$dir/mysql/bin/mariadb-dump")
    elif [ -x "$dir/bin/mysql_upgrade" ] && [ -x "$dir/bin/mysqldump" ]; then
        upgrade=("$dir/bin/mysql_upgrade") dump=("$dir/bin/mysqldump")
    else
        echo "$name no tiene mysql_upgrade"
        return 1
    fi
    upgrade+=(--no-defaults -S "$dir/var/mysql/mysql.sock" -uroot)
    dump+=(--no-defaults -S "$dir/var/mysql/mysql.sock" -uroot)
    log=$(db_error_log "$dir")
    # mysql_upgrade escribe en la carpeta de datos (mysql_upgrade_info): se ejecuta con su dueño
    # (mysql, o tu usuario en el Mac), nunca como root. Con sudo -u, MYSQL_PWD no pasaria
    local owner as_owner=()
    owner=$(stat -c %U "$dir/var/mysql" 2> /dev/null)
    if [ -n "$owner" ] && [ "$owner" != "$(id -un)" ]; then
        [[ "$owner" =~ ^[A-Za-z0-9_][A-Za-z0-9_.-]{0,31}$ ]] && [ "$owner" != root ] || {
            echo "La carpeta de datos de $name es de $owner: no se ejecuta mysql_upgrade con ese usuario."
            return 1
        }
        as_owner=(sudo -u "$owner")
        if [ -n "$MYSQL_PWD" ]; then
            echo "root de MariaDB tiene contraseña y con sudo -u no se le pasa: hazlo a mano en la terminal:"
            echo "  sudo -u $owner ${upgrade[0]} --no-defaults -S <socket> -uroot -p --upgrade-system-tables --force"
            return 1
        fi
    fi
    if db_system_outdated; then
        echo "Las tablas del sistema de MariaDB de $name son de una version anterior: se ponen al dia"
        echo "(las bases de los proyectos no se tocan)."
        [ $copy -eq 1 ] && backup="$COPIES_DIR/$name-mysql-sistema-$(date +%Y%m%d-%H%M%S).sql.gz"
        [ $copy -eq 0 ] && echo "Sin copia: las tablas del sistema de ahora no se podran recuperar (con --copia se guardan antes)"
        if [ "$DRY" -eq 1 ]; then
            [ -n "$backup" ] && echo "  [simulacion] copia de la base mysql en $backup"
            echo "  [simulacion] ${upgrade[0]##*/} --upgrade-system-tables --force"
        else
            if [ -n "$backup" ]; then
                mkdir -p -m 700 "$COPIES_DIR" || return 1
                if ! ( set -o pipefail; umask 077; "${dump[@]}" --databases mysql < /dev/null | gzip > "$backup" ); then
                    rm -f "$backup"
                    echo "No se ha podido guardar la copia de la base mysql: no se cambia nada."
                    return 1
                fi
                echo "Copia de las tablas del sistema: $backup"
            fi
            if ! out=$("${as_owner[@]}" "${upgrade[@]}" --upgrade-system-tables --force < /dev/null 2>&1); then
                echo "$out" | tail -8 | sed 's/^/  /'
                echo "No se han podido poner al dia${backup:+ (la copia esta en $backup)}."
                return 1
            fi
            echo "$out" | grep -E '^(Phase|OK)' | sed 's/^/  /'
            if db_system_outdated; then
                echo "Siguen sin estar al dia: revisa la salida de arriba."
                return 1
            fi
            echo "Tablas del sistema al dia."
            # Con las tablas antiguas, MariaDB no leia mysql.proc: rutinas INVOKER de volcados de
            # antes de la 1.42 (que nunca se neutralizaron) vuelven a funcionar. Se avisa de cuales
            local inv
            inv=$("${DB_SAFE[@]}" "$DB_CLIENT" -uroot --raw -N --force -e "SELECT CONCAT(ROUTINE_SCHEMA, '.', ROUTINE_NAME) FROM information_schema.ROUTINES
                    WHERE SECURITY_TYPE = 'INVOKER' AND ROUTINE_SCHEMA NOT IN ('mysql', 'sys');
                SELECT CONCAT(TABLE_SCHEMA, '.', TABLE_NAME) FROM information_schema.VIEWS
                    WHERE SECURITY_TYPE = 'INVOKER' AND TABLE_SCHEMA NOT IN ('mysql', 'sys');
                SELECT CONCAT(EVENT_SCHEMA, '.', EVENT_NAME, ' (evento)') FROM information_schema.EVENTS" < /dev/null 2> /dev/null)
            if [ -n "$inv" ]; then
                echo "Aviso: estas rutinas, vistas o eventos se ejecutan con los permisos de quien las use (root en"
                echo "phpMyAdmin). Si no las reconoces, vuelve a cargar esa BBDD con el gestor, que las neutraliza:"
                printf '%s\n' "$inv" | tr -c '[:alnum:]_ .()\n-' '?' | head -30 | sed 's/^/  /'
            fi
        fi
    else
        echo "Las tablas del sistema de MariaDB de $name ya estan al dia."
    fi
    # El registro: si pasa de 100 MB se vacia (solo son errores, ya corregidos; MariaDB sigue
    # escribiendo en el mismo fichero)
    if [ -n "$log" ] && [ -f "$log" ] && [ ! -L "$log" ] && [[ "$log" == "$dir"/var/mysql/*.err ]]; then
        size=$(stat -c %s "$log")
        if [ "$size" -gt 104857600 ]; then
            echo "El registro de errores de MariaDB ($log) ocupa $((size / 1048576)) MB: se vacia."
            # (con su dueño, mysql, no como root: no hace falta, y root seguiria un enlace)
            if [ ${#as_owner[@]} -gt 0 ]; then
                run sudo -u "$owner" truncate -s 0 "$log" || return 1
            else
                run truncate -s 0 "$log" || return 1
            fi
        fi
    fi
    return 0
}

# Espera (hasta 8 s) a que MariaDB de la version montada acepte a root. 1 si no arranca o pide
# contraseña (y no esta en MYSQL_PWD)
function wait_mariadb() {
    local i out
    [ -x "$DB_CLIENT" ] || return 1
    for i in 1 2 3 4 5 6 7 8; do
        out=$("${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N -e "SELECT 1" < /dev/null 2>&1) && return 0
        [[ "$out" == *"Access denied"* ]] && return 1
        sleep 1
    done
    return 1
}

function secure_mariadb() {
    [ -x "$DB_CLIENT" ] || return 0
    local mysql=("${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N) hosts h
    hosts=$("${mysql[@]}" -e "SELECT Host FROM mysql.user WHERE User=''" < /dev/null 2> /dev/null) || return 0
    for h in $hosts; do
        [[ "$h" =~ ^[A-Za-z0-9._%-]+$ ]] || continue
        echo "MariaDB: se quita el usuario anonimo (''@$h)"
        [ "$DRY" -eq 1 ] || "${mysql[@]}" -e "DROP USER IF EXISTS ''@'$h'" < /dev/null 2> /dev/null
    done
    if [ -n "$("${mysql[@]}" -e "SELECT 1 FROM mysql.db WHERE Db IN ('test', 'test\\_%') LIMIT 1" < /dev/null 2> /dev/null)" ]; then
        echo "MariaDB: se quitan los permisos de cualquiera sobre las bases test"
        [ "$DRY" -eq 1 ] || "${mysql[@]}" -e "DELETE FROM mysql.db WHERE Db IN ('test', 'test\\_%'); FLUSH PRIVILEGES" < /dev/null 2> /dev/null
    fi
    # Usuarios de las bases que hayan quedado sin bloquear (una carga interrumpida)
    [ "$DRY" -eq 1 ] || db_drop_import_users "${DB_SAFE[@]}" "$DB_CLIENT" -uroot
    return 0
}

# Base subida para un proyecto: pasa a ser su base (sustituye a la anterior). Si es un WordPress, su
# wp-config.php se rehace con la plantilla para que la use; si es una tienda PrestaShop, su
# parameters.php (o settings.inc.php) pasa a usarla y se vacia su cache
function import_project() {
    local db=$1 folder=$2
    remember_project "$db" "$folder" "${DB_TARGET_FOLDER:-}" --unica
    echo "La base $db queda asociada al proyecto $folder"
    if is_prestashop "$folder"; then
        PS_NEW_PARAMS=0
        ps_parameters "$folder" "$db" || return 1
        ps_set_db "$folder" "$db" || return 1
        ps_first_load "$folder"
    elif is_wordpress "$folder"; then
        wp_config "$folder" "$db" || return 1
    fi
    return 0
}

# Codigo de la ventana (Python). No puede contener una linea con solo LVM_GUI_PY.
function gui_source() {
    cat <<'LVM_GUI_PY'
#!/usr/bin/env python3
# Ventana de Nexum Dev Stack (GTK 3 y Python 3.8: funciona desde Ubuntu 20.04).
# La escribe y la abre "nexum ventana". No repite la logica del instalador: lo ejecuta con
# los comandos gui-* (datos) y con los de siempre (use, instalar, actualizar, desinstalar...)
# dentro de una pseudoterminal, para que sudo funcione igual que en la terminal; la contraseña
# se pide en una ventana y se escribe en esa terminal.
import base64
import codecs
import fcntl
import html
import http.server
import json
import os
import pty
import re
import zlib
import shlex
import shutil
import signal
import stat
import struct
import subprocess
import sys
import tempfile
import termios
import threading
import time

import gi

gi.require_version("Gtk", "3.0")
gi.require_version("Gdk", "3.0")
from gi.repository import Gdk, GdkPixbuf, Gio, GLib, GObject, Gtk

SCRIPT = os.path.abspath(sys.argv[1])
SIMULATE = os.environ.get("LVM_SIMULAR") == "1"
# Modo demostración (las capturas del manual): con LVM_DEMO=<carpeta> y solo en simulación, los comandos
# gui-* no llegan al script: sus respuestas son las de esa carpeta, con datos inventados
# (ayuda/herramientas/demo-linux.py). Nada de este equipo sale en la ventana
DEMO = os.environ.get("LVM_DEMO", "") if SIMULATE else ""
# Programas del sistema: el PATH de la sesion puede llevar delante carpetas tuyas (~/.local/bin),
# donde un sudo, un bash o un pkexec falso recibiria la contraseña que se escribe en la ventana
os.environ["PATH"] = "/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:/snap/bin"
for _k in [k for k in os.environ if k.startswith(("LD_", "PYTHON", "BASH_FUNC_"))
           or k in ("BASH_ENV", "ENV", "IFS", "CDPATH", "SHELLOPTS", "BASHOPTS", "PS4", "GLOBIGNORE")]:
    del os.environ[_k]
APP_ID = "dev.hexer.LamppVersionManager"
# Parches de PHP sin soporte que se compilan con el arreglo de PHP2Shell (PHP2SHELL_BACKPORTS del script)
PHP2SHELL_BACKPORTS = ("7.4.33", "8.0.30", "8.1.34")
ICON = "nexum"
LOG_DIR = os.path.expanduser("~/.lvm-instalador")
# Copias de seguridad (COPIES_DIR del script): solo las que se piden, y las de los ficheros que cambia el
# programa si está el ajuste COPIES_FILES_FLAG (nexum copias-ficheros si|no)
COPIES_DIR = os.path.expanduser("~/nexum-backups")
COPIES_FILES_FLAG = os.path.join(LOG_DIR, "copias-ficheros")
# La ultima version que estuvo activa (al parar y desactivar): la primera que ofrece ▶ en el visor
LAST_VERSION_FILE = os.path.join(LOG_DIR, "ultima-version")
# El aviso de la casilla de copia al actualizar una versión en su carpeta (solo hace falta si MariaDB cambia de rama)
UPDATE_COPY_WARN = "Sin copia, si su MariaDB cambia de rama, sus BBDD no se podrán recuperar."
PROJECTS_FILE = os.path.join(LOG_DIR, "proyectos")
# Apartados de la ventana que se han plegado (uno por línea): siguen plegados al volver a abrirla
FOLDED_FILE = os.path.join(LOG_DIR, "ventana-plegados")


def is_ps_db(db):
    """Base de una tienda PrestaShop: suelen llamarse ps_<tienda>."""
    return db.lower().startswith("ps_")


# Proyectos de /opt/htdocs (LVM_HTDOCS solo para pruebas)
HTDOCS = os.environ.get("LVM_HTDOCS", "/opt/htdocs")
# (en la demostración, la de ejemplo: nunca la de verdad. El script quita LVM_HTDOCS fuera de las pruebas)
if DEMO:
    HTDOCS = os.path.join(DEMO, "htdocs")
DB_RULES = [
    ("wp-config.php", r"""^[ \t]*define\(\s*['"]DB_NAME['"]\s*,\s*['"]([^'"]+)"""),
    ("app/config/parameters.php", r"""['"]database_name['"]\s*=>\s*['"]([^'"]+)"""),
    ("config/settings.inc.php", r"""define\(\s*['"]_DB_NAME_['"]\s*,\s*['"]([^'"]+)"""),
    (".env", r"""^\s*DB_DATABASE\s*=\s*["']?([^"'\s#]+)"""),
]


# Visual Studio Code, según cómo se haya instalado: .deb o .rpm (el nuevo y el antiguo), snap,
# flatpak o el paquete de Arch
VSCODE_IDS = ("com.microsoft.VSCode.desktop", "code.desktop", "code_code.desktop",
              "com.visualstudio.code.desktop", "visual-studio-code.desktop")


def vscode_app():
    """Acceso de Visual Studio Code (None si no está instalado)."""
    for app_id in VSCODE_IDS:
        try:
            app = Gio.DesktopAppInfo.new(app_id)
        except (TypeError, GLib.Error):
            app = None
        if app is not None:
            return app
    return None


# Ancho de los campos del formulario de la pestaña Hosts (como los de Bases de datos)
COMBO_CHARS = 24


def narrow(combo, chars=COMBO_CHARS):
    """Desplegable de ancho fijo: los nombres largos se cortan con «…» en lugar de ensanchar
    toda la pestaña."""
    for cell in combo.get_cells():
        cell.set_property("ellipsize", 3)  # Pango.EllipsizeMode.END
        cell.set_property("width-chars", chars)
        cell.set_property("max-width-chars", chars)
    return combo


def host_switch_tip(h):
    """Lo que dice el interruptor de un dominio al dejar el ratón encima."""
    if h["name"].lower().endswith(".local"):
        return "Apagar este .local" if h["fake"] else "Encender este .local"
    return "Host falseado" if h["fake"] else "Falsear Host"


def hosts_view_text(hosts, path, vhosts, text):
    """Lo que enseña el visor del fichero de hosts: los dominios que se pueden falsear (los que tienen
    vhost, estén o no en el fichero) y, debajo, el fichero tal cual."""
    head = ["# DOMINIOS QUE SE PUEDEN FALSEAR (tienen vhost%s)" % (" en %s" % vhosts if vhosts else "")]
    states = []
    for h in hosts:
        local = h["name"].lower().endswith(".local")
        states.append(("encendido" if h["fake"] else "apagado") if local
                      else ("falseado" if h["fake"] else "sin falsear"))
    state_w = max([len(x) for x in states] or [0])
    name_w = max([len(h["name"]) for h in hosts] or [0])
    for h, state in zip(hosts, states):
        head.append("#   %s  %s  ->  %s" % (state.ljust(state_w), h["name"].ljust(name_w),
                                            h["folder"] or "sin carpeta"))
    if not hosts:
        head.append("#   (ninguno)")
    head += ["#", "# CONTENIDO DE %s" % path, ""]
    return "\n".join(head) + "\n" + text


def project_folders():
    """Carpetas de proyectos de /opt/htdocs (sin enlaces como web.local ni ocultas)."""
    try:
        return sorted((n for n in os.listdir(HTDOCS) if not n.startswith(".")
                       and not os.path.islink(os.path.join(HTDOCS, n))
                       and os.path.isdir(os.path.join(HTDOCS, n))), key=str.lower)
    except OSError:
        return []


def project_kind(folder):
    """ps (tienda PrestaShop, como is_prestashop del script), wp (WordPress) o vacío."""
    path = os.path.join(HTDOCS, folder)
    if "prestashop" in folder.lower() or os.path.isdir(os.path.join(path, "src/PrestaShopBundle")) \
            or os.path.isfile(os.path.join(path, "classes/PrestaShopAutoload.php")) \
            or os.path.isfile(os.path.join(path, "app/config/parameters.php")) \
            or os.path.isfile(os.path.join(path, "config/settings.inc.php")):
        return "ps"
    if os.path.isfile(os.path.join(path, "wp-config.php")) or \
            os.path.isdir(os.path.join(path, "wp-includes")):
        return "wp"
    return ""


# Lo que se hace con la configuración del proyecto al subirle una base nueva
PROJECT_CONFIG_TEXT = {
    "wp": "su wp-config.php se rehace con la plantilla de este equipo para usar esta BBDD",
    "ps": "su parameters.php (o settings.inc.php) pasa a usar esta BBDD y se vacía su caché",
}


def name_match_project(db, folders):
    """Carpeta que se llama como la base: wp_mitienda → wordpress-mitienda (la base
    sin wp_ ni ps_, al final del nombre). Si hay varias, la del mismo tipo (WordPress o tienda)."""
    low = db.lower()
    tails = {low}
    if low[:3] in ("wp_", "ps_") and len(low) > 3:
        tails.add(low[3:])
    hits = [f for f in folders if any(f.lower() == v or f.lower()[-len(v) - 1:] in
                                     ("-" + v, "." + v, "_" + v) for v in tails)]
    if len(hits) > 1 and low[:3] in ("wp_", "ps_"):
        hits = [f for f in hits if project_kind(f) == low[:2]] or hits
    return hits[0] if len(hits) == 1 else None


def guess_project(db, ver=None):
    """Carpeta del proyecto de una base: la vinculada (~/.lvm-instalador/proyectos; la de la
    versión, si se indica, manda sobre la de todas), la única cuya configuración la usa o la que se
    llama como la base. None si no se sabe o si en esa versión está desvinculada."""
    folders = project_folders()
    saved = per = None
    try:
        with open(PROJECTS_FILE, encoding="utf-8") as f:
            for line in f.read().splitlines():
                if line.startswith(db + "="):
                    saved = line.split("=", 1)[1]
                elif ver and line.startswith("%s@%s=" % (db, ver)):
                    per = line.split("=", 1)[1]
    except OSError:
        pass
    if per is not None:
        return per if per in folders else None
    if saved in folders:
        return saved
    users = [f for f in folders if project_db(f) == db]
    if len(users) == 1:
        return users[0]
    return name_match_project(db, folders)


def docker_status_text(status):
    """Estado de un contenedor en español: «Up 2 minutes» → «en marcha · 2 min»."""
    units = [(r"(\d+) seconds?", r"\1 s"), (r"Less than a second", "1 s"), (r"(\d+) minutes?", r"\1 min"),
             (r"About a minute", "1 min"), (r"About an hour", "1 h"), (r"(\d+) hours?", r"\1 h"),
             (r"(\d+) days?", r"\1 días"), (r"(\d+) weeks?", r"\1 semanas"), (r"(\d+) months?", r"\1 meses")]
    text = status
    for rx, rep_ in units:
        text = re.sub(rx, rep_, text)
    text = re.sub(r"\s*\((healthy|unhealthy|health: starting)\)", "", text)
    m = re.match(r"Up (.+)$", text)
    if m:
        return "en marcha · %s" % m.group(1)
    m = re.match(r"Exited \((\d+)\) (.+) ago$", text)
    if m:
        return "parado hace %s%s" % (m.group(2), "" if m.group(1) == "0" else " (error %s)" % m.group(1))
    return {"Created": "creado", "Restarting": "reiniciándose", "Paused": "en pausa"}.get(text.split(" ")[0], text)


def docker_slug(folder):
    """Nombre corto de un proyecto en Docker (como docker_slug del script)."""
    s = re.sub(r"[^a-z0-9]+", "-", folder.lower()).strip("-")[:40].rstrip("-")
    return s or "proyecto"


# Final de los dominios del Apache de Docker (gui-docker, W): docker.local o, con el DNS comodín, docker.test
DOCKER_TLD = ["docker.local"]


def docker_web_domain(p, v):
    """Dominio de una versión de PHP de un proyecto del Apache de Docker (docker_web_domain del script):
    el de la tienda (uno solo) o <proyecto>-php83.docker.local (o .docker.test)."""
    if p.get("kind") == "ps":
        return "%s.%s" % (p["slug"], DOCKER_TLD[0])
    return "%s-php%s.%s" % (p["slug"], v.replace(".", ""), DOCKER_TLD[0])


def docker_pma_domain():
    return "pma." + DOCKER_TLD[0]


def copy_name(db, php):
    """Nombre propuesto para la copia de una BBDD en otra versión: sin el sufijo de versión que
    traiga y con el de la de destino (wp_tienda_8_4 → wp_tienda_8_5)."""
    base = re.sub(r"[_-]\d+_\d+(_\d+)?$", "", db) or db
    name = "%s_%s" % (base, "_".join(php.split(".")[:2]))
    return name if len(name) <= 64 else db


def write_links(changes):
    """Guarda vínculos (base, versión, carpeta; carpeta vacía = ninguna) en
    ~/.lvm-instalador/proyectos, como base@versión=carpeta. Devuelve el error o None."""
    keys = {"%s@%s" % (db, ver) for db, ver, _ in changes}
    lines = []
    try:
        with open(PROJECTS_FILE, encoding="utf-8") as f:
            lines = [l for l in f.read().splitlines() if l and l.split("=", 1)[0] not in keys]
    except OSError:
        pass
    lines += ["%s@%s=%s" % c for c in changes]
    try:
        os.makedirs(LOG_DIR, mode=0o700, exist_ok=True)
        with open(PROJECTS_FILE + ".nuevo", "w", encoding="utf-8") as f:
            f.write("\n".join(lines) + "\n")
        os.replace(PROJECTS_FILE + ".nuevo", PROJECTS_FILE)
    except OSError as exc:
        return str(exc)
    return None


def project_db(folder):
    """Base de datos de la configuración de un proyecto (vacío si no tiene)."""
    for rel, rx in DB_RULES:
        path = os.path.join(HTDOCS, folder, rel)
        # Solo un fichero normal de hasta 2 MB, sin enlaces y sin esperar (un FIFO o un enlace a
        # /dev/zero de un proyecto colgarian la ventana)
        try:
            fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        except OSError:
            continue
        try:
            st = os.fstat(fd)
            if not stat.S_ISREG(st.st_mode) or st.st_size > 2000000:
                continue
            with os.fdopen(fd, errors="replace") as fh:
                fd = None
                m = re.search(rx, fh.read(2000000), re.M)
        except OSError:
            continue
        finally:
            if fd is not None:
                os.close(fd)
        if m:
            # Solo nombres de base validos (la configuracion la trae el proyecto)
            return m.group(1) if re.fullmatch(r"[A-Za-z0-9_][A-Za-z0-9_-]{0,63}", m.group(1)) else ""
    return ""


